(window.GIM_TS=window.GIM_TS||{})["Moed Katan.1"]={"from":24,"a":[["\u0003ו\u0004כן \u0003מנודה שהתירו לו חכמים, וכן מי ש\u0004נדר שלא לכבס ו\u0003נשאל לחכם והותר.\u0004","\u0003מטפחות הידים\u0004 (מגבות לידים) \u0003ו\u0004כן \u0003מטפחות הספרים,\u0004 שמניחים על המסתפר בשעת התספורת \u0003ומטפחות הספג\u0004 (מגבות לכל הגוף) שכל אלה מתלכלכות מהר, \u0003הזבין והזבות והנדות והיולדות, וכל\u0004 שאר \u0003העולין\u0004 (היוצאים) \u0003מטומאה לטהרה\u0004 בחול המועד \u0003הרי אלו מותרין\u0004 לכבס בגדיהם כדי לטהרם. \u0003ושאר כל אדם אסורין.\u0004","לגופה של ההלכה שואלים: \u0003ושאר כל אדם מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אסורין\u0004 לעשות דברים אלה במועד, שהרי לכאורה לצורך המועד הם!","ומשיבים: \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אנשי משמר\u0004 הכהנים העובדים במקדש במשך שבוע \u0003ואנשי מעמד\u0004 הישראלים הנלוים להם באותו שבוע \u0003אסורין\u0004 בשבוע זה \u0003לספר ולכבס,\u0004 אולם \u0003ב\u0004יום ה\u0003חמישי מותרין, מפני כבוד השבת.\u0004","\u0003ואמר רבה בר בר חנה אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור להם לספר ולכבס — \u0003כדי שלא יכנסו למשמרתן כשהן מנוולין\u0004 (מלוכלכים, בלתי מסודרים), שאם יתירו להם להסתפר בשבוע המשמר ידחו את התספורת, ונמצאים נכנסים לעבודתם בלתי מסודרים. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אסור להם להסתפר ולכבס בתוך הרגל \u0003כדי שלא יכנסו לרגל כשהן מנוולין,\u0004 ולכך יכינו עצמם לפני כן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: אבדה לו\u0004 לאדם \u0003אבידה ערב הרגל\u0004 והיה טרוד בחיפושים אחריה ולא הספיק להסתפר ולכבס, האם \u0003כיון דאניס\u0004 \u0005[ש\u0006הוא \u0005אנוס]\u0006 \u0003מותר\u0004 להסתפר ולכבס בחול המועד, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא מוכחא מילתא\u0004 \u0005[שאין הדבר מוכח]\u0006 \u0003לא\u0004 יתירו, שאין אונס זה נראה?","כתשובה לשאלה זו \u0003אמר אביי\u0004 בצטטו מה שאמרו חכמים כאשר אסרו לעשות מצות מקושטות לפסח, מפני החשש שמא ישתהו בקישוט ותחמיץ המצה. וכשרצה בייתוס בן זונין לעשות זאת באופן שלא יבוא לאיסור, התנגדו לו חכמים ואמרו שאם יתירו לו \u0003יאמרו\u0004 האנשים: \u0003כל הסריקין\u0004 (מצות מקושטות) \u0003אסורין, סריקי בייתוס מותרין?!\u0004 משמע שלא התירו חכמים במקרה מיוחד, כאשר הטעם לכך אינו ניכר.","ענה לו רבי זירא: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אסי אמר ר' יוחנן: כל מי שאין לו אלא חלוק אחד, מותר לכבסו בחולו של מועד — התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003יאמרו\u0004 כל החלוקים אסורים בכביסה בחול המועד, וחלוקו של זה מותר, כדרך שאמרו \u0003כל הסריקין אסורין, סריקי בייתוס מותרין!\u0004 שהלא אין זה ניכר שיש לו רק חלוק אחד!","ודוחים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר על כך],\u0006 \u0003אמר מר בר רב אשי: איזורו מוכיח\u0004 (חגורתו מוכיחה) \u0003עליו.\u0004 שכן אם יש לו רק חלוק אחד חייב בשעת הכביסה ללבוש בגד עליון ולחגור עצמו באיזורו והכל מבינים שאין לו חלוק אחר.","\u0003רב אשי מתני\u0004 \u0005[היה שונה]\u0006 סוגיה זו בלשון אחרת: \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: אומן שאבדה לו אבידה ערב הרגל\u0004 והיה טרוד בחיפוש אחריה, \u0003מהו?\u0004 האם הותר לו לכבס ולהסתפר בגלל זה בחול המועד, או לא? וצדדי הבעיה; \u0003כיון\u0004 ש\u0003אומן הוא מוכחא מילתא\u0004 \u0005[מוכח הדבר]\u0006 שהרי אנשים באים אליו לצורך מלאכתו, ורואים שהוא טרוד. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא מוכחא מילתא כי הנך\u0004 \u0005[שאין הדבר מוכח\u0006 וברור \u0005כמו באלה\u0006 שבמשנה\u0005]\u0006 \u0003לא\u0004 יתירו לו? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה שמי שבא \u0003ממדינת הים\u0004 בערב החג ולא הספיק להסתפר, מותר לו להסתפר בחול המועד. ומעירים: \u0003מתניתין\u0004 \u0005[\u0006שיטת \u0005משנתנו]\u0006 ש\u0003לא כר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: הבא ממדינת הים\u0004 — \u0003לא יגלח, מפני שיצא שלא ברשות,\u0004 כלומר, שלא יצא ברשות ובשליחות אחרים אלא על דעת עצמו, ומכיון שכן אין הוא נחשב כאנוס.","\u0003אמר רבא:\u0004 אם יצא מן הארץ \u0003לשוט\u0004 (לטייל) — \u0003דברי הכל אסור,\u0004 שכן מדעתו יצא ואין הדבר נחשב לו כאונס, ואם יצא \u0003למזונות\u0004 מפני דוחק הפרנסה, כיון שהוא אנוס — \u0003דברי הכל מותר, לא נחלקו אלא\u0004 שיצא \u0003להרויחא\u0004 \u0005[להרווחה],\u0006 שיש לו ממה לחיות אבל מוצא רווח גדול יותר בחוץ לארץ, \u0003מר מדמי ליה\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005מדמה אותו]\u0006 ומחשיבו \u0003כ\u0004זה שיצא \u0003לשוט\u0004 (לטייל), \u0003ומר מדמי ליה\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005מדמה אותו]\u0006 ומחשיבו \u0003כ\u0004זה שיצא \u0003למזונות.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 מברייתא, \u0003אמר רבי: נראין דברי ר' יהודה כשיצא שלא ברשות, ודברי חכמים כשיצא ברשות,\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שלא ברשות? אילימא\u0004 \u0005[אם תאמר]\u0006 שיצא \u0003לשוט\u0004 — \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 שבמקרה זה \u0003דברי הכל אסור, ואלא\u0004 תאמר שיצא \u0003למזונות — והאמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003דברי הכל מותר! אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא שיצא \u0003להרויחא\u0004 \u0005[להרויח\u0006 יותר\u0005].\u0006","על הוכחה זו מקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 הברייתא\u0005]:\u0006 \u0003נראין דברי חכמים כשיצא ברשות,\u0004 ונברר שוב \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ברשות? אילימא\u0004 \u0005[אם תאמר]\u0006 שיצא \u0003למזונות — הא אמרת\u0004 \u0005[הרי אמרת]\u0006 \u0003דברי הכל מותר, ואלא להרויחא\u0004 \u0005[להרווחה] —\u0006 \u0003והא אמרת\u0004 \u0005[הרי אמרת]\u0006 \u0003נראין דברי ר' יהודה\u0004 לחכמים \u0003בהא\u0004 \u0005[בזה],\u0006 ונוצרת איפוא סתירה!","ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003נראין דברי ר' יהודה לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003כשיצא שלא ברשות ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 הפירוש של \"יצא שלא ברשות\" — \u0003לשוט, שאפילו חכמים לא נחלקו עליו אלא\u0004 כשיצא \u0003להרויחא\u0004 \u0005[להרווחה]\u0006 \u0003אבל לשוט — מודו ליה\u0004 \u0005[מודים לו]\u0006 שאם יצא אסור לו לגלח. \u0003ונראין דברי רבנן\u0004 \u0005[חכמים]\u0006 \u0003לר' יהודה כשיצא ברשות, ומאי ניהו\u0004 \u0005[ומה הוא] —\u0006 \u0003למזונות, שאפילו ר' יהודה לא נחלק עליהם אלא להרויחא\u0004 \u0005[להרווחה],\u0006 \u0003אבל למזונות מודה להו\u0004 \u0005[להם],\u0006 ונתיישבה על ידי כך הסתירה, ודברי רבי לא באו להכריע בין שיטת חכמים ור' יהודה אלא רק להכריע את מחלוקתם.","\u0003אמר שמואל: קטן הנולד במועד\u0004 והיו לו שערות ארוכות המצערות אותו — \u0003מותר לגלח\u0004 אותו \u0003ב\u0004חול ה\u0003מועד, שאין לך בית האסורין גדול מזה\u0004 מרחם אמו שהיה בו ובגלל זה לא היה יכול לגלח קודם המועד. ומדייקים בלשונו: אם נולד התינוק \u0003במועד — אין\u0004 \u0005[כן]\u0006 אבל אם נולד \u0003מעיקרא\u0004 \u0005[קודם,\u0006 לפני החג\u0005]\u0006 ומשום מה לא גילחו אותו — \u0003לא,\u0004 אסור לגלח אותו בחג, שכן היתה להם שהות קודם לכן.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003ר' פנחס\u0004 ממה ששנינו: \u0003כל אלו שאמרו מותר לגלח במועד — מותר לגלח\u0004 גם \u0003בימי אבלו.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 מי ש\u0003אסור לגלח במועד — אסור לגלח בימי אבלו.\u0004"],["\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003קטן אית ביה פלוגתא\u0004 \u0005[יש בו חילוק]\u0006 בין נולד קודם המועד לנולד לאחריו ואיסור גילוח נוהג במקרים מסויימים גם בתינוק — אם כן \u0003נמצאת אבילות נוהגת\u0004 גם \u0003בקטן.\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מקרעין לקטן,\u0004 כלומר, קורעים גם את בגדי הקטן שאירע אבל במשפחתו \u0003מפני עגמת נפש\u0004 כדי שהרואים יצטערו, כאילו אף הקטן משתתף כבר באבל, אולם מצד הדין אין אבילות חלה על הקטן!","\u0003אמר רב אשי:\u0004 אין זו קושיה, \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 במפורש \u0003הא\u0004 \u0005[הרי]\u0006 אלה ה\u0003אסורין\u0004 לגלח במועד אסורים לעשות כן גם בימי אבלם! הרי למדנו זאת רק בדרך הדיוק, ואפשר גם לדייק אחרת: \u0003דלמא\u0004 \u0005[שמא]\u0006 הדברים האסורים במועד \u0003יש מהן אסור ויש מהן מותר\u0004 באבילות, ובתינוק אף שישנם דברים שהוא אסור בהם בחול המועד, מכל מקום אין אבילות נוהגת בו.","\u0003אמימר ואי תימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי מתני הכי\u0004 \u0005[היה שונה\u0006 שמועה זו \u0005כך,\u0006 בנוסח אחר\u0005].\u0006 \u0003אמר שמואל: קטן מותר לגלחו ב\u0004חול ה\u0003מועד, לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003שנולד במועד ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם \u0003נולד מעיקרא\u0004 \u0005[מתחילה]\u0006 קודם המועד.","\u0003אמר רב פנחס: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 בברייתא סיוע לכך; \u0003כל אלו שאמרו מותר לגלח במועד — מותר לגלח בימי אבלו, הא\u0004 \u0005[הרי]\u0006 אלה ש\u0003אסורין לגלח במועד — אסורין\u0004 גם \u0003לגלח בימי אבלו.\u0004","\u0003אי אמרת\u0004 \u0005[\u0006ו\u0005אם אומר אתה]\u0006 ש\u0003קטן אסור\u0004 בגילוח במועד, \u0003נמצאת\u0004 למד מן ההשוואה כי \u0003אבילות נוהגת בקטן. ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003מקרעין לקטן מפני עגמת נפש\u0004 ורק מפני טעם זה, ולא מחמת שדיני אבלות חלים עליו.","\u0003אמר רב אשי\u0004 לדחות ראיה זו: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 במפורש \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אסורין? דלמא\u0004 \u0005[שמא]\u0006 \u0003יש מהן אסור, ויש מהן מותר,\u0004 ואם כן אין מכאן ראיה גמורה לא לצד זה ולא לצד אחר.","\u0003אבל אינו נוהג אבילותו ברגל,\u0004 שברגל בטלה ממנו אבילות, \u0003שנאמר: \"ושמחת בחגך\"\u0004 (דברים טז, יד).","ומסבירים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003אבילות דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003הוא,\u0004 שכבר התחילה קודם הרגל — אנו אומרים ש\u0003אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה\u0004 של שמחת החג החל על ה\u0003רבים ודחי\u0004 \u0005[ודוחה]\u0006 מצות \u0003עשה\u0004 של ה\u0003יחיד\u0004 להתאבל. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אבילות דהשתא\u0004 \u0005[של עכשיו]\u0006 \u0003הוא,\u0004 שאירע המוות בתוך הרגל, אנו אומרים בסגנון אחר קצת: \u0003לא אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה\u0004 של \u0003יחיד\u0004 של אבל \u0003ודחי\u0004 \u0005[ודוחה]\u0006 מצות \u0003עשה\u0004 של ה\u0003רבים —\u0004 שמחת יום טוב.","שואלים: \u0003מנודה, מהו שינהוג נדויו ברגל\u0004 או שמא מפני שמחת הרגל נדחה הנידוי? \u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: \u0003דנין\u0004 גם בחול המועד \u0003דיני נפשות, ודיני מכות, ודיני ממונות,\u0004 והרי אנו יודעים \u0003ואי לא ציית דינא\u0004 \u0005[אם\u0006 אדם \u0005איננו מציית לדין]\u0006 הרי בין שאר אמצעי הכפיה \u0003משמתינן ליה\u0004 \u0005[מנדים אנו אותו]\u0006 עד שיקבל עליו את פסק הדין,","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003אינו נוהג נדויו ברגל,\u0004 אם כן הרי כאן קל וחומר: שהרי אם לזה ה\u0003משומת ואתי מעיקרא\u0004 \u0005[מנודה ובא מתחילה]\u0006 \u0003אתי רגל דחי ליה\u0004 \u0005[בא הרגל\u0006 ו\u0005דוחה אותו]\u0006 \u0003השתא משמתינן ליה אנן\u0004 \u0005[עכשיו\u0006 האם נכון יהיה ש\u0005ננדה אותו אנחנו]\u0006 לכתחילה ביום טוב?! ולכן מובן מכאן כי נידוי אינו מפסיק וממשיך לנהוג ואף מנדים מלכתחילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו ראייה, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מה ששנינו כי דנים דינים במועד הכוונה היא רק \u0003לעיוני בדיניה\u0004 \u0005[לעיין בדינו]\u0006 בלא לגזור דין \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שמדובר רק בעיון בדין, \u0003דיני נפשות דקתני\u0004 \u0005[ששנינו],\u0006 \u0003הכי נמי דקטלין ליה\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שהורגים אותו\u0006 במועד\u0005]?\u0006","אם כן \u0003הא קא מימנעי\u0004 \u0005[הרי\u0006 הדבר גורם שהדיינים \u0005נמנעים]\u0006 \u0003משמחת יום טוב,\u0004 כיצד — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: מנין לסנהדרין שהרגו את הנפש\u0004 כלומר, שדנו אדם למוות, \u0003שאין טועמין\u0004 דבר \u0003כל אותו היום — תלמוד לומר: \"לא תאכלו על הדם\"\u0004 (ויקרא יט, כו), שאין זה ראוי לאכול באותו יום שבו גרמו לשפיכות דמים.","ואם כן מה שנאמר שדנים דיני נפשות בחול המועד אינו \u0003אלא לעיוני בדיניה\u0004 \u0005[לעיין בדינו],\u0006 \u0003הכא נמי לעיוני בדיניה\u0004 \u0005[כאן\u0006 בדיני ממונות ומכות \u0005גם כן\u0006 כוונת הדברים \u0005לעיין בדינו]\u0006 בלא נידוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אם כן\u0004 לפי הסברך, שרק מעיינים ולא פוסקים בדיני נפשות \u0003נמצאת מענה את דינו\u0004 שהנאשם מתענה על ידי ספק וחשש עד לאחר החג!","אלא כך יש לעשות: \u0003אתו מצפרא ומעייני בדיניה\u0004 \u0005[באים\u0006 הדיינים \u0005בבוקר\u0006 כרגיל \u0005ומעיינים בדינו]\u0006 \u0003ועיילי ואכלי ושתו כולי יומא\u0004 \u0005[ונכנסים\u0006 לביתם \u0005ואוכלים ושותים כל היום]\u0006 כל צרכם, \u0003והדר אתו\u0004 \u0005[וחוזרים ובאים]\u0006 לבית דין סמוך ל\u0003שקיעת החמה וגמרינן לדיניה וקטלו ליה\u0004 \u0005[וגומרים את דינו והורגים אותו]\u0006 ואינם צריכים להתענות באותו יום, שהרי יום זה נגמר מיד אחר השקיעה.","\u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה אחרת, ממה ששנינו: \u0003ומנודה שהתירו לו חכמים\u0004 להסתפר בחול המועד, משמע שאמרו חכמים שאין דין מנודה ברגל!","ודוחים: \u0003אמר רבא: מי קתני\u0004 \u0005[האם שנינו]\u0006 \u0003\"שהתירוהו חכמים\",\u0004 ללמד שחכמים התירו בכלל למנודה? כאן \u0003\"שהתירו לו חכמים\" קתני\u0004 \u0005[שנינו],\u0006 שאין זה דין כללי אלא מקרה פרטי \u0003דאזל ופייסיה לבעל דיניה, ואתי קמי דרבנן, ושרו ליה\u0004 \u0005[שהלך ופייס את בעל\u0006 \u0005דינו, ובא לפני חכמים, והתירו לו\u0006 את הנידוי\u0005].\u0006","עוד שאלה דומה: \u0003מצורע, מהו שינהיג\u0004 כל דיני \u0003צרעתו ברגל? אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003והנזיר והמצורע\u0004 כשיוצא במועד \u0003מטומאתו לטהרתו\u0004 מגלח. ונדייק: \u0003הא\u0004 \u0005[הרי],\u0006 משמע שאת \u0003ימי טומאתו נהיג\u0004 \u0005[\u0006הוא \u0005נוהג]\u0006 ואין טומאתו בטלה ברגל.","ודוחים: אפשר לומר כי בסגנון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר ש\u0003בימי טומאתו דלא נהיג\u0004 \u0005[שאינו נוהג],\u0006 \u0003אבל לטהרתו\u0004 אם נתרפאה הצרעת \u0003ניגזור\u0004 שלא יגלח במועד \u0003שמא ישהה קרבנותיו\u0004 ולא יזדרז בהבאתם, שלא תהא לו סיבה למהר ולהטהר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא גזרו!","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במדרש הלכה על הכתוב \u0003\"והצרוע\u0004 אשר בו הנגע בגדיו יהיו פרומים...\u0003\"\u0004 (ויקרא יג, מה), ומהדגשה יתירה זו של \"והצרוע\" למדים \u0003לרבות כהן גדול,\u0004 שכל דיני מצורע נוהגים בו אם הצטרע. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כהן גדול\u0004 ש\u0003כל השנה כ\u0004מו \u0003רגל לכולי עלמא דמי\u0004 \u0005[לכל העולם,\u0006 לכול הוא \u0005נחשב],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כהן גדול מקריב\u0004 גם כשהוא \u0003אונן\u0004 (בו ביום שמת לו מת) \u0003ו\u0004אולם \u0003אינו אוכל\u0004 קדשים. הרי שבטל דין אוננות מן הכהן הגדול כמו אצל אדם אחר בימי הרגל, ובכל זאת נוהג בו דין צרעת, אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 לגבי כל אדם ש\u0003נוהג צרעתו ברגל.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 שכן הוא\u0005].\u0006","ומעתה — לבירור מקורות הדינים ועיקרם. \u0003אבל אסור בתספורת,\u0004 וכיצד אנו יודעים זאת — \u0003מדקאמר להו רחמנא\u0004 \u0005[ממה שאמר להם הקדוש ברוך הוא]\u0006 \u0003לבני אהרן: \"ראשיכם אל תפרעו\"\u0004 (ויקרא י, ו), כלומר, אסור להם לגדל שער פרע בזמן שצריכים להיות אבלים על אחיהם שמתו, \u0003מכלל\u0004 הדברים אתה למד \u0003דכולי עלמא\u0004 \u0005[שלכל העולם]\u0006 \u0003אסור\u0004 להסתפר, וצריכים לפרוע שערם."],["שואלים: \u0003מנודין ומצורעין מה הן בתספורת? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא: \u0003מנודין ומצורעין אסורין לספר ולכבס.\u0004","ועוד שנו שם: \u0003מנודה שמת — בית דין סוקלין את ארונו. ר' יהודה אומר: לא שיעמידו עליו גל אבנים כגלו של עכן\u0004 בסקילה של ממש, \u0003אלא בית דין שולחין ומניחין אבן גדולה על ארונו\u0004 שתשמש כסמל, \u0003ללמדך: שכל המתנדה ומת בנידויו\u0004 ולא ביקש היתר לנידויו, \u0003בית דין סוקלין את ארונו.\u0004","ועוד: \u0003אבל חייב בעטיפת הראש\u0004 לכסות פניו וראשו, ולמדים זאת \u0003מדקאמר ליה רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמר לו הקדוש ברוך הוא]\u0006 \u0003ליחזקאל\u0004 באבלו: \u0003\"ולא תעטה על שפם\"\u0004 (יחזקאל כד, יז), שלא יראה סימני אבל, ו\u0003מכלל\u0004 הדברים אתה למד \u0003דכולי עלמא מיחייבי\u0004 \u0005[שכל העולם,\u0006 הכול \u0005חייבים]\u0006 בכך.","ושואלים: \u0003מנודה מהו בעטיפת הראש? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו על המתענים על הגשם ולא נשמעה בקשתם: \u0003והן מתעטפין ויושבין כמנודין וכאבלים עד שירחמו עליהם מן השמים.\u0004 משמע שהמנודים מתעטפים כמו האבלים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 \u0003מנודה לשמים שאני\u0004 \u0005[שונה]\u0006 \u0003דחמיר\u0004 \u0005[ש\u0006הוא \u0005חמור]\u0006 יותר ממנודה על ידי בית דין.","ושואלים עוד: \u0003מצורע מהו בעטיפת הראש? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שנאמר: \u0003\"ועל שפם יעטה\"\u0004 (ויקרא יג, מה), \u0003מכלל\u0004 הדברים אתה למד \u0003שחייב בעטיפת הראש,\u0004 שמשמעות \"יעטה\" היא התעטפות. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ועוד בירור הלכה: \u0003אבל אסור להניח תפילין, מדקאמר ליה רחמנא\u0004 \u0005[ממה שאמר לו הקדוש ברוך הוא]\u0006 \u0003ליחזקאל\u0004 באבלו, שבאופן יוצא מן הכלל \u0003\"פארך חבוש עליך\"\u0004 (יחזקאל כד, יז), ואנו מבינים ש\"פאר\" זה הוא כינוי לתפילין, \u0003מכלל\u0004 הדברים אתה למד \u0003דכולי עלמא\u0004 \u0005[שכל העולם]\u0006 \u0003אסור\u0004 בתפילין בעת אבל.","ושואלים: \u0003מנודה מהו בתפילין?\u0004 לשאלה זו לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה. ושואלים עוד: \u0003מצורע מהו בתפילין?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראייה מברייתא הדורשת על מה שכתוב \u0003\"והצרוע\"\u0004 (ויקרא יג, מה) שהוא לשון ריבוי — \u0003לרבות כהן גדול\u0004 לכל דיני מצורע, ונאמר שם: \u0003\"בגדיו יהיו פרמים\"\u0004 פירושו — \u0003שיהו מקורעים, \"וראשו יהיה פרוע\" — אין פריעה\u0004 זו \u0003אלא גידול שער,\u0004 אלו \u0003דברי ר' אליעזר.\u0004","\u0003ר' עקיבא אומר:\u0004 לומדים גזירה שווה, \u0003נאמרה \"הוייה\" בראש\u0004 (\"ראשו יהיה\"), כלומר, נאמר שיעשה מעשה מסויים בראש, \u0003ונאמרה \"הוייה\" בבגד\u0004 (\"בגדיו יהיו\"), \u0003מה הוייה האמורה בבגד\u0004 פירושה שעושה \u0003דבר שחוץ מגופו, אף הוייה בראש — דבר שחוץ מגופו. מאי לאו\u0004 \u0005[האם לא]\u0006 המדובר הוא על \u0003תפילין,\u0004 שאסור לו להניח תפילין!","\u0003אמר רב פפא: לא,\u0004 אין להוכיח מכאן, כי אפשר לפרש שמדובר \u0003אכומתא וסודרא\u0004 \u0005[על כובע וסודר]\u0006 שאנשים חובשים על ראשם, ואפשר לפרש שלדעת ר' עקיבא אסור דבר זה למצורע, משום שיש בו הידור יתר.","ונושא נוסף: \u0003אבל אסור בשאילת שלום\u0004 שאיננו שואל בשלום אחרים ואין שואלים בשלומו. ודבר זה נלמד ממה \u0003דקאמר ליה רחמנא\u0004 \u0005[שאמר לו הקדוש ברוך הוא]\u0006 \u0003ליחזקאל: \"האנק דם\"\u0004 (יחזקאל כד, יז), משמע שחייב לשתוק ואסור בדיבור בלתי הכרחי.","ושואלים: \u0003מנודה מהו בשאילת שלום? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר על המתענים על הגשמים שלא נענו בתפילתם, שהם אסורים \u0003בשאילת שלום שבין אדם לחבירו כבני אדם הנזופין למקום. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דלמא\u0004 \u0005[שמא]\u0006 \u0003מנודה לשמים שאני דחמיר\u0004 \u0005[שונה ש\u0006הוא \u0005חמור]\u0006 ממנודה אחר.","ושואלים עוד: \u0003מצורע מהו בשאילת שלום?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר: \u0003\"ועל שפם יעטה\"\u0004 (ויקרא יג, מה), ודרשוהו: \u0003שיהו שפתותיו מדובקות זו בזו, שיהא כמנודה וכאבל, ואסור בשאילת שלום.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמצורע אסור בשאילת שלום, ושואלים: אם כן,","\u0003וניפשוט מינה\u0004 \u0005[ונפתור מכאן],\u0006 מן המקור הזה, גם \u0003ל\u0004ענין ה\u0003מנודה\u0004 שאף הוא אסור בשאילת שלום! \u0003אמר רב אחא בר פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יוסף: מי קתני\u0004 \u0005[האם שנינו\u0006 במפורש\u0005]\u0006 במצורע \u0003שאסור\u0004 הוא בשאילת שלום? הלא רק \u0003שיהא כמנודה וכאבל קתני\u0004 \u0005[שנינו],\u0006 והכוונה: \u0003במילי אחרנייתא\u0004 \u0005[בדברים אחרים]\u0006 הרי הוא כמנודה וכאבל, \u0003ואסור נמי\u0004 \u0005[גם כן]\u0006 \u0003בשאילת שלום,\u0004 ואם כן אין ללמוד מכאן למנודה.","ועוד נושא: \u0003אבל אסור בדברי תורה,\u0004 ודבר זה נלמד \u0003מדקאמר רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמר הקדוש ברוך הוא]\u0006 \u0003ליחזקאל:\u0004 \"האנק \u0003דם\"\u0004 (יחזקאל כד, יז) משמע: שתוק ואל תדבר אפילו בדברי תורה.","ושואלים: \u0003מנודה מהו בדברי תורה? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מנודה שונה\u0004 (מלמד תורה) \u0003ושונין לו, נשכר\u0004 לעבודה \u0003ונשכרין לו.\u0004","\u0003מוחרם\u0004 שהוא נידוי חמור יותר — \u0003לא שונה ולא שונין לו, לא נשכר ולא נשכרין לו, אבל שונה הוא לעצמו\u0004 כדי \u0003שלא יפסיק\u0004 לגמרי \u0003את למודו\u0004 וישכח הכל, \u0003ועושה לו חנות קטנה בשביל פרנסתו\u0004 כדי חיים בלבד ולא יותר.","\u0003ואמר רב:\u0004 מהי חנות קטנה כעין זו — כגון \u0003זבוני מיא\u0004 \u0005[מכירת מים]\u0006 \u0003ב\u0004מקום \u0003פקתא\u0004 \u0005[בקעה,\u0006 שדה\u0005]\u0006 \u0003דערבות\u0004 שלא היו שם מים, ומוכר המים עשוי להרויח מזה מעט מאד. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמנודה מותר בדברי תורה.","ושואלים עוד: \u0003מצורע מהו בדברי תורה?\u0004 ומביאים ראייה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו, נאמר: \u0003\"...והודעתם לבניך ולבני בניך. יום אשר עמדת לפני ה' אלהיך בחרב\"\u0004 (דברים ד, ט-י), \u0003מה להלן\u0004 כשקיבלו את התורה היה זה \u0003באימה וביראה וברתת\u0004 (ברעדה) \u0003ובזיעה\u0004 (זעזוע) מחמת האימה,","\u0003מכאן אמרו: הזבין, והמצורעין, ובועלי נדות\u0004 אף על פי שהם טמאים — \u0003מותרין לקרות בתורה ובנביאים ובכתובים, ולשנות במדרש ובתלמוד בהלכות ובאגדות. ובעלי קריין — אסורין,\u0004 משום שטומאתם באה להם על ידי יצר ואין בכך אימה ויראה. ומסכמים: אכן, \u0003שמע מינה\u0004 (למד מכאן).","ונושא אחר: \u0003אבל אסור בתכבוסת, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישלח יואב תקועה ויקח משם אשה חכמה ויאמר אליה התאבלי נא ולבשי נא בגדי אבל ואל תסוכי שמן והיית כאשה זה ימים רבים מתאבלת על מת\"\u0004 (שמואל ב' יד, ב).","ושואלים: \u0003מנודין ומצורעין מה הן בתכבוסת? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במפורש: \u0003מנודין ומצורעין אסורין לספר ולכבס.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אבל חייב בקריעה,\u0004 ודבר זה נלמד ממה \u0003דקאמר להו רחמנא\u0004 \u0005[שאמר להם הקדוש ברוך הוא]\u0006 \u0003לבני אהרן: \"לא תפרמו\"\u0004 (ויקרא י, ו), \u0003מכלל\u0004 הדברים אתה למד \u0003דכולי עלמא מיחייבי\u0004 \u0005[שכל העולם,\u0006 אבלים אחרים, \u0005מחוייבים]\u0006 בקריעה.","ושואלים עוד: \u0003מנודה מהו בקריעה?\u0004 לשאלה זו לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ומוסיפים לשאול: \u0003מצורע מהו בקריעה? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 נאמר: \u0003\"בגדיו יהיו פרמים\"\u0004 (ויקרא יג, מה), ופירושו: \u0003שיהו מקורעין,\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","ועוד: \u0003אבל חייב בכפיית המטה\u0004 שהוא הופך את המיטה וישן על גבה, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003בר קפרא:\u0004"],["\u0003דמות דיוקני נתתי בהן\u0004 בבני אדם, שנבראו בצלם אלהים \u0003ובעונותיהם הפכתיה,\u0004 שמת אותו אדם ובטלה דמות אלהים שבו — \u0003כפו\u0004 \u0005[הפכו]\u0006 אף אתם \u0003מטותיהן עליה.\u0004 ושואלים: \u0003מנודה ומצורע מה הן בכפיית המטה?\u0004 לשאלה זו לא נמצאה תשובה והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד, \u0003אבל אסור בעשיית מלאכה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והפכתי חגיכם לאבל\"\u0004 (עמוס ח, י), ונלמד: \u0003מה חג אסור במלאכה — אף אבל אסור במלאכה.\u0004","ושואלים: \u0003מנודה מהו בעשיית מלאכה? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו: \u0003כשאמרו\u0004 שבתעניות אחרונות של גשמים \u0003אסור בעשיית מלאכה — לא אמרו אלא ביום, אבל בלילה — מותר. וכן אתה מוצא במנודה ובאבל. מאי לאו אכולהו\u0004 \u0005[האם לא\u0006 נאמר הדבר \u0005על הכל],\u0006 כלומר, על כל דיני האבילות, שהם דומים לדיני הנידוי? ודוחים: \u0003לא, אשארא\u0004 \u0005[על השאר]\u0006 ולא לענין מלאכה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממקור אחר, ששנינו: \u0003מנודה שונה ושונין לו, נשכר\u0004 לעבודה אצל אחרים \u0003ו\u0004אחרים \u0003נשכרין לו, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהמנודה מותר בעשיית מלאכה. ושואלים עוד: \u0003מצורע מהו בעשיית מלאכה?\u0004 לשאלה זו לא נמצאה תשובה, והושארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","יודעים אנו כי \u0003אבל אסור ברחיצה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואל תסוכי שמן\u0004 והיית כאשה זה ימים רבים מתאבלת על מת\u0003\"\u0004 (שמואל ב' יד, ב), \u0003ורחיצה בכלל סיכה\u0004 היא, שסיכה ורחיצה מטרתן ועניינן אחד.","ושואלים: \u0003מנודה מהו ברחיצה? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו: \u0003כשאמרו\u0004 בתענית ציבור ש\u0003אסור ברחיצה — לא אמרו אלא\u0004 רחיצת \u0003כל גופו, אבל פניו ידיו ורגליו — מותר, וכן אתה מוצא במנודה ובאבל. מאי לאו אכולהו\u0004 \u0005[האם לא\u0006 מדובר \u0005על כולם]\u0006 בהשוואת כל הדינים של מנודה לאבל? ודוחים: \u0003לא, אשארא\u0004 \u0005[על שאר\u0006 הדינים\u0005]\u0006 ולא לענין רחיצה. ומוסיפים לשאול: \u0003מצורע מהו ברחיצה?\u0004 וגם שאלה זו נשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","אנו יודעים ש\u0003אבל אסור בנעילת הסנדל,\u0004 ודבר זה למדים אנו \u0003מדקאמר ליה רחמנא\u0004 \u0005[מ\u0006מה \u0005שאמר לו הקדוש ברוך הוא]\u0006 \u0003ליחזקאל\u0004 באבלו שישנה מן המנהג המקובל \u0003\"ונעליך תשים ברגליך\"\u0004 (יחזקאל כד, יז), \u0003מכלל\u0004 הדברים אתה למד \u0003דכולי עלמא\u0004 \u0005[שלכל העולם]\u0006 מלבד יחזקאל \u0003אסור.\u0004","ושואלים: \u0003מנודה מהו בנעילת הסנדל? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו: \u0003כשאמרו\u0004 שבתענית ציבור \u0003אסור בנעילת הסנדל — לא אמרו אלא\u0004 בלכתו \u0003בעיר, אבל בדרך\u0004 מחוץ לעיר — \u0003מותר. הא כיצד? יצא לדרך — נועל\u0004 את נעליו, \u0003נכנס לעיר — חולץ, וכן אתה מוצא במנודה ובאבל. מאי לאו אכולהו\u0004 \u0005[האם\u0006 השוואה זו בין המנודה לאבל \u0005לא\u0006 מדברת \u0005על כולם],\u0006 על כל הדינים? ודוחים: \u0003לא, אשארא\u0004 \u0005[על השאר]\u0006 מלבד נעילת הסנדל.","ושואלים עוד: \u0003מצורע מהו בנעילת הסנדל?\u0004 אף שאלה לא נמצאה לה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","אנו יודעים כי \u0003אבל אסור בתשמיש המטה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וינחם דוד את בת שבע אשתו ויבא אליה\"\u0004 (שמואל ב' יב, כד) לאחר שמת בנם, ו\u0003מכלל\u0004 הדברים אתה למד \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 בזמן האבל \u0003אסור.\u0004","ושואלים: \u0003מנודה מהו בתשמיש המטה? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כל אותן שנים שהיו ישראל במדבר מנודין היו, ו\u0004הרי אנחנו יודעים ש\u0003שימשו מטותיהן,\u0004 שהרי נולדו להם ילדים במשך הזמן, הרי שהמנודה מותר בתשמיש המיטה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מנודה לשמים שאני\u0004 \u0005[שונה]\u0006 \u0003דקיל\u0004 \u0005[ש\u0006דינו \u0005קל]\u0006 ממי שנודה על ידי בית דין של מטה.","על דברי אביי תוהים: \u0003קיל\u0004 \u0005[קל]\u0006 הוא?! \u0003והא אמרת חמיר\u0004 \u0005[והרי\u0006 אתה עצמך \u0005אמרת\u0006 מקודם שהמנודה לשמים \u0005חמור\u0006 יותר\u0005],\u0006 ומטעם זה הלא דחה אביי את דברי רב יוסף כשרצה ללמוד מברייתא זו! ומשיבים: \u0003ספוקי מספקא ליה\u0004 \u0005[מסופק לו\u0006 לאביי הדבר\u0005]\u0006 מה דינו של מנודה לשמים אם הוא קל או חמור, ולכן \u0003זיל הכא קמדחי ליה וזיל הכא קמדחי ליה\u0004 \u0005[לך לכאן הוא דוחה אותו, ולך לכאן הוא דוחה אותו],\u0006 שסבור שכיון שאין הדבר ברור, אין להביא ממנו ראיה לכל ענין.","ומוסיפים לשאול: \u0003מצורע מהו בתשמיש המטה? תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 נאמר במצורע: \u0003\"וישב מחוץ לאהלו\"\u0004 (ויקרא יד, ח), ולמדים מזה \u0003שיהא\u0004 המצורע \u0003כמנודה וכאבל, ואסור בתשמיש המטה.\u0004 וכיצד למדים זאת? כי \u0003אין \"אהלו\" אלא\u0004 רמז וכינוי ל\u0003אשתו, שנאמר\u0004 לאחר מתן תורה: \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז), שהתיר להם לשוב להיות עם נשותיהם, לאחר שנאסרו בכך לפני מתן תורה (\"אל תגשו אל אשה\". שמות יט, טו). ומסכמים: אכן, \u0003שמע מינה\u0004 שהמצורע אסור בתשמיש המיטה.","ושואלים: \u0003ונפשוט נמי\u0004 \u0005[ונפתור\u0006 מכאן \u0005גם כן]\u0006 את הבעייה ביחס \u0003למנודה? אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יוסף: מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003שאסור\u0004 המצורע בתשמיש כמנודה? נאמר רק \u0003שיהא כמנודה וכאבל במילי אחרנייתא\u0004 \u0005[בדברים אחרים],\u0006 \u0003ואסור נמי\u0004 \u0005[גם כן]\u0006 \u0003בתשמיש המטה.\u0004","אנו יודעים כי \u0003אבל אינו משלח קרבנותיו\u0004 לבית המקדש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 קרבן \u0003שלמים\u0004 נקרא כך גם כדי ללמדנו שאדם מביא אותו \u0003בזמן שהוא שלם\u0004 ודעתו שלימה ומיושבת, \u0003ולא בזמן שהוא אונן\u0004 (ביום הראשון לאבלו), שהוא בצער.","ושואלים: \u0003מנודה מהו שישלח קרבנותיו? אמר רב יוסף, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003כל אותן שנים שהיו ישראל במדבר מנודין היו, ושלחו קרבנותיהן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ודלמא מנודה לשמים שאני\u0004 \u0005[שונה]\u0006 \u0003דקיל\u0004 \u0005[ש\u0006דינו \u0005קל]\u0006 יותר ממנודה על ידי בית דין?","ותוהים: \u0003קיל\u0004 \u0005[קל\u0006 הוא\u0005]?!\u0006 \u0003והאמרת חמיר\u0004 \u0005[והרי\u0006 אתה עצמך \u0005אמרת\u0006 שהוא \u0005חמור]?\u0006 ומשיבים: \u0003ספוקי מספקא ליה ומדחי ליה\u0004 \u0005[מסופק\u0006 לו הדבר, \u0005ומדחה אותו\u0006 לכאן ולכאן\u0005].\u0006","ושואלים עוד: \u0003מצורע מהו שישלח קרבנותיו?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 נאמר בענין כהן שנטמא: \"ואחרי טהרתו שבעת ימים יספרו לו\" (יחזקאל מד, כו), ומפרשים: \u0003\"ואחרי טהרתו\" — אחר פרישתו מן המת, \"שבעת ימים יספרו לו\" — אלו שבעת ימי ספירו\u0004 שסופר עד גמר טהרתו, \u0003\"וביום באו אל הקדש אל החצר הפנימית לשרת בקדש יקריב חטאתו\"\u0004 (יחזקאל מד, כז)"],["\u0003זו עשירית האיפה שלו,\u0004 שמביא כל כהן ביום שבו הוא מתחיל לעבוד במקדש, אלו \u0003דברי ר' יהודה.\u0004 ומתוך שנקט הפסוק בלשון ספירה (\"יספרו לו\"), ולא בלשון הזאה, יש ללמוד זאת גם לענין המצורע שטהרתו תלויה בספירה ולא בהזאה.","\u0003ר' שמעון אומר:\u0004 מן הכתוב \u0003\"\u0004וביום \u0003באו\u0004 אל הקודש אל החצר הפנימית לשרת בקודש \u0003יקריב\"\u0004 (יחזקאל מד, כז) למדים אנו: \u0003בזמן שראוי לביאה — ראוי להקרבה, בזמן שאינו ראוי לביאה\u0004 בזמן טומאתו — \u0003אינו ראוי להקרבה.\u0004 ואם כן למדנו שהמצורע אינו יכול לשלח קרבנותיו להקרבה, שהרי אינו רשאי להכנס למקדש.","כיון שדובר בדיני המנודה, מבארים כמה מעיקרי ענין הנידוי, \u0003אמר רבא: מנלן דמשדרין שליחא דבי דינא ומזמנינן ליה לדינא\u0004 \u0005[מניין לנו ששולחים שליח בית דין ומזמינים אותו\u0006 את הנתבע \u0005לדין]\u0006 לפני שבאים לנדות אדם — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישלח משה לקרא לדתן ולאבירם בני אליאב\"\u0004 (במדבר טז, יב). \u0003ומנלן דמזמנינן לדינא\u0004 \u0005[ומניין שמזמינים אנו לדין]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר משה אל קרח אתה וכל עדתך\"\u0004 (במדבר טז, טז).","ומניין שאומרים להם שנדונים \u0003לקמי גברא רבה\u0004 \u0005[לפני אדם גדול]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004היו \u0003לפני ה' \"\u0004(במדבר טז, טז). ומניין שמפרשים לו שיבואו לדין \u0003את ופלניא\u0004 \u0005[אתה ופלוני]\u0006 בעל דין — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אתה והם ואהרן\"\u0004 (במדבר טז, טז). ומניין לנו \u0003דקבעינן זימנא\u0004 \u0005[שאנו קובעים זמן]\u0006 לדין — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מחר\"\u0004 (במדבר טז, טז). ומניין שקובעים \u0003זימנא בתר זימנא\u0004 \u0005[זמן אחר זמן],\u0006 שאם לא בא בפעם ראשונה מזמינים אותו שנית — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קראו שם פרעה מלך מצרים שאון העביר המועד\"\u0004 (ירמיהו מו, יז), משמע שיש מועד, אבל הדבר אינו בטל לגמרי אלא נדחה לזמן מאוחר יותר.","\u0003ומנלן דאי מתפקר בשליחא דבי דינא ואתי ואמר, לא מיתחזי כלישנא בישא\u0004 \u0005[ומניין שאם מתחצף לשליח בית הדין ובא\u0006 השליח \u0005ואומר\u0006 זאת, \u0005אין\u0006 זה \u0005נראה כלשון הרע] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"העיני האנשים ההם תנקר\"\u0004 (במדבר טז, יד), שמסרו דתן ואבירם לשליחו של משה והשליח חזר ואמר למשה מה שאמרו לו.","\u0003ומנלן דמשמתינן\u0004 \u0005[ומניין לנו שאנו מנדים]\u0006 מי שאינו בא לדין — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אורו מרוז\"\u0004 (שופטים ה, כג), שנידו אותו על שלא בא. ומנין לנו שצריך לומר למנודה \u0003דהכי סברא דגברא רבה\u0004 \u0005[שכך\u0006 היתה \u0005הסברה של אדם גדול]\u0006 לנדות אותו — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אמר מלאך ה' \"\u0004(שופטים ה, כג). \u0003ומנלן דמחרמינן\u0004 \u0005[ומניין שאנו\u0006 גם \u0005מחרימים]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארו ארור\"\u0004 (שופטים ה, כג), משמע קללה אחר קללה (חרם אחר הנידוי).","ומניין שכוללים בזה גם את כל מי \u0003דאכיל ושתי בהדיה\u0004 \u0005[שאוכל ושותה עמו]\u0006 \u0003וקאי\u0004 \u0005[ועומד,\u0006 נמצא\u0005]\u0006 \u0003בארבע אמות דידיה\u0004 \u0005[שלו]\u0006 של המנודה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישביה\"\u0004 (שופטים ה, כג), כלומר, כל אלה היושבים איתו. \u0003ומנלן דפרטינן חטאיה בציבורא\u0004 \u0005[ומנין שמפרטים אנו את חטאו בציבור]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא באו לעזרת ה' \"\u0004(שופטים ה, כג).","\u0003ואמר עולא: בארבע מאה שיפורי\u0004 \u0005[מאות שופרות]\u0006 \u0003שמתיה\u0004 \u0005[נידה אותו]\u0006 \u0003ברק למרוז\u0004 על שלא בא. לעצם פירושו של פסוק זה, \u0003איכא דאמרי גברא רבה הוה\u0004 \u0005[יש אומרים\u0006 שמרוז \u0005אדם גדול היה]\u0006 ולא בא למלחמה ולכן החרימו אותו, \u0003ואיכא דאמרי כוכבא הוה\u0004 \u0005[ויש אומרים כוכב היה]\u0006 ולא אדם, ולא בא לעזור למלחמת ישראל, \u0003שנאמר: \"מן שמים נלחמו הכוכבים\u0004 ממסילותם נלחמו עם סיסרא\u0003\"\u0004(שופטים ה, כ), וכוכב זה שלא עזר לישראל — קללוהו.","\u0003ומנלן דמפקרינן נכסיה\u0004 \u0005[ומניין לנו שאנו מפקירים נכסיו]\u0006 של מי שאיננו מציית לבית דין — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל אשר לא יבוא לשלשת הימים כעצת השרים והזקנים יחרם כל רכושו והוא יבדל מקהל הגולה\"\u0004 (עזרא י, ח).","\u0003ומנלן דנצינן ולייטינן ומחינן ותלשינן שיער ומשבעינן\u0004 \u0005[ומניין שאנו רבים ומקללים ומכים ותולשים שיער ומשביעים]\u0006 שיימנעו מן האיסור — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואריב עמם ואקללם ואכה מהם אנשים ואמרטם ואשביעם\"\u0004 (נחמיה יג, כה).","\u0003ומנלן דכפתינן ואסרינן ועבדינן\u0004 \u0005[ומניין שאנחנו קושרים\u0006 ידיו ורגליו \u0005ואוסרים ועושים]\u0006 \u0003הרדפה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הן למות הן לשרושי הן לענש נכסין ולאסורין\"\u0004 (עזרא ז, כו). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לשרושי\"\u0004 שנאמר בכתוב? \u0003אמר אדא מרי אמר נחמיה בר ברוך אמר רב חייא בר אבין אמר רב יהודה:\u0004 דבר זה הוא הקרוי \u0003הרדפה.\u0004 ביטוי זה לא היה מובן, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003הרדפה\u0004 זו? \u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב,\u0004 כך עושים: \u0003מנדין לאלתר\u0004 \u0005[מיד]\u0006 \u0003ושונין\u0004 (חוזרים) לנדותו \u0003לאחר שלשים, ו\u0004אם לא חזר בו \u0003מחרימין לאחר ששים\u0004 יום,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חיננא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חסדא: מתרין ביה\u0004 \u0005[בו]\u0006 שלוש פעמים, בימים \u0003שני וחמישי ושני.\u0004 ומעירים: \u0003הני מילי לממונא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005לממון]\u0006 שמתרים וחוזרים ומתרים בו שישלם את שהוטל עליו, \u0003אבל לאפקירותא\u0004 \u0005[לחוצפה]\u0006 שמתחצף לתלמידי חכמים — \u0003לאלתר\u0004 \u0005[מיד]\u0006 מחרימים אותו.","מסופר: \u0003ההוא טבחא דאיתפקר\u0004 \u0005[שוחט אחד שהתחצף]\u0006 ל\u0003רב טובי בר מתנה, אימנו עליה\u0004 \u0005[נימנו עליו]\u0006 \u0003אביי ורבא ושמתוהו\u0004 \u0005[ונידוהו],\u0006 \u0003לסוף אזל פייסיה לבעל דיניה\u0004 \u0005[לבסוף הלך\u0006 ו\u0005פייס את בעל דינו]\u0006 רב טובי. \u0003אמר אביי: היכי ליעביד\u0004 \u0005[כיצד נעשה]\u0006 במקרה זה? אם \u0003לישרי ליה\u0004 \u0005[נתיר לו]\u0006 מיד את נידויו? הרי \u0003לא חל\u0004 עדיין \u0003שמתא עליה תלתין יומין\u0004 \u0005[הנידוי עליו שלושים יום]\u0006 וכיון שלא חל הנידוי אין דרך להתיר דבר שעדיין לא נתממש. ומצד שני, אם \u0003לא לישרי ליה\u0004 \u0005[נתיר לו]\u0006 הלא \u0003קא בעו רבנן למיעל\u0004 \u0005[רוצים חכמים להכנס]\u0006 וצריכים לקנות ממנו בשר, ואם כן מה לעשות?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לרב אידי בר אבין: מידי שמיע לך בהא\u0004 \u0005[\u0006האם \u0005שמעת דבר מה ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אידי בר אבין לאביי: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב תחליפא בר אבימי אמר שמואל: טוט,\u0004 כלומר, קול השופר בנידוי \u0003אסר וטוט\u0004 התקיעה \u0003שרי\u0004 \u0005[מתיר],\u0006 כלומר יש לתקוע בשופר, כמו בשעת הנידוי, ולהתיר לו אף על פי שלא עברו שלושים יום בנידוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003הני מילי לממונא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005ל\u0006ענין \u0005ממון]\u0006 \u0003אבל לאפקירותא\u0004 \u0005[לחוצפה]\u0006 \u0003עד דחיילא שמתא עליה תלתין יומין\u0004 \u0005[שיחול הנידוי עליו שלושים יום].\u0006","ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003אביי: הני בי תלתא דשמיתו\u0004 \u0005[אלה\u0006 ה\u0005שלושה שנידו] —\u0006 \u0003לא אתו תלתא אחריני ושרו ליה\u0004 \u0005[אין\u0006 רשאים \u0005לבוא שלושה אחרים ולהתיר לו]\u0006 אלא רק הם עצמם, שהרי אביי עצמו טרח להתיר ולא מסר הדבר לאחרים.","\u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם]\u0006 ללומדים שאלה זו: \u0003הני בי תלתא דשמיתו,\u0004 \u0005[אלה\u0006 ה\u0005שלושה שנידו]\u0006 \u0003מהו למיתי תלתא אחריני ושרו ליה\u0004 \u0005[שיבואו שלושה אחרים ויתירו לו]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003מנודה לרב\u0004 מי שנידהו הרב על שפגע בכבודו — \u0003מנודה לתלמיד\u0004 שגם התלמיד צריך לנהוג בו ריחוק, אבל \u0003מנודה לתלמיד — איננו מנודה לרב.\u0004","וכן, מי ש\u0003מנודה לעירו — מנודה\u0004 גם \u0003לעיר אחרת, מנודה לעיר אחרת — אינו מנודה לעירו.\u0004 מי ש\u0003מנודה לנשיא — מנודה לכל ישראל, מנודה לכל ישראל — אינו מנודה לנשיא. רבן שמעון בן גמליאל אומר: אחד מן התלמידים שנידה ומת\u0004 ולא הספיק להתיר — \u0003חלקו אינו מופר.\u0004","ומעירים מהלכה זו \u0003שמע מינה תלת\u0004 \u0005[למד מכאן שלושה\u0006 דברים\u0005];\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003תלמיד שנידה לכבודו\u0004 לא משום שהמנודה עבר עבירה, אלא שפגע בכבודו — \u0003נידויו נידוי,\u0004 שאם היה מדובר בנידוי על עבירה — הכל חייבים לנהוג בו נידוי. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003כל אחד ואחד\u0004 מן המנדים \u0003מיפר חלקו\u0004 שלו, שהרי הוזכר כאן \"חלקו\". \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003הני בי תלתא דשמיתו, לא אתו תלתא אחריני ושרו ליה\u0004 \u0005[שלושה שנידו, אין באים שלושה אחרים ומתירים לו],\u0006 שאם לא כן, מה משנה אם חלקו של המנדה אינו מופר, הרי עדיין ניתן להתירו על ידי אחר.","\u0003אמר אמימר: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005],\u0006 \u0003הני בי תלתא דשמיתו\u0004 \u0005[שלושה שנידו] —\u0006 \u0003אתו בי תלתא אחריני ושרו ליה\u0004 \u0005[\u0006יכולים \u0005לבוא שלושה אחרים ולהתיר לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אחד מן התלמידים שנידה ומת — חלקו אינו מופר. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003אינו מופר כלל,\u0004 ומכאן שאין אחר יכול להתיר את שנידה אחר! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003עד דאתו בי תלתא אחריני ושרו ליה\u0004 \u0005[שיבואו שלושה אחרים ויתירו לו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין נידוי פחות משלשים יום, ואין נזיפה\u0004 שהיא פחות חמורה מנידוי \u0003פחות משבעה ימים. ואף על פי שאין ראיה לדבר\u0004 זה בענין נזיפה, אבל \u0003זכר לדבר\u0004 יש, \u0003שנאמר: \"ואביה ירק ירק בפניה הלא תכלם שבעת ימים\"\u0004 (במדבר יב, יד), הרי שנזיפה היא לשבעה ימים.","\u0003אמר רב חסדא: נידוי שלנו\u0004 של בני בבל כוחו \u0003כנזיפה שלהן\u0004 של בני ארץ ישראל, שכיוון שהם חכמים סמוכים, גדול יותר כח נזיפתם. ושואלים: \u0003ונזיפה דידהו\u0004 \u0005[שלהם]\u0006 של בני ארץ ישראל אינה אלא \u0003שבעה\u0004 ימים \u0003ותו לא\u0004 \u0005[ולא יותר]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 מסופר כי \u0003ר' שמעון בר\u0004 \u0005[בנו]\u0006 של \u0003רבי ובר קפרא הוו יתבי וקא גרסי\u0004 \u0005[היו יושבים ולומדים],\u0006 \u0003קשיא להו שמעתא\u0004 \u0005[\u0006היתה \u0005קשה להם הלכה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון לבר קפרא: דבר זה צריך רבי,\u0004 כלומר, לדבר זה צריך את רבי אבי שילמדנו פירושו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא לר' שמעון\u0004 במקצת ליגלוג: \u0003ומה\u0004 אביך \u0003רבי אומר בדבר זה,\u0004 מה יכול הוא להוסיף וללמדנו בזה?","\u0003אזל\u0004 \u0005[הלך]\u0006 רבי שמעון ו\u0003אמר ליה לאבוה\u0004 \u0005[לו\u0006 \u0005לאביו\u0006 רבי\u0005]\u0006 את דברי בר קפרא, \u0003איקפד\u0004 \u0005[הקפיד]\u0006 רבי על כך: כאשר \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בר קפרא\u0004 פעם \u0003לאיתחזויי ליה\u0004 \u0005[לבקר אותו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003בר קפרא, איני מכירך מעולם! ידע\u0004 והבין בר קפרא \u0003דנקט מילתא בדעתיה\u0004 \u0005[שלקח\u0006 רבי \u0005את הדבר בדעתו,\u0006 בליבו ונעלב\u0005]\u0006 \u0003נהג\u0004 בר קפרא \u0003נזיפותא בנפשיה\u0004 \u0005[נזיפות בעצמו]\u0006 במשך \u0003תלתין יומין\u0004 \u0005[שלושים יום]\u0006 כעונש.","ובדומה לזה \u0003שוב פעם אחד גזר רבי שלא ישנו לתלמידים בשוק\u0004 אלא רק בבית המדרש. \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דרש\u0004 כמקור לגזירה זו — שנאמר: \u0003\"חמוקי ירכיך כמו חלאים\u0004 מעשה ידי אמן\u0003\"\u0004 (שיר השירים ז, ב) וכך פירשו: \u0003מה ירך\u0004 מצוי \u0003בסתר\u0004 ודרך לכסותו תמיד בבגדים,"],["\u0003אף דברי תורה\u0004 (שהם \"מעשה ידי אומן\" — הקדוש ברוך הוא) צריכים להיאמר \u0003בסתר.\u0004","למרות זאת \u0003יצא ר' חייא ושנה לשני בני אחיו בשוק, לרב ולרבה בר בר חנה. שמע רבי, איקפד\u0004 \u0005[הקפיד\u0006 על כך\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' חייא לאיתחזויי ליה\u0004 \u0005[לבקר אותו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 תוך כדי שהוא מכנהו בלשון לגלוג: \u0003עייא, מי קורא לך בחוץ!\u0004 שרמז לו שיצא מביתו. \u0003ידע דנקט מילתא בדעתיה\u0004 \u0005[ידע שלקח\u0006 רבי \u0005את הדבר בדעתו,\u0006 בלבו ונעלב\u0005],\u0006 \u0003נהג נזיפותא בנפשיה\u0004 \u0005[נזיפות בעצמו]\u0006 במשך \u0003תלתין יומין\u0004 \u0005[שלושים יום].\u0006","מסופר: \u0003ביום תלתין\u0004 \u0005[\u0006ה\u0005שלושים]\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 רבי: \u0003תא\u0004 \u0005[בוא\u0006 לבקרני\u0005].\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003שלח ליה\u0004 \u0005[לו]\u0006 ש\u0003לא ליתי\u0004 \u0005[לבוא].\u0006","ושואלים: \u0003מעיקרא מאי\u0004 \u0005[מתחילה מה]\u0006 \u0003סבר ולבסוף מאי\u0004 \u0005[מה]\u0006 \u0003סבר,\u0004 ששינה דעתו? ומסבירים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר\u0004 רבי: \u0003מקצת היום ככולו\u0004 לענין זה, וכיון שהתחיל יום שלושים כבר נפטר רבי חייא מעונשו. \u0003ולבסוף סבר: לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 לענין זה \u0003מקצת היום ככולו.\u0004","\u0003לסוף אתא\u0004 \u0005[בסוף בא]\u0006 רבי חייא באותו יום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אמאי אתית\u0004 \u0005[מדוע באת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי חייא: ש\u0003שלח לי מר דליתי\u0004 \u0005[אדוני שאבוא].\u0006 אמר לו: \u0003והא שלחי\u0004 \u0005[והרי שלחתי]\u0006 \u0003לך\u0004 ש\u0003לא תיתי\u0004 \u0005[תבוא]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זה\u0004 השליח הראשון שבא בשליחותך \u0003ראיתי\u0004 ושמעתי דבריו, \u0003וזה\u0004 השליח השני \u0003לא ראיתי. קרי עליה\u0004 \u0005[קרא עליו]\u0006 רבי מקרא זה: \u0003\"ברצות ה' דרכי איש גם אויביו ישלם אתו\"\u0004 (משלי טז, ז), שמשמים מסייעים לך בדבר.","ולעיקרו של ענין שאל רבי את רבי חייא: \u0003מאי טעמא עבד מר הכי\u0004 \u0005[מה טעם עשה אדוני כך]\u0006 ולא שמע לדברי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי חייא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"חכמות בחוץ תרנה\"\u0004 (משלי א, כ), משמע שצריך לפרסם דברי תורה ברבים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003אם קרית\u0004 מקרא זה, ודאי \u0003לא שנית\u0004 לקוראו שנית בעיון, \u0003ואם שנית — לא שילשת, ואם שילשת\u0004 וזכרת היטב — משמע כי \u0003לא פירשו לך,\u0004 ולא הבנת את משמעות הדברים.","\u0003\"חכמות בחוץ תרנה\"\u0004 יש להבינו \u0003כ\u0004דברי \u0003רבא.\u0004 ש\u0003אמר רבא: כל העוסק בתורה מבפנים,\u0004 בביתו, בסתר, \u0003תורתו מכרזת עליו מבחוץ\u0004 שמתגלה תורתו לרבים והם מכירים בגדולתו.","ושואלים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא מראש בסתר דברתי\"\u0004 (ישעיהו מח, טז), משמע שדברי תורה צריכים להיאמר בגלוי ובפרהסיה! ומשיבים: הכתוב \u0003ההוא\u0004 מדבר \u0003ביומי דכלה\u0004 (בימי האסיפה, הלימוד השנתי), שאז בא רוב העם לשמוע, ואז מותר וראוי ללמד תורה ברבים. עד כאן לשיטת רבי.","ושואלים: \u0003ור' חייא, האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"חמוקי ירכיך\" מאי עביד לה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו],\u0006 כיצד מפרש הוא אותו? שהרי לכאורה מראה כתוב זה שצריך להצניע ולא לגלות דברי תורה ברבים. ומסבירים: \u0003מוקי לה\u0004 \u0005[מעמיד,\u0006 מפרש, \u0005אותה]\u0006 \u0003בצדקה ובגמילות חסדים,\u0004 שודאי מצוות אלה ראוי שתיעשנה בסתר.","ולענייננו בהלכה \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003שנזיפה דידהו\u0004 \u0005[שלהם]\u0006 של בני ארץ ישראל במשך \u0003תלתין יומין\u0004 \u0005[שלושים יום]\u0006 היא ולא שבעה כמו שאמרנו! ומשיבים: \u0003נזיפת נשיא שאני\u0004 \u0005[שונה]\u0006 שהיא חמורה יותר מנזיפת אדם אחר.","ושואלים: \u0003ונזיפה דידן\u0004 \u0005[שלנו,\u0006 של בני בבל\u0005]\u0006 \u0003כמה הוי\u0004 \u0005[היא\u0006 נמשכת\u0005]?\u0006 ומשיבים: \u0003חד יומא\u0004 \u0005[יום אחד].\u0006 ומסופר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003שמואל\u0004 וראש הגולה \u0003מר עוקבא. כי הוו יתבי גרסי שמעתא\u0004 \u0005[כאשר היו יושבים\u0006 ו\u0005לומדים הלכה],\u0006 \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003מר עוקבא קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל ברחוק ארבע אמות,\u0004 שנהג בו יראת כבוד כתלמיד לרב, ששמואל היה גדול ממנו בתורה. \u0003וכי הוו יתבי בדינא\u0004 \u0005[וכאשר היו יושבים בדין],\u0006 \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003שמואל קמיה\u0004 \u0005[לפני]\u0006 \u0003מר עוקבא ברחוק ארבע אמות,\u0004 משום כבודו שהוא היה ראש הגולה וראש הדיינים. ומספרים: \u0003והוו חייקי ליה דוכתא\u0004 \u0005[והיו חוקקים,\u0006 מנמיכים, \u0005מקום]\u0006 \u0003למר עוקבא בציפתא\u0004 \u0005[ב\u0006תוך ה\u0005כר],\u0006 \u0003ויתיב עילויה כי היכי דלישתמען מיליה\u0004 \u0005[וישב עליו כדי שיהיו דבריו\u0006 של שמואל \u0005נשמעים\u0006 לו\u0005]\u0006 ושיוכל לקבל ממנו דברי תורה גם כשישבו בדין.","\u0003כל יומא\u0004 \u0005[יום]\u0006 \u0003הוה מלוי ליה\u0004 \u0005[היה מלווה אותו]\u0006 \u0003מר עוקבא לשמואל עד אושפיזיה\u0004 \u0005[בית המלון\u0006 שהיה גר בו\u0005]\u0006 כתלמיד הנוהג כבוד ברבו. \u0003יומא חד איטריד בדיניה\u0004 \u0005[יום אחד נטרד\u0006 מר עוקבא \u0005בדינו]\u0006 ומתוך שהיה טרוד במחשבה על הדין שבא לפניו לא שם לב \u0003דהוה אזיל\u0004 \u0005[שהיה הולך]\u0006 \u0003שמואל בתריה\u0004 \u0005[אחריו]\u0006 משום שהיה ראש הגולה, ונהג בו כבוד. \u0003כי מטא לביתיה\u0004 \u0005[כאשר הגיע\u0006 מר עוקבא \u0005לביתו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003לא נגה\u0004 \u0005[הספיק]\u0006 \u0003לך\u0004 שאלווה אותך עד כאן? \u0003לישרי לי מר בתיגריה\u0004 \u0005[שיתיר לי אדוני את חובתי]\u0006 ואוכל לשוב לביתי! \u0003ידע\u0004 מר עוקבא \u0003דנקט מילתא בדעתיה\u0004 \u0005[שלקח\u0006 שמואל \u0005את הדבר בדעתו,\u0006 בלבו ונעלב\u0005]\u0006 \u0003ונהג נזיפותא בנפשיה\u0004 \u0005[נזיפות בעצמו]\u0006 במשך \u0003חד יומא\u0004 \u0005[יום אחד].\u0006","כיוצא בו מסופר: \u0003ההיא איתתא דהוות יתבא בשבילא, הוות פשטה כרעה וקא מניפה חושלאי\u0004 \u0005[אשה אחת ישבה בשביל\u0006 ו\u0005היתה פושטת את רגלה ומנפה שעורים]\u0006 \u0003והוה חליף ואזיל צורבא מרבנן ולא איכנעה מקמיה\u0004 \u0005[והיה חולף והולך תלמיד חכם\u0006 בשביל זה \u0005ולא נכנעה מלפניו]\u0006 להחזיר את רגלה ולפנות לו מקום. \u0003אמר: כמה חציפא\u0004 \u0005[חצופה]\u0006 \u0003ההיא איתתא\u0004 \u0005[אשה זו]!\u0006 \u0003אתאי לקמיה\u0004 \u0005[באה\u0006 האשה \u0005לפני]\u0006 \u0003רב נחמן\u0004 לשאול האם יש לראות בדברים אלה משום נידוי. \u0003אמר לה: מי שמעת שמתא מפומיה\u0004 \u0005[האם שמעת נידוי\u0006 מפורש \u0005מפיו]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא. אמר לה:\u0004 אם כן, \u0003זילי נהוגי נזיפותא חד יומא בנפשיך\u0004 \u0005[לכי נהגי נזיפות בעצמך יום אחד],\u0006 שלא היה זה נידוי אלא נזיפה בלבד.","ועוד מסופר: \u0003זוטרא בר טוביה הוה קפסיק סידרא קמיה\u0004 \u0005[היה קורא\u0006 את \u0005המקרא לפני]\u0006 \u0003רב יהודה, כי מטא להאי פסוקא\u0004 \u0005[כאשר הגיע לפסוק זה]\u0006 \u0003\"ואלה דברי דוד האחרונים\"\u0004 (שמואל ב', כג, א), \u0003אמר ליה\u0004 \u0005[לו]\u0006 זוטרא בר טוביה לרב יהודה: אם נאמר \u0003\"אחרונים\" — מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003ראשונים,\u0004 ואם כן \u0003ראשונים מאי נינהו\u0004 \u0005[מה הם]?\u0006 שהרי לא נאמרו קודם לכן \"דברי דוד\" אלא שירה בלבד.","\u0003שתיק\u0004 \u0005[שתק]\u0006 רב יהודה \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 חשב זוטרא בר טוביה שלא שמע רב יהודה, \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"אחרונים\", מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 גם \u0003ראשונים, ראשונים מאי היא\u0004 \u0005[מה\u0006 הם\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דעתך,\u0004 האם אתה חושב שמי \u0003דלא ידע פירושא דהאי קרא לאו גברא רבה הוא\u0004 \u0005[שאיננו יודע\u0006 את \u0005פירושו של כתוב זה איננו אדם גדול]?\u0006 ואתה בא להדגיש שאיני יודע! \u0003ידע\u0004 זוטרא בר טוביה \u0003דנקט מילתא בדעתיה\u0004 \u0005[שלקח\u0006 רב יהודה את \u0005הדבר בדעתו,\u0006 בלבו ונעלב\u0005]\u0006 ו\u0003נהג נזיפותא בנפשיה\u0004 \u0005[נזיפות בעצמו]\u0006 במשך \u0003חד יומא\u0004 \u0005[יום אחד].\u0006","ושואלים: \u0003ודאתן עלה\u0004 \u0005[ו\u0006כיון \u0005שהגענו\u0006 כבר \u0005אליה]\u0006 לבעיה זו, \u0003מיהא\u0004 \u0005[הלא]\u0006 ממה שנאמר \u0003\"אחרונים\" מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003ראשונים,\u0004 ואם כן \u0003ראשונים מאי היא\u0004 \u0005[מה הם]?\u0006 ואומרים: הראשונים הם \u0003\"וידבר דוד לה' את דברי השירה הזאת ביום הציל ה' אתו מכף כל אויביו ומכף שאול\"\u0004 (שמואל ב', כב, א), הרי ששירה זו גם היא נקראת דברים.","ובאותו ענין, \u0003אמר לו הקדוש ברוך הוא לדוד: דוד, שירה אתה אומר על מפלתו של שאול? אלמלי\u0004 (אילו) \u0003אתה שאול והוא דוד\u0004 שהוא נולד במזלך ואתה נולדת במזלו — \u0003איבדתי כמה דוד מפניו,\u0004 שאמנם גזרתי שלא תמשיך מלכות שאול, אבל מצד מעלתו האישית — גדול הוא וחשוב ממך.","וכתיקון לתוכחה זו — \u0003היינו דכתיב\u0004 \u0005[הוא שנאמר]:\u0006 \u0003\"שגיון לדוד אשר שר לה' על דברי כוש בן ימיני\"\u0004 (תהלים ז, א), \u0003וכי כוש שמו? והלא שאול שמו, אלא\u0004 כינוי הוא: \u0003מה כושי משונה בעורו\u0004 שהוא שחור — \u0003אף שאול משונה במעשיו,\u0004 הטובים והמיוחדים, שהיה צדיק גמור, והודה דוד שהיה זה \"שגיון\" — שגיאה שאמר שירה על מפלתו.","ומעירים, \u0003כיוצא בדבר\u0004 בדרך פירוש זו \u0003אתה אומר: \"\u0004ותדבר מרים ואהרן במשה \u0003על אדות האשה הכשית אשר לקח\"\u0004 (במדבר יב, א), \u0003וכי כושית שמה? והלא ציפורה שמה! אלא מה כושית משונה בעורה — אף ציפורה משונה במעשיה\u0004 הטובים. \u0003כיוצא בדבר אתה אומר \"וישמע עבד מלך הכושי\"\u0004 (ירמיהו לח, ז), \u0003וכי כושי שמו\u0004 של המלך? \u0003והלא צדקיה שמו! אלא מה כושי משונה בעורו — אף צדקיה משונה במעשיו\u0004 הטובים, שהוא עצמו צדיק היה.","\u0003כיוצא בדבר אתה אומר: \"הלוא כבני כשיים אתם לי בני ישראל\"\u0004 (עמוס ט, ז), \u0003וכי כושיים שמן? והלא ישראל שמן! אלא: מה כושי משונה בעורו — אף ישראל משונין במעשיהן\u0004 לטובה \u0003מכל האומות.\u0004 כיון שהזכרנו את \"דברי דוד האחרונים\" מביאים דברים אחדים בביאור קטעים ממזמור זה.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"נאם דוד בן ישי ונאם הגבר הקם על\"\u0004 (שמואל ב' כג, א) — כך פירושו: \u0003\"נאם דוד בן ישי\" שהקים עולה של תשובה,\u0004 שלימד במעשיו עד היכן מגיע כוחה של תשובה.","\u0003\"אמר אלהי ישראל לי דבר צור ישראל מושל באדם צדיק מושל יראת אלהים\"\u0004 (שמואל ב', כג, ג), ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אומר]\u0006 פסוק זה, מה פירושו? \u0003אמר ר' אבהו: הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003אמר אלהי ישראל: לי דבר צור ישראל, אני מושל באדם, מי מושל בי\u0004 בקדוש ברוך הוא — \u0003צדיק.\u0004 וכיצד אפשר לומר שהצדיק כביכול מושל בה' \u0003שאני גוזר גזרה ו\u0004הצדיק \u0003מבטלה.\u0004","ועוד נאמר שם: \u0003\"אלה שמות הגברים אשר לדוד ישב בשבת\u0004 תחכמוני ראש השלישי הוא עדינו העצני על שמונה מאות חלל בפעם אחת\u0003\"\u0004 (שמואל ב', כג, ח), ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירוש הדבר? \u0003אמר ר' אבהו, הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לדרוש: \u0003ואלה שמות גבורותיו של דוד.\u0004","שמה שנמנה בפסוק זה יש להבינו לא כשמותיהם של אנשים, אלא כתארים עבור דוד; \u0003\"יושב בשבת\" — בשעה שהיה יושב בישיבה, לא היה יושב על גבי כרים וכסתות\u0004 כפי שנוהג אדם גדול וחשוב \u0003אלא על גבי קרקע\u0004 כאחד התלמידים. \u0003דכל כמה דהוה רביה\u0004 \u0005[שכל זמן שהיה רבו\u0006 של דוד\u0005]\u0006 \u0003עירא היאירי קיים, הוה מתני להו לרבנן\u0004 \u0005[היה\u0006 עירא \u0005משנה\u0006 מלמד \u0005להם לחכמים]\u0006 כשהוא יושב \u0003על גבי כרים וכסתות. כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 עירא, \u0003הוה מתני\u0004 \u0005[היה משנה,\u0006 מלמד\u0005]\u0006 \u0003דוד לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003והוה יתיב\u0004 \u0005[והיה יושב]\u0006 \u0003על גבי קרקע. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליתיב מר\u0004 \u0005[ישב אדוני]\u0006 על \u0003כרים וכסתות! לא קביל עליה\u0004 \u0005[קיבל עליו]\u0006 מחמת ענוה שלא להראות עצמו כרבם של ישראל.","\u0003\"תחכמני\" — אמר רב: אמר לו הקדוש ברוך הוא: הואיל והשפלת עצמך — תהא כמוני,\u0004 \"תחכמוני\" — תה(א) כמוני, בחילוף האותיות הגרוניות ח' וה'. וכיצד זה — \u0003שאני גוזר גזרה, ואתה\u0004 בצדקתך \u0003מבטלה.\u0004","\u0003\"ראש השלישים\" — תהא ראש לשלשת אבות,\u0004 שדוד נמנה בתפילה כראש לאבות. \u0003\"הוא עדינו העצני\"\u0004 מרמז: \u0003כשהוא יושב ועוסק בתורה היה מעדן\u0004 (\"עדינו\") \u0003עצמו כתולעת\u0004 זו שהיא רכה, \u0003ובשעה שיוצא למלחמה היה מקשה עצמו כעץ\u0004 (\"העצני\") ומתחזק.","ומה שנאמר \u0003\"על שמנה מאות חלל בפעם אחת\" — שהיה זורק חץ, ומפיל שמונה מאות חלל בפעם אחת. והיה\u0004 דוד \u0003מתאנח על מאתים\u0004 שחסרים כדי להשלים את ההבטחה בתורה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איכה ירדף אחד אלף\"\u0004 (דברים לב, ל).","\u0003יצתה בת קול ואמרה: \"\u0004אשר עשה דוד את הישר בעיני ה' ולא סר מכל אשר ציוהו כל ימי חייו \u0003רק בדבר אוריה החתי\"\u0004 (מלכים א' טו, ה), שאילולי חטא זה היה זוכה שכל הבטחות התורה היו מתקיימות בו בשלימות.","ושוב לעניינים ולהלכות נידוי \u0003אמר ר' תנחום בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא איש כפר עכו, אמר ר' יעקב בר אחא אמר ר' שמלאי. ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 מסורת זו באופן אחר, ש\u0003אמר ר' תנחום אמר רב הונא, ואמרי לה\u0004 \u0005[ו\u0006יש \u0005אומרים]\u0006 ש\u0003אמר רב הונא לחודיה\u0004 \u0005[לבד,\u0006 בעצמו\u0005]\u0006 בלי שלשלת זו של מוסרי השמועה:"],["\u0003תלמיד שנידה לכבודו\u0004 לא משום שהמנודה עבר עבירה, אלא שפגע בכבודו — \u0003נדויו נידוי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנודה לרב — מנודה לתלמיד, מנודה לתלמיד — אינו מנודה לרב.\u0004 ונדייק: \u0003לרב הוא\u0004 ש\u0003אינו מנודה, הא לכולי עלמא\u0004 \u0005[הרי לכל העולם,\u0006 לכול\u0005]\u0006 — הוא \u0003מנודה,\u0004 ונברר:","\u0003למאי\u0004 \u0005[למה]\u0006 נידה אותו? \u0003אי במילי דשמיא\u0004 \u0005[אם בדברים\u0006 בענייני \u0005שמים]\u0006 משום שאותו אדם עבר עבירה — מדוע לא יהיה מנודה גם לרב? הלא כבר נאמר \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה' \"\u0004(משלי כא, ל), שנגד ה', ובמקום שיש חילול שמו, אין להחשיב שום דבר, גם לא את גדלותו של הרב וחכמתו, שגם הוא צריך לנהוג נידוי באדם זה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כשנידה \u0003לכבוד עצמו,\u0004 ואם כן משמע מכאן שנידויו נידוי לכל אדם (פרט לרב).","\u0003אמר רב יוסף: צורבא מרבנן עביד דינא לנפשיה במילתא דפסיקא ליה\u0004 \u0005[תלמיד חכם עושה דין לעצמו בדבר הברור לו]\u0006 ואינו צריך ללכת לבית דין שיפסקו דינו תחילה, וכן הוא נוהג כשנהגו בו זלזול.","מסופר: \u0003ההוא צורבא מרבנן דהוו סנו שומעניה\u0004 \u0005[תלמיד חכם אחד שהיו\u0006 עליו \u0005שמועות רעות]\u0006 שהיה חשוד בדבר עבירה, \u0003אמר רב יהודה: היכי ליעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003לשמתיה\u0004 \u0005[\u0006אם \u0005ננדה אותו]\u0006 — \u0003צריכי ליה רבנן\u0004 \u0005[צריכים אותו חכמים],\u0006 שהיה גדול בתורה, ואם \u0003לא לשמתיה\u0004 \u0005[ננדה אותו] —\u0006 \u0003קא מיתחיל שמא דשמיא\u0004 \u0005[יתחלל שם שמים].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה \u0003לרבה בר בר חנה: מידי שמיע לך בהא\u0004 \u0005[\u0006האם \u0005שמעת דבר ב\u0006ענין \u0005זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הכתוב]:\u0006 \u0003\"כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו כי מלאך ה' צבאות הוא\"\u0004 (מלאכי ב, ז), ללמדנו: \u0003אם דומה הרב למלאך ה' — יבקשו תורה מפיו, ואם לאו\u0004 שאיננו טהור וכשר — \u0003אל יבקשו תורה מפיו,\u0004 ואפילו הוא גדול בתורה אין ללמוד ממנו.","וכיון שכן \u0003שמתיה\u0004 \u0005[נידה אותו]\u0006 \u0003רב יהודה\u0004 לאותו תלמיד. \u0003לסוף איחלש\u0004 \u0005[בסוף\u0006 לאחר זמן \u0005נחלש]\u0006 \u0003רב יהודה\u0004 ועמד למות. \u0003אתו רבנן לשיולי ביה\u0004 \u0005[באו חכמים לשאול בו\u0006 לשלומו\u0005]\u0006 \u0003ואתא איהו נמי בהדייהו\u0004 \u0005[ובא הוא\u0006 המנודה \u0005גם כן איתם],\u0006 \u0003כד חזייה\u0004 \u0005[כאשר ראה אותו]\u0006 \u0003רב יהודה חייך,\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 המנודה: \u0003לא מסתייך\u0004 \u0005[דייך]\u0006 \u0003דשמתיה לההוא גברא\u0004 \u0005[שנידיתי את האיש ההוא],\u0006 אותי, \u0003אלא אחוכי נמי חייך בי\u0004 \u0005[אתה גם צוחק עלי]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003לאו בדידך מחייכנא\u0004 \u0005[לא בשלך,\u0006 עליך \u0005אני צוחק]\u0006 \u0003אלא דכי אזלינא לההוא עלמא בדיחא דעתאי\u0004 \u0005[שכאשר אני הולך לעולם ההוא שמח אני],\u0006 ש\u0003אפילו לגברא כוותך\u0004 \u0005[לאדם\u0006 גדול \u0005כמוך]\u0006 \u0003לא חניפי ליה\u0004 \u0005[החנפתי לו]\u0006 ונהגתי בו כדין.","כאשר \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב יהודה, אתא לבי מדרשא\u0004 \u0005[בא\u0006 המנודה \u0005לבית המדרש],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לחכמים: \u0003שרו\u0004 \u0005[התירו]\u0006 \u0003לי\u0004 את הנידוי! \u0003אמרו ליה רבנן\u0004 \u0005[לו החכמים]:\u0006 \u0003גברא דחשיב\u0004 \u0005[אדם חשוב]\u0006 \u0003כרב יהודה ליכא הכא דלישרי לך\u0004 \u0005[אין כאן ש\u0006יוכל \u0005להתיר לך],\u0006 \u0003אלא זיל לגביה\u0004 \u0005[לך אל]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 בארץ ישראל \u0003דלישרי לך\u0004 \u0005[שיתיר לך],\u0006 \u0003אזל לקמיה\u0004 \u0005[הלך לפניו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה הנשיא \u0003לר' אמי: פוק\u0004 \u0005[צא]\u0006 \u0003עיין בדיניה\u0004 \u0005[בדינו],\u0006 \u0003אי מיבעי למשרא ליה\u0004 \u0005[אם צריך להתיר לו] —\u0006 \u0003שרי ליה\u0004 \u0005[התר לו\u0006 בשליחותי\u0005].\u0006","\u0003עיין ר' אמי בדיניה\u0004 \u0005[בדינו],\u0006 \u0003סבר למישרא ליה\u0004 \u0005[\u0006ו\u0005חשב להתיר לו],\u0006 \u0003עמד ר' שמואל בר נחמני על רגליו ואמר: ומה שפחה של בית רבי\u0004 שנידתה אדם פעם \u0003לא נהגו חכמים קלות ראש בנידויה\u0004 להתירו עד \u0003שלש שנים, יהודה חבירינו על אחת כמה וכמה,\u0004 שצריך להתחשב בדבריו ואל לנו להתיר את הנידוי.","\u0003אמר ר' זירא: מאי דקמן דאתא האידנא האי סבא בבי מדרשא\u0004 \u0005[מה\u0006 קרה זה \u0005לפנינו שבא עכשיו זקן זה\u0006 ר' שמואל בר נחמני \u0005לבית המדרש]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כמה שני\u0004 \u0005[שנים]\u0006 \u0003לא אתא\u0004 \u0005[בא]\u0006 ובדיוק היום נזדמן בשעת דיון זה, \u0003שמע מינה לא מיבעי למישרא ליה\u0004 \u0005[למד מכאן\u0006 ש\u0005אין צריך להתיר לו]\u0006 שצירוף מאורעות זה — לא מקרה הוא, אלא יש לראותו כהוראת דברים משמים. שנזדמן שבדיוק ביום זה יבא אותו חכם ויביע דעתו זו, \u0003לא שרא ליה\u0004 \u0005[התיר לו].\u0006 \u0003נפק כי קא בכי ואזיל\u0004 \u0005[יצא\u0006 המנודה \u0005כשהוא בוכה והולך],\u0006","\u0003אתא זיבורא וטרקיה אאמתיה ושכיב\u0004 \u0005[באה צירעה ועקצה אותו באמתו,\u0006 באבר, \u0005ומת].\u0006 כיון שהיה תלמיד חכם גדול \u0003עיילוהו למערתא דחסידי\u0004 \u0005[הכניסוהו,\u0006 לקוברו, \u0005למערה ש\u0006בה קוברים את \u0005החסידים]\u0006 \u0003ולא קיבלוהו,\u0004 שעמד נחש בפתח המערה ולא נתן להכניסו, \u0003עיילוהו למערתא דדייני\u0004 \u0005[הכניסו אותו למערה של דיינים]\u0006 \u0003ו\u0004שם \u0003קיבלוהו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 קיבלו אותו במקום זה? ומשיבים: שאף שחטא, מכל מקום \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003כ\u0004דעת \u0003ר' אילעאי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אילעאי אומר: אם רואה אדם שיצרו מתגבר עליו\u0004 ואינו יכול להשתלט עליו — \u0003ילך למקום שאין מכירין אותו, וילבש שחורים ויתעטף שחורים,\u0004 כמנהגם של אבלים שמא ישפיע עליו הדבר ולא יעבור, \u0003ו\u0004אם לא הועיל — \u0003יעשה מה שלבו חפץ, ו\u0004לפחות \u0003אל יחלל שם שמים בפרהסיא.\u0004 וכיון שאותו אדם אף שעבר עבירה עשה זאת בצינעה באופן שלא יהיה חילול השם בגלוי, ראוי היה לקבורה מכובדת.","ושואלים: אותו סיפור שהזכיר רבי שמואל בר נחמני בענין \u0003שפחה של בית רבי מאי היא\u0004 \u0005[מה הוא]?\u0006 ומסופר, \u0003דאמתא דבי\u0004 \u0005[שהמשרתת,\u0006 השפחה, \u0005של בית]\u0006 \u0003רבי חזיתיה לההוא גברא דהוה מחי\u0004 \u0005[ראתה אדם אחד שהיה מכה]\u0006 \u0003לבנו\u0004 ה\u0003גדול אמרה: ליהוי ההוא גברא בשמתא\u0004 \u0005[שיהא אדם זה\u0006 המכה \u0005בנידוי],\u0006 \u0003דקעבר\u0004 \u0005[ש\u0006הרי \u0005הוא עובר]\u0006 \u0003משום \"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד). וכעין מה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר: \u0003\"ולפני עור לא תתן מכשל\" — במכה לבנו גדול הכתוב מדבר,\u0004 שכן אם מכה בן גדול עלול הבן להתרגז ולהכות את אביו ויעבור עבירה חמורה, ולכן אסור לאדם להכות בן גדול.","בענין דומה מסופר: \u0003ריש לקיש הוה מנטר פרדיסא\u0004 \u0005[היה שומר פרדס\u0006 בשכר\u0005],\u0006 \u0003אתא ההוא גברא וקאכיל תאיני\u0004 \u0005[בא אדם אחד ואכל תאנים\u0006 מאותו פרדס\u0005],\u0006 \u0003רמא ביה קלא\u0004 \u0005[הרים בו קולו,\u0006 צעק עליו\u0005]\u0006 \u0003ולא אשגח ביה\u0004 \u0005[השגיח בו]\u0006 אותו האיש והמשיך לאכול. \u0003אמר\u0004 ריש לקיש: \u0003להוי ההוא גברא בשמתא\u0004 \u0005[שיהא אותו איש בנידוי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003אדרבה, להוי ההוא גברא בשמתא\u0004 \u0005[להיפך, יהא אותו איש,\u0006 ריש לקיש \u0005בנידוי],\u0006 שכן, \u0003אם ממון נתחייבתי לך\u0004 שנטלתי תאנים שלא ברשות, \u0003נידוי מי\u0004 \u0005[האם]\u0006 \u0003נתחייבתי לך?\u0004 והלך אותו אדם משם.","\u0003אתא לבי מדרשא\u0004 \u0005[בא\u0006 ריש לקיש \u0005לבית המדרש]\u0006 לשאול מה דינו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 הנידוי \u0003שלו,\u0004 של אותו אדם — \u0003נידוי,\u0004 והרי אתה מנודה, ואילו הנידוי \u0003שלך — אינו נידוי,\u0004 שכן צדק אותו אדם, שלא היתה לך זכות לנדותו על מה שעשה.","ושאל אם כן \u0003ומאי תקנתיה\u0004 \u0005[ומה תקנתו]\u0006 של נידוי זה? ענו לו חכמים: \u0003זיל לגביה דלישרי לך\u0004 \u0005[לך אליו שיתיר לך].\u0006 אמר להם: \u0003לא ידענא ליה\u0004 \u0005[אינני מכיר אותו],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל לגבי נשיאה דלישרי לך\u0004 \u0005[לך אל הנשיא שיתיר לך],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נידוהו ואינו יודע מי נידהו — ילך אצל\u0004 ה\u0003נשיא, ויתיר לו נדויו.\u0004","ועוד בענין נידוי \u0003אמר רב הונא, באושא התקינו: אב בית דין שסרח\u0004 בעבירה — \u0003אין מנדין אותו,\u0004 אף על פי שראוי לכך כדי לא להביא לחילול השם, \u0003אלא אומר לו\u0004 כלשון הכתוב: \u0003\"הכבד ושב בביתך\"\u0004 (מלכים ב' יד, י), כלומר, יהיה זה לכבודך אם תשאר בביתך ולא תשמש בתפקידך ולא תבוא בציבור. \u0003חזר וסרח — מנדין אותו\u0004 אפילו בפרהסיה, \u0003מפני חילול השם,\u0004 שלא יאמרו שכיוון שאדם גדול הוא אין חכמים מענישים אותו כראוי, ומעירים:","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש: תלמיד חכם שסרח — אין מנדין אותו בפרהסיא\u0004 כלל, \u0003שנאמר: \"וכשלת היום וכשל גם נביא עמך לילה\"\u0004 (הושע ד, ה), ופירושו: שאם הנביא, כלומר, אדם גדול, כושל בעבירה — \u0003כסהו כלילה,\u0004 ואין מענישים אותו בפומבי.","באותו ענין מסופר: \u0003מר זוטרא חסידא\u0004 \u0005[החסיד],\u0006 \u0003כי מיחייב צורבא מרבנן שמתא\u0004 \u0005[כאשר היה מתחייב\u0006 לפניו \u0005תלמיד חכם בנידוי],\u0006 \u0003ברישא משמית נפשיה, והדר משמית לדידיה\u0004 \u0005[בתחילה היה מנדה את עצמו\u0006 משום כבודו של התלמיד החכם, \u0005ואחר כך היה מנדה את אותו\u0006 תלמיד חכם\u0005].\u0006 והיות ונידוי עצמו היה רק משום כבודו של התלמיד חכם שנידה, לכן \u0003כי הוה עייל באושפיזיה שרי ליה לנפשיה, והדר שרי ליה לדידיה\u0004 \u0005[כאשר היה נכנס למלונו היה מתיר לעצמו\u0006 את הנידוי, \u0005ואחר כך היה מתיר לו לאותו\u0006 אדם\u0005].\u0006","\u0003אמר רב גידל אמר רב: תלמיד חכם מנדה לעצמו,\u0004 כלומר, את עצמו, \u0003ו\u0004כן \u0003מיפר לעצמו\u0004 את הנידוי הזה. \u0003אמר רב פפא: תיתי\u0004 \u0005[תבוא]\u0006 \u0003לי\u0004 טובה, כלומר, משתבח אני בכך ש\u0003לא שמיתי צורבא מרבנן\u0004 \u0005[נדיתי תלמיד חכם]\u0006 \u0003מעולם.\u0004 ושואלים: אם כן, \u0003אלא כי קא מיחייב צורבא מרבנן שמתא, היכי עביד\u0004 \u0005[כאשר מתחייב תלמיד חכם נידוי, מה היה עושה]?\u0006 ומשיבים: \u0003כי הא דבמערבא מימנו אנגידא דצורבא מרבנן ולא מימנו אשמתא\u0004 \u0005[כמו זה, שבארץ ישראל היו נמנים\u0006 ומחליטים בבית דין על \u0005הלקאת תלמיד חכם ולא היו נמנים על נידוי],\u0006 שהעדיפו עונש מלקות על נידוי.","וכעין הסבר לחומרת העונש שבנידוי, \u0003מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"שמתא\"? אמר רב:\u0004 הוא נוטריקון \u0003שם מיתה,\u0004 שהוא רמז שיש בנידוי ענין של מיתה. \u0003ושמואל אמר:\u0004 \"שמתא\" פירושו — \u0003שממה יהיה, ומהניא ביה כי טיחיא בתנורא\u0004 \u0005[ומועילה,\u0006 נכנסת \u0005בו כמו שומן\u0006 שטחים \u0005בתנור],\u0006 שכשם שנשאר שומן בלוע בתנור, כך נשאר תמיד משהו מן הקללה שבנידוי גם לאחר שמתירים אותו.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: כשם שנכנסת\u0004 השמתא \u0003במאתים וארבעים ושמונה איברים\u0004 כשמטילים אותה, \u0003כך כשהיא יוצאה — יוצאה ממאתים וארבעים ושמונה איברים.\u0004","ורמז לדבר: \u0003כשהיא נכנסת — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיתה העיר חרם\"\u0004 (יהושע ו, יז), ו\u0003\"חרם\" בגימטריא\u0004 לפי חשבון האותיות \u0003מאתים וארבעים ושמונה הוו\u0004 \u0005[הם],\u0006 לרמז שהחרם נכנס במאתים ארבעים ושמונה איברים. \u0003כשהיא יוצאה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ברגז רחם תזכור\"\u0004 (חבקוק ג, ב), ו\u0003\"רחם\" בגימטריא הכי הוו\u0004 \u0005[כך הם\u0006 גם כן\u0005]\u0006 מאתים ארבעים ושמונה, ללמד שכאשר מתירים הכל מתבטל.","ועוד בענין כח הנידוי. \u0003אמר רב יוסף: שדי שמתא אגנובתא דכלבא ואיהי דידה עבדה\u0004 \u0005[הטל נידוי על זנבו של כלב והוא\u0006 הנידוי \u0005יעשה את שלו,\u0006 יזיק\u0005].\u0006 ומסופר: \u0003דההוא כלבא דהוה אכיל מסאני דרבנן ולא הוו קא ידעי מנו\u0004 \u0005[\u0006היה \u0005כלב אחד שהיה אוכל\u0006 את \u0005נעליהם של החכמים ולא היו יודעים מי הוא]\u0006 המזיק, וחשבו שאדם הוא \u0003ושמתו ליה\u0004 \u0005[ונידו אותו]\u0006 \u0003איתלי ביה נורא בגנובתיה ואכלתיה\u0004 \u0005[נתפסה אש בזנבו ושרפתו],\u0006 הרי שהנידוי פועל אפילו על כלב.","מסופר: \u0003ההוא אלמא דהוה קא מצער ליה לההוא צורבא מרבנן\u0004 \u0005[\u0006היה \u0005איש אלים אחד שהיה מצער תלמיד חכם אחד],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 אותו תלמיד חכם \u0005לפני]\u0006 \u0003רב יוסף\u0004 לשאול מה לעשות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שמתיה\u0004 \u0005[לך נדהו]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתפינא מיניה\u0004 \u0005[מתיירא אני ממנו]\u0006 שירדוף אותי יותר.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שקילי פתיחא עליה\u0004 \u0005[קח\u0006 וכתוב \u0005עליו כתב נידוי],\u0006 אמר לו: \u0003כל שכן דמסתפינא מיניה\u0004 \u0005[שאני מתיירא ממנו],\u0006 שאם אפרסם את הדבר בכתב בוודאי ירדפני. \u0003אמר ליה\u0004 \u0005[לו]\u0006 כך תעשה: \u0003שקליה, אחתיה בכדא\u0004 \u0005[קח אותו,\u0006 את כתב הנדוי, \u0005והנח אותו בכד],\u0006"],["\u0003ואחתיה בי קברי\u0004 \u0005[והנח אותו בבית הקברות]\u0006 שאין אנשים מצויים שם, \u0003וקרי ביה אלפא שפורי בארבעין יומין\u0004 \u0005[וקרא,\u0006 תקע \u0005בו אלף,\u0006 כלומר הרבה תקיעות \u0005שופר ב\u0006משך \u0005ארבעים ימים]\u0006. \u0003אזיל עביד הכי\u0004 \u0005[הלך\u0006 אותו איש ו\u0005עשה כך],\u0006 \u0003פקע כדא\u0004 \u0005[הכד]\u0006 \u0003ומית אלמא\u0004 \u0005[ומת\u0006 האיש \u0005האלים\u0006 הזה\u0005].\u0006 ומעירים: \u0003מאי שפורי\u0004 \u0005[מה\u0006 טעם \u0005שופרות]\u0006 שתוקעים בהם בזמן נידוי — שהם רמז \u0003שנפרעין ממנו\u0004 (שופר — שפורע),","וכך מסבירים: \u0003מאי תברא\u0004 \u0005[מה\u0006 טעם תוקעים תקיעת \u0005שברים]\u0006 בזמן הנידוי? \u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: תברי בתי רמי\u0004 \u0005[שובר בתים גבוהים],\u0006 שפוגע והורס אף באנשים גדולים ותקיפים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006, \u0003אמר רבן שמעון בן גמליאל: כל מקום ש\u0004אמרו \u0003\"נתנו חכמים עיניהם\"\u0004 בהקפדה על מישהו, \u0003או\u0004 שגרם הדבר ל\u0003מיתה או\u0004 ל\u0003עוני.\u0004","שנינו במשנה: \u0003והנזיר והמצורע\u0004 שיצאו \u0003מטומאתו לטהרתו\u0004 בחול המועד, מותרים להסתפר בחול המועד. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 האם היתר זה להסתפר בחול המועד הוא דווקא \u0003בשלא היה להם פנאי\u0004 להסתפר לפני החג שהיו אסורים עד אז בתספורת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אף בשהיה להם פנאי?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה בברייתא: \u0003כל אלו שאמרו מותרין לגלח במועד — בשלא היה להם פנאי\u0004 קודם לכן, \u0003אבל היה להם פנאי — אסורים.\u0004","אולם \u0003נזיר ומצורע, אף על פי שהיה להם פנאי — מותרים.\u0004 ומדוע התירו להם — כדי \u0003שלא ישהו קרבנותיהן,\u0004 שהרי צריכים הם לגלח לפני שמקריבים קרבן לטהרתם, ואם לא יתירו להם לגלח לא יקריבו את קרבנם בזמן.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003הכהן והאבל מותרין בגילוח\u0004 בחול המועד. ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003אבל היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שחל שמיני שלו\u0004 של אבל, \u0003בערב הרגל —\u0004 אם כן \u0003איבעי ליה לגלוחי\u0004 \u0005[היה צריך לו לגלח]\u0006 \u0003בערב הרגל,\u0004 שהרי כבר בטלה חומרת האבילות! \u0003אלא — שחל שמיני שלו להיות בשבת ערב הרגל.\u0004","אולם אז גם כן \u0003איבעי ליה לגלוחי\u0004 \u0005[היה לו לגלח]\u0006 \u0003ערב שבת,\u0004 ש\u0003אמר רב חסדא אמר רבינא בר שילא: הלכה כאבא שאול,\u0004 שאם נקבר המת שבעת ימים קודם הרגל — לא רק השלים כל שבעת ימי אבילות, אלא נחשב כאילו כבר התחיל לנהוג אבילות של שלושים, וכיון שהגיע הרגל הריהו מפסיק את האבילות הזו. \u0003ומודים חכמים לאבא שאול בשחל\u0004 היום ה\u0003שמיני שלו\u0004 של האבל \u0003להיות בשבת ערב הרגל — שמותר לגלח בערב שבת\u0004 כיון שאנוס הוא ואינו יכול לגלח בשמיני התירו לו בשביעי?!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרך]\u0006 אלא לאופן \u0003שחל שביעי שלו להיות בשבת ערב הרגל,\u0004 שודאי אינו יכול להסתפר בערב שבת שהוא היום השישי לאבלו.","ומעירים, \u0003תנא ברא\u0004 \u0005[התנא החיצון,\u0006 של הברייתא\u0005]\u0006 המתיר גילוח לאבל בחול המועד, \u0003סבר לה\u0004 \u0005[סובר הוא]\u0006 \u0003כאבא שאול,\u0004 ש\u0003אמר: מקצת היום ככולו, ויום שביעי עולה לו לכאן ולכאן,\u0004 כאחרון של שבעה, וכראשון של שלושים. ומצד דיני אבל מותר היה לו לגלח, אלא \u0003וכיון\u0004 שיום זה \u0003שבת הוי\u0004 \u0005[הוא]\u0006 — \u0003אנוס הוא,\u0004 ולכן מותר לגלח ברגל.","\u0003תנא דידן סבר לה כרבנן\u0004 \u0005[התנא שלנו\u0006 במשנה האוסר גילוח לאבל \u0005סבור כ\u0006דעת \u0005חכמים]\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מקצת היום ככולו\u0004 באבל \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003לא שלים\u0004 \u0005[נשלמה]\u0006 \u0003אבילות\u0004 של \u0003שבעה\u0004 ולכן לא הותר לו לגלח ברגל.","ועוד שואלים: \u0003האי כהן היכי דמי\u0004 \u0005[כהן זה\u0006 שהזכרנו שמותר לגלח ברגל \u0005כיצד היה בדיוק]?\u0006 \u0003אילימא דשלים\u0004 \u0005[אם תאמר שהשלים]\u0006 את \u0003משמרתו ערב הרגל — איבעי ליה לגלוחי\u0004 \u0005[צריך היה לו לגלח]\u0006 \u0003ערב הרגל!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דשלים\u0004 \u0005[שהשלים]\u0006 \u0003משמרתו ברגל\u0004 עצמו. ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003סבר: כיון דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בשלשה פרקים\u0004 בשלושת הרגלים \u0003בשנה היו כל המשמרות שוות\u0004 בזכויותיהם, והיו מתחלקות בשווה \u0003באימורי\u0004 (קרבנות) \u0003הרגלים, ובחילוק לחם הפנים\u0004 המתחלק לכהנים בשבת שברגל. וכיון שברגל משמשות כל המשמרות כאחת, \u0003כמאן דלא שלים\u0004 \u0005[כמי שלא השלים]\u0006 את \u0003משמרתו ברגל דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואסור בתספורת עד סוף הרגל, \u0003ו\u0004ה\u0003תנא ברא\u0004 \u0005[החיצון]\u0006 של הברייתא \u0003סבר: אף על גב\u0004 \u0005[אף על פי]\u0006 שהוא \u0003שייך בהנך\u0004 \u0005[באותן]\u0006 \u0003משמרות\u0004 שברגל, \u0003משמרתיה מיהא שלימא ליה\u0004 \u0005[משמרתו שלו על כל פנים נשלמה לו]\u0006 ומותר לו לגלח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל אלו שאמרו\u0004 שהם \u0003מותרין לגלח במועד\u0004 כשלא הספיקו לגלח קודם מפני האונס — \u0003מותרין לגלח בימי אבלן\u0004 אם קודם לכן לא גילחו מחמת אונס.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת האומרת ש\u0003אסורים\u0004 לגלח בימי אבלם! \u0003אמר רב חסדא אמר רב שילא: כי תניא הכא\u0004 \u0005[כאשר שנינו\u0006 בברייתא \u0005כאן]\u0006 \u0003מותרין —\u0004 הוא כש\u0003תכפוהו אבליו,\u0004 שהיתה לו אבילות אחר אבילות ואינו יכול לסבול במשך זמן רב.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשתכפוהו אבליו מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003כל אלו שאמרו, אפילו כולי עלמא נמי\u0004 \u0005[כל העולם גם כן]?\u0006 ולא רק אלה שהיו אנוסים קודם, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תכפוהו אבליו זה אחר זה,\u0004 אם \u0003הכביד שערו — מיקל\u0004 וחותך משערו \u0003בתער, ומכבס כסותו במים\u0004 שלא יתענה זמן רב כל כך בלא תספורת וכביסה.","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 בפירושה של ברייתא זו, ש\u0003אמר רב חסדא:\u0004 מה שאמרו שמותר להסתפר הרי הוא \u0003בתער\u0004 בלבד \u0003ולא במספרים,\u0004 ולכבס, מותר לו \u0003במים ולא בנתר ולא באהל\u0004 (מיני סבון). ולכן הברייתא שלנו באה ללמד, שאם היה אונס אחר קודם לכן רשאי האבל שתכפוהו אבליו לגלח כדרכו, ואיננו צריך לעשות בשינוי. \u0003אמר רב חסדא: זאת אומרת,\u0004 מן הברייתא אפשר ללמוד את הדין הכללי ש\u0003אבל אסור בתכבוסת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשם שאמרו\u0004 ש\u0003אסור לגלח ב\u0004חול ה\u0003מועד, כך אסור ליטול צפורנים במועד,\u0004 אלו \u0003דברי ר' יהודה. ור' יוסי מתיר\u0004 ליטול צפורנים.","\u0003וכשם שאמרו אבל אסור לגלח בימי אבלו — כך אסור ליטול צפורנים בימי אבלו,\u0004 אלו \u0003דברי ר' יהודה. ור' יוסי מתיר.\u0004","\u0003אמר עולא: הלכה כר' יהודה באבל, והלכה כר' יוסי במועד.\u0004 ו\u0003שמואל אמר:\u0004"],["\u0003הלכה כר' יוסי במועד ו\u0004גם \u0003באבל.\u0004 ש\u0003אמר שמואל\u0004 כלל: \u0003הלכה כדברי המיקל באבל.\u0004","מסופר: \u0003פנחס אחוה\u0004 \u0005[אחיו]\u0006 של \u0003מר שמואל איתרע ביה מילתא\u0004 \u0005[אירע בו דבר\u0006 של אבילות\u0005],\u0006 \u0003על\u0004 \u0005[נכנס]\u0006 \u0003שמואל למישאל טעמא מיניה\u0004 \u0005[לשאול טעם ממנו],\u0006 כלומר, לדבר על לבו ולנחמו. \u0003חזנהו לטופרי דהוו נפישן\u0004 \u0005[ראה את צפרניו\u0006 של פנחס \u0005שהיו גדולות],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי לא שקלת להו\u0004 \u0005[מדוע אינך נוטל אותן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 פנחס: \u0003אי בדידיה הוה, מי מזלזלת ביה כולי האי\u0004 \u0005[אם בשלו\u0006 \u0005היה\u0006 האבל, \u0005האם היה מזלזל בו כל כך]?\u0006 כלומר, אילו היית אתה אבל, האם גם אז היית מזלזל בכך?","ומעירים: \u0003הואי\u0004 \u0005[היה]\u0006 הדבר שאמר פנחס \u0003\"כשגגה שיצא מלפני השליט\"\u0004 (קהלת י, ה), שכיון שהוציא דבר זה מפיו, אף שלא התכוון לכך, נתקיים, \u0003ואיתרע ביה מילתא\u0004 \u0005[ואירע בו דבר\u0006 אבילות\u0005]\u0006 \u0003בשמואל. על\u0004 \u0005[נכנס]\u0006 \u0003פנחס אחוה\u0004 \u0005[אחיו]\u0006 \u0003למישאל טעמא מיניה\u0004 \u0005[לשאול טעם ממנו,\u0006 לדבר על לבו\u0005].\u0006 \u0003שקלינהו לטופריה חבטינהו לאפיה\u0004 \u0005[לקח\u0006 שמואל \u0005את צפרניו\u0006 שחתך אותן \u0005וזרק אותן בפניו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: האם \u0003לית\u0004 \u0005[אין]\u0006 \u0003לך,\u0004 האם אינך יודע את הכלל ש\u0003ברית כרותה לשפתים?\u0004 כלומר, שדבר שאדם מוציא מפיו, גורם שדבר זה יבוא.","ש\u0003אמר ר' יוחנן: מנין שברית כרותה לשפתים,\u0004 שמאמר פיו של אדם משפיע ומתקיים — \u0003שנאמר: \"ויאמר אברהם אל נעריו שבו לכם פה עם החמור ואני והנער נלכה עד כה ונשתחוה ונשובה אליכם\"\u0004 (בראשית כב, ה), אף שחשב שהוא מוליך את בנו לעקידה ולא יחזור עמו, \u0003ואיסתייעא מלתא דהדור תרוייהו\u0004 \u0005[והסתייע הדבר שחזרו שניהם].\u0006","ובהלכה זו מעירים: \u0003סבור מיניה\u0004 \u0005[חשבו מכאן]\u0006 שלהסיר את הצפרנים של ה\u0003יד\u0004 באבילות — \u0003אין\u0004 \u0005[כן]\u0006 מותר, ואולם של ה\u0003רגל — לא,\u0004 כיון שאינו מאוס כל כך. \u0003אמר רב ענן בר תחליפא: לדידי מפרשא לי מיניה\u0004 \u0005[לי עצמי נתפרש\u0006 הדבר \u0005מאת]\u0006 \u0003שמואל: לא שנא\u0004 \u0005[אינו שונה]\u0006 צפרני ה\u0003יד ולא שנא\u0004 \u0005[ואינו שונה]\u0006 צפרני ה\u0003רגל,\u0004 והכל מותר.","\u0003אמר רב חייא בר אשי אמר רב: ובגנוסטרא\u0004 \u0005[מספריים\u0006 מיוחדים לצפרנים\u0005]\u0006 — \u0003אסור\u0004 ליטול, שראוי שיעשה בשינוי. \u0003אמר רב שמן בר אבא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003ר' יוחנן בי מדרשא\u0004 \u0005[בבית המדרש]\u0006 \u0003בחולו של מועד ושקלינהו לטופריה בשיניה וזרקינהו\u0004 \u0005[ונטל את צפרניו בשיניו וזרק אותן\u0006 שם\u0005].\u0006","ומעירים: ממעשהו של ר' יוחנן \u0003שמע מינה תלת\u0004 \u0005[למד מכאן שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מותר ליטול צפרנים בחולו של מועד, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003אין בהן משום מיאוס,\u0004 שאסור לאדם לשים דבר מאוס בפיו, ולמדנו שאין צפרנים נחשבות לדבר מאוס, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 גם ש\u0003מותר לזרקן\u0004 את הצפרנים.","ושואלים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלשה דברים נאמרו בצפרנים: הקוברן\u0004 באדמה — \u0003צדיק,\u0004 אם \u0003שורפן —\u0004 הרי הוא יותר מכן, שהוא \u0003חסיד,\u0004 אם \u0003זורקן\u0004 סתם — \u0003רשע.\u0004 ומסבירים: \u0003טעמא מאי\u0004 \u0005[הטעם מהו]\u0006 שאסור להשליך צפרנים — \u0003שמא תעבור עליהן אשה עוברה\u0004 (מעוברת) \u0003ותפיל,\u0004 שכך קיבלו שמסוכן לאשה הרה לדרוך על צפרנים,","ומשיבים: \u0003אשה בי מדרשא\u0004 \u0005[בבית המדרש]\u0006 \u0003לא שכיחא\u0004 \u0005[איננה מצויה]\u0006 ולכן לא חשש רבי יוחנן לזרוק צפרניו שם. \u0003וכי תימא: זימנין דמיכנשי להו ושדי להו אבראי\u0004 \u0005[ואם תאמר פעמים שאוספים אותן\u0006 כשמטאטאים את המקום, \u0005וזורקים אותן החוצה]\u0006 ושם יכולה לעבור אשה — \u0003כיון דאשתני אישתני\u0004 \u0005[שהשתנו\u0006 ממקום הנחתן הראשון \u0005השתנו]\u0006 ושוב אינן מזיקות.","\u0003אמר רב יהודה אמר רב: זוג\u0004 של חכמים \u0003בא מ\u0004המקום \u0003חמתן לפני רבי, ומר זוטרא מתני\u0004 \u0005[היה שונה]\u0006 זאת כברייתא בלי הזכרת שמותיהם של רב יהודה ושל רב: \u0003זוג בא מחמתן לפני רבי, ובקשו ממנו\u0004 (שאלוהו) בענין \u0003צפרנים\u0004 האם מותר לנוטלן באבילות — \u0003והתיר להם. ואם בקשו\u0004 (היו מבקשים) \u0003ממנו\u0004 להתיר להם לגזוז את ה\u0003שפה\u0004 (שפם), גם כן \u0003התיר\u0004 (היה מתיר) \u0003להם,\u0004 שאין בכך משום \"ולא תשחית את פאת זקנך\" (ויקרא יט, כז)\u0003. ושמואל אמר: אף בקשו ממנו\u0004 היתר לגזיזת ה\u0003שפה ו\u0004אכן \u0003התיר להם.\u0004","\u0003אמר אביטול ספרא\u0004 \u0005[הסופר]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: שפה\u0004 מותר לתקנה \u0003מזוית לזוית\u0004 של הפה. \u0003אמר ר' אמי: ובשפה המעכבת\u0004 מותר רק בחלק של השפם שמעכב מלאכול ולא לשם נוי. \u0003אמר רב נחמן בר יצחק: לדידי\u0004 \u0005[לי]\u0006 כל השפם \u0003כשפה המעכבת דמי\u0004 \u0005[נחשב]\u0006 \u0003לי,\u0004 ויכול אני לגלח את כולו.","כיון שהוזכר שמו של אביטול ספרא מביאים דברים נוספים בשמו, ש\u0003אמר אביטול ספרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: פרעה שהיה בימי משה, הוא\u0004 היה גבוה \u0003אמה, וזקנו\u0004 היה ארוך \u0003אמה, ופרמשתקו\u0004 (אברו) היה \u0003אמה וזרת, לקיים מה שנאמר: \"ושפל אנשים יקים עלה\"\u0004 (דניאל ד, יד), מלמד שהיה ננס ובזוי (שפל = קטן).","\u0003ו\u0004עוד \u0003אמר אביטול ספרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: פרעה שהיה בימי משה אמגושי\u0004 (מכשף) \u0003היה, שנאמר: \"הנה יצא המימה\"\u0004 (שמות ז, טו), ויציאה זו המימה היתה לצורך כישוף שעשה בכל פעם.","שנינו במשנה: \u0003ואלו מכבסין במועד, הבא ממדינת הים. אמר רב אסי אמר ר' יוחנן: מי שאין לו אלא חלוק אחד — מותר לכבסו בחולו של מועד.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' ירמיה\u0004 ממה ששנינו: \u0003אלו מכבסין במועד, הבא ממדינת הים כו'.\u0004 ונדייק: \u0003הני אין\u0004 \u0005[אלה]\u0006 שנמנו במשנה — \u0005[כן],\u0006 אולם \u0003מי שאין לו אלא חלוק אחד — לא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה: אסברה\u0004 \u0005[אסביר]\u0006 \u0003לך, מתניתין אף על גב דאית ליה תרי ומטנפי\u0004 \u0005[\u0006ב\u0005משנתנו\u0006 מדובר \u0005אפילו כשיש לו שניים ו\u0006הם \u0005מלוכלכים],\u0006 ורבי יוחנן מדבר במי שיש לו בגד אחד שמותר לכבס בכל אופן.","\u0003שלח רב יצחק בר יעקב בר גיורי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: כלי פשתן מותר לכבסן בחולו של מועד\u0004 משום שמזדהמים ביותר. \u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003מטפחות הידים\u0004 שמנגבים בהם את הידים, \u0003מטפחות\u0004"],["\u0003הספרים\u0004 שמניחים על אנשים בזמן שמסתפרים, מותר לכבס במועד. ונדייק: \u0003הני\u0004 — \u0003אין\u0004 \u0005[אלה\u0006 — \u0005כן],\u0006 אולם \u0003כלי פשתן\u0004 אחרים — \u0003לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו קושיה; \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003אפילו\u0004 בבגדים של \u0003שאר מיני\u0004 \u0005[מינים],\u0006 אבל בשל פשתן אפילו בגדים אחרים מותרים. \u0003אמר בר הידיא: לדידי חזי לי\u0004 \u0005[אני ראיתי]\u0006 את \u0003ימה של טבריה\u0004 \u0005[טבריה],\u0006 ים כנרת, \u0003דמפקי לה משיכלי דמני כיתנא בחולא דמועדא\u0004 \u0005[שמוציאים לשם אגנות של כלי פשתן\u0006 לכבסם \u0005בחול המועד].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי:\u0004 מכאן אין ראיה להלכה, \u0003מאן לימא לן\u0004 \u0005[מי אומר לנו]\u0006 ש\u0003ברצון חכמים עבדי\u0004 \u0005[\u0006הם \u0005עושים\u0006 זאת\u0005],\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003שלא ברצון חכמים עבדי\u0004 \u0005[\u0006הם \u0005עושים].\u0006","\u0003ואלו\u0004 הדברים ש\u0003כותבין ב\u0004חול ה\u0003מועד: קדושי נשים\u0004 אם כותב שטר (ואינו נותן כסף) לשם קידושין, \u0003וגיטין, ושוברין\u0004 (קבלות של חוב), \u0003דייתיקי\u0004 (שטר צוואה), שטרי \u0003מתנה, ופרוזבולין\u0004 שהמלווה כותב שמוסר את חובותיו לבית דין שלא יצטרך לוותר עליהם בשמיטה, \u0003איגרות שום\u0004 שכותבים בבית דין ששמו (העריכו) נכסים מסויימים והעבירום למלווה, \u0003ואיגרות מזון\u0004 שאדם קיבל על עצמו לזון את מישהו, בדרך כלל את ילדיו החורגים, שכותב זאת בכתובה.","\u0003שטרי חליצה\u0004 שמודיעים בית דין שעשו חליצה, או שעשו שטר \u0003מיאונים\u0004 (שילדה שהשיאו אותה אמה או אחיה יכולה למאן בנישואין ולבטלם) וכותבים לה שטר ראיה למיאון זה. \u0003ושטרי בירורין\u0004 שבית דין מסכמים סכסוך שנתברר בדרך של בוררות. \u0003גזרות\u0004 (פסקים) של \u0003בית דין, ואיגרות של רשות\u0004 מכתבים רשמיים של השלטונות.","\u0003אמר שמואל: מותר לארס אשה בחולו של מועד שמא יקדמנו אחר\u0004 ויארסנה. ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[נאמר שנסייע לו]\u0006 ממשנתנו: \u0003ואלו כותבין במועד — קדושי נשים,\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ל\u0003שטרי קדושין ממש\u0004 שבהם עצמם מארסים אשה? ודוחים: \u0003לא,\u0004 מוזכר כאן \u0003שטרי פסיקתא\u0004 \u0005[שטרי פסק],\u0006 \u0003וכ\u0004פי שהסביר זאת \u0003רב גידל\u0004 ש\u0003אמר\u0004 בשם \u0003רב.\u0004","ש\u0003אמר רב גידל אמר רב:\u0004 כאשר שתי משפחות מתחתנות זו בזו, כשאחד המחותנים אומר לשני: \u0003כמה אתה נותן לבנך\u0004 לצורך הנדוניה והשני אומר: \u0003כך וכך,\u0004 ומצד שני \u0003כמה אתה נותן לבתך — כך וכך. עמדו\u0004 החתן והכלה \u0003וקדשו קנו, הן הן הדברים הנקנין באמירה\u0004 שאין צורך לעשות קנין נוסף לקיים את ההסכם הזה ועל שטר כזה מדברת המשנה.","ועוד מציעים: \u0003לימא מסייע ליה\u0004 \u0005[נאמר שמסייעת לו]\u0006 לשמואל המשנה: \u0003אין נושאין נשים ב\u0004חול ה\u0003מועד, לא בתולות ולא אלמנות, ו\u0004אף \u0003לא מיבמין\u0004 אשת אח שמת בלא בנים \u0003מפני ששמחה היא לו.\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003לארס — שרי\u0004 \u0005[מותר].\u0006","ודוחים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 וכך יש להבין! ש\u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003לארס דלא קעביד\u0004 \u0005[שאינו עושה]\u0006 \u0003מצוה\u0004 באירוסין, ובודאי שאסור, \u0003אלא אפילו לישא נמי\u0004 \u0005[גם כן]\u0006 \u0003דקא עביד\u0004 \u0005[שהוא\u0006 \u0005עושה]\u0006 \u0003מצוה,\u0004 שהרי זו הכנה למצוות פריה ורביה, בכל זאת \u0003אסור.\u0004","ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל\u0004 ברייתא זו: \u0003מארסין\u0004 בחול המועד, \u0003אבל לא כונסין\u0004 (נושאין) \u0003ואין עושין סעודת אירוסין, ולא מיבמין, מפני ששמחה היא לו\u0004 ואין מערבים שמחה בשמחה, שמחת הנישואין בשמחת החג. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","לעצם הדברים שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל\u0004 שיש לחשוש ל\u0003שמא יקדמנו אחר? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל: בכל יום ויום בת קול יוצאת ואומרת: בת פלוני\u0004 היא אשתו המיועדת של \u0003פלוני, שדה פלוני\u0004 תגיע \u0003לפלוני.\u0004 ואם כן למה לו לחשוש, שהרי בוודאי ישא את בת זוגו היעודה לו!","\u0003אלא\u0004 כך יש להבין את דברי שמואל: \u0003שמא יקדמנו אחר ברחמים,\u0004 שיבוא אחר ויתפלל ויבטל את הגזירה הזאת, ולכן ראוי לו להזדרז.","ומספרים: \u0003כי הא\u0004 \u0005[כמו\u0006 סיפור \u0005זה]\u0006 ש\u0003רבא שמעיה לההוא גברא דבעי רחמי\u0004 \u0005[שמע אדם אחד שהתפלל]\u0006 \u0003ואמר: תזדמן לי פלניתא\u0004 \u0005[פלונית]\u0006 לאשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לא תיבעי רחמי הכי\u0004 \u0005[אל תבקש רחמים,\u0006 תתפלל \u0005כך]\u0006 \u0003אי חזיא\u0004 \u0005[אם ראויה]\u0006 היא \u0003לך,\u0004 שנגזר על כך — היא \u0003לא אזלא מינך\u0004 \u0005[תלך ממך]\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 שאיננה ראויה לך — \u0003כפרת\u0004 \u0005[\u0006אתה \u0005תכפור]\u0006 \u0003בה',\u0004 כשתראה שלא נתקבלה תפלתך. \u0003בתר הכי\u0004 \u0005[אחר כך]\u0006 לאחר שנשא אותה אשה \u0003שמעיה דקאמר\u0004 \u0005[שמע אותו ש\u0006הוא \u0005אומר]\u0006 בתפילתו: \u0003או איהו לימות מקמה\u0004 \u0005[שהוא ימות לפניה]\u0006 \u0003או איהי תמות מקמיה\u0004 \u0005[שהיא תמות לפניו],\u0006 מפני ששנא אותה ביותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לאו אמינא לך לא תיבעי עלה דמילתא\u0004 \u0005[האם לא אמרתי לך אל תתפלל על הדבר]?\u0006","\u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב משום ר' ראובן בן אצטרובילי: מן התורה ומן הנביאים ומן הכתובים\u0004 למדים אנחנו ש\u0003מה'\u0004 יוצא הדבר שמתחברת \u0003אשה לאיש.\u0004 כיצד \u0003מן התורה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויען לבן ובתואל ויאמרו מה' יצא הדבר\"\u0004 (בראשית כד, נ). \u0003מן הנביאים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואביו ואמו לא ידעו כי מה' היא\"\u0004 (שופטים יד, ד). \u0003מן הכתובים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בית והון נחלת אבות ומה' אשה משכלת\"\u0004 (משלי יט, יד).","כיון שהזכירו את דברי רבי ראובן בן איצטרובילי, מביאים דבר נוסף ש\u0003אמר רב משום ר' ראובן בן איצטרובילי, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא\u0006 היא \u0005שנויה];\u0006 \u0003אמר ר' ראובן בן איצטרובילי: אין אדם נחשד בדבר\u0004 של עבירה \u0003אלא אם כן עשאו, ואם לא עשה כולו — עשה מקצתו, ואם לא עשה מקצתו — הרהר בלבו לעשותו, ואם לא הרהר בלבו לעשותו — ראה אחרים שעשו ושמח.\u0004 שאין אדם נחשד בלא כל סיבה אלא ודאי יש משהו הגורם שיחשדו בו בעבירה מסויימת.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003ר' יעקב:\u0004 הלא נאמר: \u0003\"ויחפאו בני ישראל דברים אשר לא כן על ה' אלהיהם\"\u0004 (מלכים ב' יז, ט), משמע שאפשר להעליל דבר שאיננו נכון כלל! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003להכעיס הוא דעבוד\u0004 \u0005[שעשו],\u0006 ולא חשבו כן באמת.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 סתירה ממקום אחר: שעל הכתוב \u0003\"ויקנאו למשה במחנה לאהרן קדוש ה' \"\u0004(תהלים קו, טז) \u0003רב שמואל בר יצחק אמר:\u0004 פסוק זה \u0003מלמד שכל אחד קינא לאשתו ממשה,\u0004 שכל אחד חשד שאשתו נסתרת עם משה למעשה עבירה, והוא בודאי לא עשה, הרי שקיימת אפשרות לחשוד אף באדם הנקי מחטא! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום שנאה\u0004 למשה \u0003הוא דעבוד\u0004 \u0005[שעשו],\u0006 ולא שבאמת חשדו בו, אלא כדי לבזותו האשימו אותו.","ומקשים שוב ממקום אחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003אמר ר' יוסי: יהא חלקי עם מי שחושדין אותו בדבר ואין בו,\u0004 שיש בכך משום כפרת עוונות בצער שמצטער על כך. הרי שאפשר לחשוד במישהו שאין בו כלום, \u0003ואמר רב פפא: לדידי חשדון\u0004 \u0005[אותי\u0006 עצמי \u0005חשדו]\u0006 \u0003ולא הוה\u0004 \u0005[היה]\u0006 \u0003בי!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא בקלא דפסיק\u0004 \u0005[זה בקול,\u0006 בשמועת חשד, \u0005שפוסק]\u0006 ואז יתכן שלא היה ממש בדבר, \u0003הא בקלא דלא פסיק\u0004 \u0005[זה בקול שאינו פוסק],\u0006 יש לומר שאכן יש בסיס לחשד. ושואלים: \u0003וקלא דלא פסיק\u0004 \u0005[וקול שאינו פוסק]\u0006 \u0003עד כמה\u0004 שיעורו? \u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003דומי דמתא יומא ופלגא\u0004 \u0005[הרכילות של עיר היא יום וחצי]\u0006 וזה הוא הקרוי קול שאינו פוסק.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 כש\u0003לא פסק\u0004 הקול \u0003ביני ביני\u0004 \u0005[בינתיים]\u0006 \u0003אבל\u0004 אם \u0003פסק ביני ביני\u0004 \u0005[בינתיים]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה. וכי\u0004 \u0005[וכאשר]\u0006 \u0003פסק ביני ביני\u0004 \u0005[בינתיים]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 זאת שאין בכך כלום, \u0003אלא\u0004 כאשר \u0003לא פסק\u0004 אותו קול \u0003מחמת יראה\u0004 שהחשוד הוא אדם אלים ואנשים חוששים לדבר בו סרה, \u0003אבל\u0004 כש\u0003פסק\u0004 הקול \u0003מחמת יראה — לא,\u0004 ועדיין יש לומר שזהו חשד מבוסס.","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שקול שפסק איננו נחשב, \u0003אלא\u0004 כש\u0003לא הדר נבט\u0004 \u0005[חזר\u0006 ו\u0005עלה]\u0006 אותו קול, \u0003אבל\u0004 אם \u0003הדר נבט\u0004 \u0005[חזר\u0006 ו\u0005עלה]\u0006 — \u0003לא. ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש מקום לחשד \u0003אלא דלית ליה\u0004 \u0005[\u0006כ\u0005שאין לו]\u0006 \u0003אויבים, אבל\u0004 אם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 \u0003אויבים\u0004 ידועים \u0003—\u0004 מן הסתם ה\u0003אויבים הוא דאפקוה לקלא\u0004 \u0005[הם שהוציאו את הקול].\u0006","\u0003אין כותבין שטרי חוב ב\u0004חול ה\u0003מועד. ואם אינו מאמינו\u0004 ללוה שלא יכפור בהלוואה לאחר זמן, \u0003או שאין לו\u0004 לסופר \u0003מה יאכל — הרי זה יכתוב.\u0004","\u0003אין כותבין ספרים\u0004 (ספרי תורה) \u0003תפילין ומזוזות במועד, ואין מגיהין אות אחת\u0004 בספר \u0003אפילו בספר עזרא\u0004 שהיה במקדש ועליו סמכו כל ישראל. \u0003ר' יהודה אומר: כותב אדם תפילין ומזוזות לעצמו\u0004 בחול המועד אם הוא זקוק להם,"],["\u0003וטווה על יריכו\u0004 חוטי \u0003תכלת לציציתו,\u0004 אבל אינו טווה כרגיל בפלך, שיש לעשות שינוי במועד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כותב אדם תפילין ומזוזות לעצמו, וטווה על יריכו תכלת לציציתו, ולאחרים\u0004 יכול לעשות זאת רק \u0003בטובה\u0004 אבל לא בשכר, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אם עשה לעצמו הריהו יכול להיות \u0003מערים, ומוכר את שלו, וחוזר וכותב\u0004 שוב \u0003לעצמו. ר' יוסי אומר: כותב ומוכר כדרכו כדי פרנסתו.\u0004","\u0003אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003רב לרב חננאל, ואמרי לה\u0004 \u0005[ויש אומרים\u0006 שהורה זאת\u0005]\u0006 \u0003רבה בר בר חנה לרב חננאל: הלכה, כותב ומוכר כדרכו כדי פרנסתו.\u0004","שנינו במשנה ש\u0003טווה על יריכו תכלת\u0004 לציצית. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003טווה אדם על יריכו תכלת לציציתו, אבל לא באבן\u0004 שעושים אותה כמעין פלך להקל על הטוויה. אלו \u0003דברי ר' אליעזר, וחכמים אומרים: אף באבן\u0004 טווים. \u0003ר' יהודה אומר משמו: באבן\u0004 מותר \u0003אבל לא בפלך, וחכמים אומרים: בין באבן בין בפלך.\u0004","\u0003אמר רב יהודה אמר שמואל וכן אמר ר' חייא בר אבא אמר ר' יוחנן: הלכה\u0004 היא שמותר לטוות ציצית בחול המועד \u0003בין באבן בין בפלך,\u0004 משום חיבת המצוה. \u0003ו\u0004כן \u0003הלכה: כותב\u0004 בחול המועד \u0003כדרכו ומוכר כדי פרנסתו.\u0004","\u0003הקובר את מתו שלשה ימים קודם לרגל\u0004 כיון שהתאבל כבר זמן מסויים קודם הרגל \u0003בטלה הימנו\u0004 (ממנו) \u0003גזרת\u0004 (איסורי ודיני אבילות של) \u0003שבעה\u0004 ואיננו צריך להשלים ולנהוג שבעת ימי האבל לאחר הרגל. ואם קבר את מתו \u0003שמונה\u0004 ימים קודם הרגל — \u0003בטלו הימנו גזרת שלשים,\u0004 שאיננו נוהג עוד באיסורי שלושים ימי האבילות אחר הרגל.","\u0003מפני שאמרו\u0004 חכמים כלל בענין זה: \u0003שבת עולה\u0004 נחשבת בתוך ימי האבל אף שאין מתאבלים בה, אבל \u0003אינה מפסקת\u0004 את האבל, והאבילות נמשכת אחריה. \u0003רגלים מפסיקין,\u0004 שאם החל לנהוג אבילות קודם הרגל, היא נפסקת על ידי הרגל, אבל \u0003אינן עולין,\u0004 שאם לא נהג אבילות כלל קודם הרגל (או שמת לו מת ברגל) צריך להשלים את אבלו אחר כך ואין ימי הרגל נחשבים במנין זה.","\u0003ר' אליעזר אומר: משחרב בית המקדש, עצרת\u0004 (חג השבועות) \u0003כשבת,\u0004 שאין נוהגים עוד מנהג חג בימים שלאחר החג, שבמקדש היו מקריבים הרבה קרבנות חג שלא הקריבו בשבועות גם שישה ימים אחר החג. ובזמן הזה שבטלו הקרבנות, כיון שהוא יום חג אחד בלבד דינו כשבת לענין אבילות שעולה מן המנין ואינו מפסיק.","\u0003רבן גמליאל אומר:\u0004 אפילו \u0003ראש השנה ויום הכפורים\u0004 נחשבים \u0003כרגלים\u0004 שמפסיקים את האבילות ואינם עולים. \u0003וחכמים אומרים: לא כדברי זה ולא כדברי זה, אלא העצרת\u0004 נחשבת לענין אבילות \u0003כרגלים, ראש השנה ויום הכפורים\u0004 נידונים \u0003כשבת.\u0004","על דברי המשנה שגזירות שבעה ושלושים ימים בטלו, \u0003אמר רב: גזרת — בטלו,\u0004 כלומר, האיסורים העיקריים שיש בדבר בטלו, אולם \u0003ימים\u0004 של אבילות עצמם \u0003לא בטלו\u0004 לחלוטין, והם נחשבים כתלויים ועומדים, \u0003וכן אמר רב הונא: גזרת — בטלו, ימים\u0004 — \u0003לא בטלו. ורב ששת אמר: אפילו ימים נמי\u0004 \u0005[גם כן]\u0006 \u0003בטלו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם],\u0006 כלומר, מה הכוונה ש\u0003ימים לא בטלו?\u0004 ומסבירים, \u0003שאם\u0004 היה אבל שמונה ימים קודם הרגל (וגזירת איסור הגילוח בטלה בגלל החג) ו\u0003לא גילח\u0004 משום מה ב\u0003ערב הרגל\u0004 — \u0003אסור לגלח אחר הרגל\u0004 עד תום שלושים יום, שכן ימי האבל לא בטלו לחלוטין, וכיון שלא השתמש בהיתר שהיה לו בחג — עליו לנהוג איסור שלושים יום לאחר מכן."],["\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקובר את מתו שלשה ימים קודם לרגל — בטלה הימנו\u0004 (ממנו) \u0003גזרת שבעה,\u0004 ואם קברו את המת \u0003שמונה ימים קודם לרגל — בטלה הימנו גזרת שלשים, ו\u0004על כן רשאי להיות \u0003מגלח ערב הרגל.\u0004 ו\u0003אם לא גילח ערב הרגל — אסור לגלח אחר הרגל\u0004 שלושים יום.","\u0003אבא שאול אומר: מותר לגלח אחר הרגל, שכשם שמצות שלשה\u0004 ימי אבילות שקיים קודם הרגל \u0003מבטלת גזרת שבעה,\u0004 שאם נקבר המת שלושה ימים לפני הרגל, שוב אינו צריך לשבת אחר הרגל כלום, \u0003כך מצות שבעה\u0004 שקיים ערב הרגל \u0003מבטלת גזרת שלשים.\u0004","ושואלים: מדוע הוא אומר \u0003שבעה? והאנן\u0004 \u0005[והרי אנחנו]\u0006 \u0003שמונה\u0004 ימים \u0003תנן\u0004 \u0005[שנינו]\u0006 בענין זה! ומסבירים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003אבא שאול: מקצת היום\u0004 נחשב \u0003ככולו ו\u0004משום כך ה\u0003יום\u0004 ה\u0003שביעי עולה לו לכאן ולכאן,\u0004 גם כיום אחרון של אבילות שבעה וגם כיום ראשון של אבילות השלושים. \u0003אמר רב חסדא אמר רבינא בר שילא: הלכה כאבא שאול.\u0004","\u0003ו\u0004עוד, אף \u0003מודים חכמים לאבא שאול כשחל\u0004 היום ה\u0003שמיני שלו להיות בשבת\u0004 שהיתה \u0003ערב הרגל, שמותר לגלח ב\u0004יום השביעי שהוא \u0003ערב שבת,\u0004 כיון שהוא אנוס, שאינו יכול לגלח בשבת.","ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 שמועה \u0005זו]\u0006 ש\u0003אמר רב עמרם אמר רב: אבל, כיון שעמדו מנחמין מאצלו,\u0004 כלומר ביום השביעי לאבלו, \u0003מותר\u0004 מיד \u0003ברחיצה? כמאן\u0004 \u0005[כ\u0006דעת \u0005מי] —\u0006 \u0003כ\u0004דעת \u0003אבא שאול,\u0004 הסבור שמקצת יום שביעי ככולו לענין זה.","\u0003אמר אביי: הלכה כאבא שאול ביום שבעה, ומודים חכמים לאבא שאול ביום שלשים,\u0004 שבו בודאי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מקצת היום ככולו\u0004 ומותר לגלח מיד לאחר תחילת יום השלושים.","\u0003רבא אמר: הלכה כאבא שאול ביום שלשים,\u0004 אבל \u0003אין הלכה כאבא שאול ביום שבעה. ונהרדעי אמרי\u0004 \u0005[ו\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003הלכה כאבא שאול\u0004 גם \u0003בזו ו\u0004גם \u0003בזו.\u0004 ש\u0003אמר שמואל: הלכה כדברי המיקל באבל.\u0004","לגופו של דבר שואלים: \u0003שלשים יום\u0004 אלה שנוהגים בהם אבילות \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"פרע\" \"פרע\", מנזיר; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין האבילות על בני אהרן שלא ינהגו מנהג אבילות, ולכן, \u0003\"ראשיכם אל תפרעו\"\u0004 (ויקרא י, ו), ומכאן למדנו שכל אבל אחר חייב בפריעת (כלומר, בגידול) שערו, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בנזיר: \u0003\"גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), \u0003מה להלן\u0004 \u0005[שם]\u0006 בנזיר גידול שיער הוא \u0003שלשים\u0004 יום, \u0003אף כאן\u0004 באבילות — \u0003שלשים\u0004 יום.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם\u0006 בנזיר \u0005מניין לנו]\u0006 שהם שלושים יום? שהרי לא נאמר דבר זה במפורש בנזיר! ומשיבים, \u0003אמר רב מתנה: סתם נזירות\u0004 שנדר אדם ולא פירש לכמה זמן — הרי זמנה \u0003שלשים יום, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"קדש יהיה\u0004 גדל פרע שיער ראשו\u0003\"\u0004 (במדבר ו, ה), ו\u0003\"יהיה\" בגימטריא תלתין הוו\u0004 \u0005[שלושים הם]\u0006 ומכאן שסתם נזירות היא שלושים יום, ומכאן למדים גם לאבילות.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הכל\u0004 (גם אבא שאול האומר שמקצת היום ככולו) \u0003מודים\u0004 ש\u0003כשחל\u0004 היום ה\u0003שלישי שלו להיות\u0004 ב\u0003ערב הרגל — שאסור ברחיצה עד הערב,\u0004 ואין אומרים בזה מקצת היום ככולו, אלא צריך שיהיו שלושה ימים שלמים של אבל, ולכן ימתין לערב וירחץ במים צוננים או לחול המועד וירחץ בחמים.","\u0003אמר רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אשכחתינהו\u0004 \u0005[מצאתי אותם]\u0006 את \u0003רב פפי ו\u0004את \u0003רב פפא דיתבי וקאמרי\u0004 \u0005[שישבו ואמרו]:\u0006 \u0003הלכה כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח שונה קצת, \u0003אמר רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף: אשכחתינהו\u0004 \u0005[מצאתי אותם]\u0006 את \u0003רב פפי ו\u0004את \u0003רב פפא ו\u0004את \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע דיתבי וקאמרי\u0004 \u0005[שישבו ואמרו]\u0006 הלכה זו: \u0003הכל מודים, שאם חל שלישי שלו להיות ערב הרגל — שאסור ברחיצה עד הערב.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבא\u0004 שאלה זו: מת ש\u0003קברו ברגל\u0004 עצמו, האם ה\u0003רגל עולה לו למנין שלשים\u0004 ימי אבילות, \u0003או אין\u0004 ה\u0003רגל עולה לו\u0004 ואין נחשב לו כלל \u0003למנין שלשים?\u0004 והוא מסביר את צדדי השאלה: \u0003למנין שבעה לא קמיבעיא\u0004 \u0005[מסופק]\u0006 \u0003לי,\u0004 מאחר \u0003דלא נהגה\u0004 \u0005[שאין נוהגת]\u0006 \u0003מצות שבעה ברגל\u0004 כלל, ודאי צריך להתחיל הכל אחרי הרגל, \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 הרי זה \u0003למנין שלשים,\u0004 כיון \u0003דקא נהגא\u0004 \u0005[שנוהגת]\u0006 בדברים מסויימים \u0003מצות שלשים ברגל,\u0004 כגון לענין גיהוץ ותספורת, הרי השאלה היא: \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 האם נחשיב את הימים ברגל במנין שלושים ימי האבל, או לא?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו עולה. איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003הקובר את מתו שני ימים קודם הרגל — מונה חמשה ימים\u0004 של אבל \u0003אחר הרגל ומלאכתו נעשית\u0004 אז \u0003על ידי אחרים, ועבדיו ושפחותיו עושים\u0004 את המלאכה \u0003בצנעא בתוך ביתו,\u0004 אבל \u0003אין רבים מתעסקין עמו\u0004 לבוא אליו ולנחמו,"],["\u0003שכבר נתעסקו בו ברגל,\u0004 שבאו הרבים לנחמו. \u0003כללו של דבר: כל שהוא משום\u0004 ביטוי של \u0003אבל\u0004 שצריך האבל לעשותו — \u0003רגל מפסיקו,\u0004 וצריך להשלימו אחר כך. \u0003וכל שהוא משום עסקי רבים\u0004 שצריכים לבוא ולנחם — \u0003אין רגל מפסיקו,\u0004 שאף ברגל עושים זאת.","\u0003קברו שלשה ימים ב\u0004סמוך ל\u0003סוף הרגל,\u0004 כיון שלא התחילה אבילותו — \u0003מונה שבעה\u0004 ימי אבילות \u0003אחר הרגל,\u0004 אלא ש\u0003ארבעה ימים הראשונים\u0004 של אבילותו \u0003רבים מתעסקין בו\u0004 לבוא לנחמו, ו\u0003שלשה ימים האחרונים — אין רבים מתעסקין בו, שכבר נתעסקו ברגל\u0004 שבודאי באו לנחמו ברגל, למרות שלא חלה אבילות כדינה, \u0003ורגל עולה לו\u0004 למנין שלושים.","והלכה זו שרגל עולה לו \u0003מאי לאו אסיפא\u0004 \u0005[האם לא\u0006 מדובר לגבי \u0005סופה]\u0006 של הברייתא, לענין מי שנקבר ברגל עצמו, ואם כן מפורש (שלא כדברי רבה) שרגל עולה לו למנין שלושים! ודחה רבה: \u0003לא, ארישא\u0004 \u0005[על ההתחלה]\u0006 מדובר, במי שנקבר קודם הרגל, שכיון שהחלו להתאבל עליו עולה למנין שלושים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממקור אחר, ששנינו: \u0003רגל עולה לו למנין שלשים, כיצד?\u0004 אם \u0003קברו בתחילת הרגל מונה שבעה\u0004 ימי אבל \u0003אחר הרגל, ומלאכתו נעשית\u0004 באותם ימים \u0003על ידי אחרים, ועבדיו ושפחותיו עושין בצנעא בתוך ביתו, ואין רבים מתעסקין בו,\u0004 משום \u0003שכבר נתעסקו בו ברגל, ורגל עולה לו.\u0004 הרי מפורש כאן שהרגל עולה למנין שלושים גם כשנקבר ברגל, ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דברי רבה.","\u0003כי אתא\u0004 \u0005[\u0006ו\u0005כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: אפילו קברו ברגל —\u0004 עולה לו למנין שלושים, \u0003וכן אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003ר' אלעזר לר' פדת בריה\u0004 \u0005[בנו]:\u0006 \u0003אפילו קברו ברגל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003קיים כפיית\u0004 (הפיכת) \u0003המטה שלשה ימים קודם הרגל — אינו צריך לכפותה\u0004 כלל \u0003אחר הרגל,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אומרים: אפילו\u0004 קיים \u0003יום אחד, ואפילו שעה אחת\u0004 שוב אינו צריך.","\u0003אמר ר' אלעזר בר' שמעון: הן הן דברי בית שמאי, הן הן דברי בית הלל.\u0004 כלומר, מחלוקת ר' אליעזר וחכמים כבר היתה שנויה במחלוקת בין בית שמאי ובית הלל, \u0003שבית שמאי אומרים: שלשה ימים, ובית הלל אומרים: אפילו יום אחד.\u0004","\u0003אמר רב הונא אמר ר' חייא בר אבא אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח שונה: ש\u0003אמר ר' יוחנן לר' חייא בר אבא ולרב הונא: אפילו יום אחד, אפילו שעה אחת.\u0004 ולסיכום ההלכה, \u0003רבא אמר: הלכה כתנא דידן\u0004 \u0005[כמו התנא שלנו]\u0006 בברייתא ש\u0003אמר שלשה\u0004 ולפיו נפסוק שאין חושבים התחלת אבילות בפחות משלושה ימים.","\u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003סורא\u0004 שעל נהר \u0003פרת, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבא לרבינא: הלכתא מאי\u0004 \u0005[ההלכה מה\u0006 היא\u0005]\u0006 בענין זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו יום אחד, ואפילו שעה אחת.\u0004","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' חייא בר אבא ור' אמי ור' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אקילעא\u0004 \u0005[בחצר]\u0006 של \u0003ר' יצחק בן אלעזר, נפק מילתא מבינייהו\u0004 \u0005[יצא דבר מביניהם]\u0006 ששוחחו ביניהם, ומתוך דברי כולם עלה סיכום זה: \u0003מנין לאבילות\u0004 שהיא \u0003שבעה\u0004 ימים — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והפכתי חגיכם לאבל\"\u0004 (עמוס ח, י), \u0003מה חג\u0004 זמנו \u0003שבעה\u0004 ימים — \u0003אף אבילות שבעה.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כמו חג \u0003עצרת\u0004 (שבועות), \u0003דחד יומא\u0004 \u0005[ש\u0006הוא \u0005יום אחד]\u0006 בלבד! ודוחים: הלימוד \u0003ההוא\u0004 מחג השבועות של יום אחד \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לכ\u0004 פי שאמר \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש משום\u0004 (בשם) \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]:\u0006 \u0003מנין לשמועה רחוקה\u0004 כששמע אדם שאחד מקרוביו מת זמן רב קודם לכן, \u0003שאינה נוהגת\u0004 אבילות \u0003אלא יום אחד\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והפכתי חגיכם לאבל\" ואשכחן\u0004 \u0005[ומצאנו]\u0006 ב\u0003עצרת דאיקרי חד יומא\u0004 \u0005[שנקרא\u0006 גם \u0005יום אחד]\u0006 \u0003חג.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ב\u0003שמועה קרובה\u0004 — \u0003נוהגת\u0004 אבילות \u0003שבעה ושלשים,\u0004 ב\u0003שמועה רחוקה — אינה נוהגת אלא יום אחד. איזו היא קרובה ואיזו היא רחוקה? קרובה —\u0004 ששמע \u0003בתוך שלשים\u0004 יום למוות, \u0003רחוקה — לאחר שלשים,\u0004 אלו \u0003דברי ר' עקיבא. וחכמים אומרים: אחת שמועה קרובה ואחת שמועה רחוקה — נוהגת שבעה ושלשים.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל מקום שאתה מוצא יחיד מקיל ורבים מחמירין — הלכה כרבים, חוץ מ\u0004מחלוקת \u0003זו, שאף על פי שר' עקיבא מקיל וחכמים מחמירין — הלכה כר' עקיבא.\u0004 ובהתאם לכלל ש\u0003אמר שמואל: הלכה כדברי המקיל באבל.\u0004","מסופר: \u0003רב חנינא אתיא ליה\u0004 \u0005[באה לו]\u0006 \u0003שמועה דאבוה\u0004 \u0005[של\u0006 מות \u0005אביו]\u0006 \u0003מבי חוזאי\u0004 שהיתה מקום רחוק מבבל, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב חסדא\u0004 לשאול מה יעשה; \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003שמועה רחוקה אינה נוהגת אלא יום אחד.\u0004 ומסופר עוד: \u0003רב נתן בר אמי אתא ליה\u0004 \u0005[באה לו]\u0006 \u0003שמועה דאימיה\u0004 \u0005[של\u0006 מות \u0005אמו]\u0006 \u0003מבי חוזאי, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הרי אמרו\u0004 בו, \u0003שמועה רחוקה אינה נוהגת אלא יום אחד בלבד.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב נתן לרבא, ממה ששנינו: \u0003במה דברים אמורים\u0004 ששמועה רחוקה אינה נוהגת אלא יום אחד — \u0003בחמשה מתי מצוה\u0004 האחרים (בן ובת, אח ואחות, ואשה), \u0003אבל על אביו ועל אמו\u0004 מתאבל \u0003שבעה ושלשים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 שיטה זו דעת \u0003יחידאה\u0004 \u0005[יחיד]\u0006 \u0003היא, ולא סבירא לן כוותיה\u0004 \u0005[ואין אנו סבורים כמותו].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ומת אביו של ר' צדוק ב\u0004עיר \u0003גינזק, והודיעוהו לאחר שלש שנים, ובא ושאל את אלישע בן אבויה וזקנים שעמו, ואמרו\u0004 לו: \u0003נהוג\u0004 באבילות \u0003שבעה ושלשים. וכשמת בנו של ר' אחייה בגולה\u0004 ונודע לו מכך לאחר זמן רב \u0003ישב עליו שבעה ושלשים\u0004 ימי אבילות. הרי שדעה זו היא דעת חכמים אחדים, ולא דעת הכל.","ושואלים: \u0003איני\u0004 \u0005[\u0006האם \u0005כן היא]\u0006 שזו היא דעת ר' חייא? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב\u0004 היה \u0003בר אחוה\u0004 \u0005[בן אחיו]\u0006 של \u0003ר' חייא\u0004 ש\u0003הוא\u0004 היה גם \u0003בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של \u0003ר' חייא,\u0004 שאבי רב, אייבו, היה אח למחצה לר' חייא מצד אביו, ואם רב היתה אחות למחצה של ר' חייא מצד אמו, \u0003כי סליק להתם\u0004 \u0005[כאשר עלה\u0006 רב \u0005לשם]\u0006 לארץ ישראל \u0003אמר ליה\u0004 \u0005[לו]\u0006 דודו ר' חייא: האם \u0003אבא\u0004 אייבו \u0003קיים\u0004 (חי) עדיין?"],["\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא קיימת?\u0004 כלומר, מדוע אינך שואל על אימא, שהיא אחותך, אם היא קיימת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003אימא קיימת? אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003אבא קיים?\u0004 כיון שהבין מכך שמתו שניהם, שהם אחיו ואחותו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי חייא \u0003לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003חלוץ לי מנעלי\u0004 כסימן של אבילות, \u0003ו\u0004אחר כך \u0003הולך אחרי\u0004 את \u0003כלי\u0004 (בגדי), שאני הולך \u0003לבית המרחץ.\u0004","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד מכאן\u0006 ממעשיו של רבי חייא \u0005שלושה]\u0006 דברים בהלכה; \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אבל אסור בנעילת הסנדל\u0004 ולכן חלץ את נעליו, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003שמועה רחוקה אינה נוהגת אלא יום אחד\u0004 ולא יותר, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שאין זו אבילות של יום שלם, אלא \u0003מקצת היום ככולו,\u0004 שהרי הלך מיד לבית המרחץ. על כל פנים רואים שרבי חייא נהג כך בשמועה רחוקה והרי אמרנו שרבי אחייה נהג אחרת!","ומשיבים: אין זאת קושיה, כי \u0003ר' חייא לחוד\u0004 ו\u0003ר' אחייה לחוד\u0004 והם אנשים שונים, למרות דמיון השם.","\u0003אמר ר' יוסי בר אבין: שמע שמועה קרובה ברגל\u0004 וברגל הרי אינו יכול להתאבל, \u0003ולמוצאי הרגל נעשית רחוקה\u0004 שכבר עברו שלושים יום מאז שמת — \u0003עולה\u0004 (נחשב) \u0003לו\u0004 הרגל למנין הימים כאילו היתה השמועה רחוקה, \u0003ואינו נוהג\u0004 לאחר הרגל \u0003אלא יום אחד.\u0004 כיוצא בו \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' אדא דמן קסרי\u0004 ברייתא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: שמע שמועה קרובה בשבת, ולמוצאי שבת נעשית רחוקה — אינו נוהג אלא יום אחד.\u0004","ושואלים: מי ששמע שמועה רחוקה, האם \u0003קורע\u0004 בגדו \u0003או אינו קורע? ר' מני אמר: אינו קורע, ר' חנינא אמר: קורע. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' מני לר' חנינא: בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 \u0003אינו קורע היינו\u0004 \u0005[זהו,\u0006 הטעם לכך\u0005]\u0006 משום \u0003דלא איכא\u0004 \u0005[שאין]\u0006 \u0003אבילות שבעה, אלא לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 \u0003קורע\u0004 \u0005—\u0006 \u0003קריעה בלא\u0004 שיש אחריה אבילות \u0003שבעה מי איכא\u0004 \u0005[האם ישנה]?\u0006","ותוהים: \u0003ולא\u0004 \u0005[ו\u0006האם \u0005אין]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ששנה אותה \u0003איסי אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' זירא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' זירא: מי שאין לו חלוק\u0004 משלו \u0003לקרוע, ונזדמן לו\u0004 חלוק \u0003בתוך שבעה — קורע.\u0004 נזדמן לו \u0003לאחר שבעה — אינו קורע.\u0004","\u0003עני\u0004 \u0005[ענה]\u0006 \u0003ר' זירא בתריה\u0004 \u0005[אחריו]\u0006 והשלים את ההלכה: \u0003במה דברים אמורים — בחמשה מתי מצוה\u0004 (אשתו, אחיו ואחותו, בנו ובתו) שעליהם אינו קורע אחר שבעה, \u0003אבל על אביו ועל אמו — קורע והולך\u0004 גם אחר כך. ולא כדברי רבי מני שאין קריעה בלא אבילות!","ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 שקורע, אין זו משום מצות קריעה ממש, אלא מעשה סמלי הוא \u0003לכבוד אביו ואמו.\u0004 אבל עיקר דין קריעה אינו אלא כשיש לאחריו אבילות שבעה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל האמור בפרשת כהנים\u0004 ביחס לאותם אנשים \u0003שכהן מיטמא להן,\u0004 אף \u0003אבל מתאבל עליהן ואלו הן: אשתו, אביו, ואמו, אחיו, ואחותו, בנו, ובתו. הוסיפו עליהן\u0004 חכמים קרובים אחרים לענין אבילות: \u0003אחיו ואחותו הבתולה מאמו ואחותו\u0004 ה\u0003נשואה בין מאביו בין מאמו\u0004 אף שאין מטמא להם.","ומעירים: \u0003וכשם שמתאבל עליהם — כך מתאבל על שניים שלהם\u0004 שכשם שהוא מתאבל על קרוביו, כך גם אם מתו הקרובים להם ביותר (\"שניים\"), כגון: אבי אביו, בן בנו, בן בתו ובן אחותו — מצטרף לאבלם של קרוביו, אלו \u0003דברי ר' עקיבא, ר' שמעון בן אלעזר אומר: אינו מתאבל אלא על בן בנו ועל אבי אביו.\u0004 ולא על שאר קרובי קרוביו. \u0003וחכמים אומרים: כל\u0004 קרוב \u0003שמתאבל עליו\u0004 אם מת, \u0003מתאבל\u0004 גם \u0003עמו\u0004 כאשר הוא אבל.","ושואלים: דעת \u0003חכמים היינו\u0004 \u0005[היא\u0006 עצמה\u0005]\u0006 דעת ה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 ר' עקיבא\u0005],\u0006 ומה הוסיפו בדבריהם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 ביחס לאלה שהם \u0003עמו בבית,\u0004 שלדעת חכמים צריך להתאבל רק אם קרובים אבלים אלה הם עמו בבית, ואילו לדעת ר' עקיבא צריך להתאבל גם כשאינם נמצאים עמו. \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו],\u0006 \u0003וכן אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרבה בריה\u0004 \u0005[בנו]\u0006 כאשר אירע אבל לאשתו; \u0003באפה\u0004 \u0005[בפניה] —\u0006 \u0003נהוג\u0004 במנהג \u0003אבילותא\u0004 \u0005[אבילות],\u0006 \u0003בלא אפה\u0004 \u0005[שלא בפניה]\u0006 — \u0003לא תינהוג\u0004 במנהג \u0003אבילותא\u0004 \u0005[אבילות].\u0006","מסופר: \u0003מר עוקבא שכיב ליה בר חמוה\u0004 \u0005[מת לו בן חמיו,\u0006 אחי אשתו\u0005],\u0006 \u0003סבר למיתב עליה\u0004 \u0005[חשב לשבת עליו]\u0006 \u0003שבעה ושלשים, על\u0004 \u0005[נכנס]\u0006 \u0003רב הונא לגביה\u0004 \u0005[אצלו],\u0006 \u0003אשכחיה\u0004 \u0005[מצאו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003צודנייתא בעית למיכל\u0004 \u0005[מאכלי אבלים רוצה אתה לאכול]?!\u0006 \u0003לא אמרו לכבוד אשתו\u0004 שהוא מתאבל עמה — \u0003אלא\u0004 באבלה על \u0003חמיו וחמותו\u0004 בלבד.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שמת חמיו או חמותו — אינו רשאי לכוף את אשתו\u0004 בימי האבל \u0003להיות כוחלת\u0004 את עיניה \u0003ולהיות פוקסת\u0004 באודם את לחייה, \u0003אלא\u0004 אף הוא \u0003כופה\u0004 (הופך) \u0003מטתו, ונוהג עמה אבילות. וכן היא,\u0004 כ\u0003שמת חמיה או חמותה — אינה רשאה להיות כוחלת ולהיות פוקסת, אלא כופה מטתה ונוהגת עמו אבילות.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אף על פי שאמרו אינו רשאי לכוף את אשתו\u0004 בזמן אבלה \u0003להיות כוחלת ולהיות פוקסת\u0004 ואינה רשאית לזלזל באבילותה. \u0003באמת אמרו\u0004 שבכל זאת \u0003מוזגת לו את הכוס, ומצעת לו מטה, ומרחצת לו פניו ידיו ורגליו\u0004 שהם דברי חיבה שבין איש לאשתו, שאין בהם ענין קישוט יתר וזלזול באבל. על כל פנים \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 הברייתות \u0005זו על זו],\u0006 שמן הראשונה משמע שאף הוא נוהג אבילות ובשניה נאמר רק שאינו רשאי לכפותה לזלזל באבילות שלה!","\u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד\u0006 מכאן\u0005]:\u0006 \u0003כאן — בחמיו וחמותו\u0004 צריך אף הוא לנהוג אבילות, \u0003כאן — בשאר קרובים\u0004 של אשתו שהיא חייבת באבילות עליהם, שאף שאשתו מתאבלת עליהם — הוא עצמו אינו זקוק לכך, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לא אמרו לכבוד אשתו\u0004 שהוא מתאבל עימה \u0003אלא\u0004 כשהיא אבילה על \u0003חמיו וחמותו בלבד.\u0004","מסופר: \u0003אמימר שכיב ליה בר בריה\u0004 \u0005[מת לו בן בנו],\u0006 \u0003קרע עילויה\u0004 \u0005[עליו]\u0006 קריעה. \u0003אתא בריה\u0004 \u0005[בא,\u0006 נכנס \u0005בנו] —\u0006 \u0003קרע\u0004 שוב \u0003באפיה\u0004 \u0005[בפניו]\u0006 להראות שהוא מצטרף עמו בצערו ובאבלו, \u0003אידכר\u0004 \u0005[נזכר]\u0006 שבאותה שעה שקרע לפני בנו ב\u0003מיושב קרע, קם\u0004 \u0005[עמד]\u0006 ו\u0003קרע\u0004 שוב ב\u0003מעומד.\u0004","אגב אותו ענין מספרים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: קריעה\u0004 שהיא צריכה להיות ב\u0003מעומד מנלן\u0004 \u0005[מניין לנו]?\u0006 אמר לו: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר שמע איוב שמתו בניו: \u0003\"ויקם איוב ויקרע את מעלו\"\u0004 (איוב א, כ)."],["\u0003אלא מעתה\u0004 מה שנאמר בחליצה \u0003\"ועמד ואמר לא חפצתי לקחתה\"\u0004 (דברים כה, ח), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שצריך לעמוד דווקא? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שהחליצה נעשית \u0003בין\u0004 כשהיבם \u0003יושב בין\u0004 שהוא \u0003עומד בין\u0004 שהוא \u0003מוטה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בחליצה \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויעמד ויאמר\",\u0004 משמע שאין זאת הוראה שצריך לעמוד, ולעומת זאת \u0003הכא כתיב\u0004 \u0005[כאן\u0006 בקריעה \u0005נאמר]\u0006 \u0003\"ויקם ויקרע\".\u0004","\u0003אמר רמי בר חמא: מנין לקריעה שהיא\u0004 צריכה להיעשות ב\u0003מעומד — שנאמר: \"ויקם איוב ויקרע\u0004 את מעילו\u0003\"\u0004 (איוב א, כ). ושואלים: \u0003דלמא מילתא יתירתא\u0004 \u0005[שמא דבר יתר\u0006 על החובה\u0005]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה]?\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שעשה יותר ממה שמחוייבים לעשות — מה שנאמר בו \u0003\"ויגז את ראשו\"\u0004 (איוב א, כ), וכי \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שצריך כל אדם לגזוז שערות ראשו באבלו?","\u0003אלא,\u0004 יש לדחות ראיה זו, ולומר כי הראיה היא \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר בדוד באבלו על בנו: \u0003\"ויקם המלך ויקרע את בגדיו\"\u0004 (שמואל ב' יג, לא). ושואלים גם כאן: \u0003ודלמא מילתא יתירתא עביד\u0004 \u0005[ושמא דבר יתר\u0006 על החובה \u0005עשה]?\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך] —\u0006 מה שנאמר \u0003\"וישכב ארצה\"\u0004 (שמואל ב' יג, לא), וכי \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 צריך כל אבל לעשות?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אבל ש\u0003ישב על גבי מטה, על גבי כסא, על גבי אודייני\u0004 \u0005[מכתשת]\u0006 \u0003גדולה, על גבי קרקע — מכולן לא יצא ידי חובתו. ואמר ר' יוחנן:\u0004 מפני \u0003שלא קיים\u0004 עדיין \u0003כפיית המטה\u0004 גם אם שכב על הקרקע. משמע ששכיבה על קרקע אינה חובה כלל!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה בפסוק היא \u0003כעין ארצה,\u0004 כלומר, לא ששכב על הארץ, אלא שכפה מיטתו והנמיך אותה עד הארץ. ואם כן נהג אמימר כהלכה, ואפשר ללמוד ממנהגו בקריעה, שקריעה היא מעומד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ואלו דברים שאבל אסור בהן: אסור במלאכה, וברחיצה, ובסיכה\u0004 בשמן, \u0003ובתשמיש המטה, ובנעילת הסנדל. ואסור לקרות בתורה ובנביאים ובכתובים, ולשנות במשנה, במדרש ובהלכות, ובתלמוד ובאגדות. ואם היו רבים צריכין לו\u0004 שילמדם כל אלה — \u0003אינו נמנע. ומעשה ומת בנו של ר' יוסי בציפורי ונכנס לבית המדרש, ודרש כל היום כולו.\u0004","מסופר: \u0003רבה בר בר חנה איתרעא ביה מילתא\u0004 \u0005[אירע בו דבר\u0006 של אבילות\u0005],\u0006 \u0003סבר\u0004 ש\u0003לא למיפק לפירקא\u0004 \u0005[לצאת לדרשה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא:\u0004 הלא שנינו \u0003אם היו רבים צריכין לו — אינו נמנע. סבר לאוקמי\u0004 \u0005[להעמיד]\u0006 \u0003אמורא\u0004 (מתורגמן) \u0003עליה\u0004 \u0005[לפניו]\u0006 שישמיע דבריו לציבור, כרגיל בשעת דרשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין זה: \u0003ובלבד שלא יעמיד תורגמן.\u0004","ושואלים: \u0003ואלא היכי עביד\u0004 \u0005[כיצד\u0006 הוא \u0005עושה]\u0006 כדי שישמעו דבריו? ומשיבים: \u0003כי הא דתניא\u0004 \u0005[כמו זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ומת בנו של ר' יהודה בר אילעאי, ונכנס לבית המדרש. ונכנס ר' חנניה בן עקביא וישב בצדו, ולחש הוא לר' חנניה בן עקביא, ור' חנניה בן עקביא\u0004 לחש \u0003לתורגמן, ותורגמן השמיע לרבים,\u0004 שעשו שינוי זה כדי שידעו שאבל הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שלשה ימים הראשונים — אסור להניח תפילין, מ\u0004יום ה\u0003שלישי ואילך, ושלישי בכלל\u0004 זה — \u0003מותר להניח תפילין. ואם באו\u0004 ביום השלישי \u0003פנים חדשות\u0004 (אנשים שלא היו קודם) — גם אז \u0003אינו חולץ\u0004 את התפילין, אף שיש לחשוש שמא יטעו לחשוב שהניח תפילין ביומיים הראשונים, אלו \u0003דברי ר' אליעזר. ר' יהושע אומר: אבל, שני ימים הראשונים — אסור להניח תפילין, משני ושני בכלל — מותר להניח תפילין. ואם באו פנים חדשות\u0004 לנחמו באבלו \u0003חולץ.\u0004","\u0003אמר רב מתנה: מאי טעמא\u0004 \u0005[מה טעם]\u0006 דברי \u0003ר' אליעזר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתמו ימי בכי אבל משה\"\u0004 (דברים לד, ח), משמע שעיקרו של אבל הוא שני ימים שלמים (שמיעוט רבים הוא שנים). \u0003אמר רב עינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהושע — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ושמתיה כאבל יחיד \u0003ואחריתה כיום מר\"\u0004 (עמוס ח, י), משמע — יום אחד.","ושואלים: \u0003ור' יהושע נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"ויתמו ימי\u0004 בכי אבל משה \u0003\",\u0004 משמע שני ימים! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003משה\u0004 ש\u0003תקיף\u0004 חמור \u0003אבליה\u0004 \u0005[אבלו],\u0006 והתאבלו עליו יותר מן הרגיל. שואלים: \u0003ור' אליעזר נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"ואחריתה כיום מר\"!\u0004 ומשיבים: גם הוא סבור ש\u0003עיקר מרירא\u0004 \u0005[המרירות]\u0006 \u0003חד יומא\u0004 \u0005[יום אחד]\u0006 \u0003הוא,\u0004 ואולם חומר האבילות נמשך יומיים.","\u0003אמר עולא: הלכה כר' אליעזר בחליצה,\u0004 שבימים שהאבל מותר בהם בהנחת תפילין אינו חולצם אף כשבאים מנחמים חדשים, \u0003והלכה כר' יהושע בהנחה\u0004 שמניח תפילין כבר ביום השני.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003ב\u0004יום ה\u0003שני\u0004 לאבל, \u0003ל\u0004שיטת \u0003עולא\u0004 שפסק כר' יהושע שמניח ביום השני, האם ביום זה סבור הוא כמותו גם לענין חליצת התפילין כשבאים מנחמים חדשים, \u0003ו\u0004אף לדבריו \u0003חולץ או אינו חולץ?\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר עולא\u0004 במפורש: \u0003חולץ ומניח אפילו מאה פעמים,\u0004 שכאשר באים מנחמים חדשים — הריהו חולץ, ומשהלכו — חוזר ומניח. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003יהודה בן תימא אומר: חולץ ומניח אפילו מאה פעמים.\u0004","\u0003רבא אמר: כיון שהניח — שוב אינו חולץ.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא\u0004 ש\u0003אמר\u0004 \u0005[הוא שאמר]\u0006 בעצמו: \u0003הלכה כ\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנה ש\u0003אמר\u0004 שאבילות חמורה היא \u0003שלשה\u0004 ימים, וכיצד פוסק כברייתא שיניח תפילין בימים אלה?"],["\u0003מצוה שאני\u0004 \u0005[מצוה שונה]\u0006 וכיון שמצוה להניח תפילין, אין מחמירים על האבל שלא יניח אפילו בימי הבכי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שלשה ימים הראשונים אסור במלאכה, ואפילו\u0004 היה \u0003עני המתפרנס מן הצדקה —\u0004 לא יעשה מלאכה. \u0003מכאן ואילך\u0004 אם זקוק לכך \u0003עושה בצינעא בתוך ביתו. ו\u0004כן \u0003האשה\u0004 כשהיא אבילה \u0003טווה בפלך בתוך ביתה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שלשה ימים הראשונים\u0004 לאבלו \u0003אינו הולך לבית האבל\u0004 האחר לנחמו, \u0003מכאן ואילך הולך,\u0004 אבל \u0003אינו יושב במקום המנחמין אלא במקום המתנחמין\u0004 בין האבלים שבאותו בית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שלשה ימים הראשונים אסור בשאילת שלום\u0004 כלל. \u0003משלשה ועד שבעה משיב\u0004 שלום כשפונים אליו, \u0003ואינו שואל. מכאן ואילך שואל ומשיב כדרכו.\u0004","ומקשים: וכי \u0003שלשה ימים הראשונים אסור בשאילת שלום? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה ומתו בניו של ר' עקיבא, נכנסו כל ישראל והספידום הספד גדול.\u0004","\u0003בשעת פטירתן\u0004 (כשנפרדו ממנו) \u0003עמד ר' עקיבא על ספסל גדול, ואמר: אחינו בית ישראל שמעו! אפילו\u0004 מתו עלי \u0003שני בנים חתנים — מנוחם הוא\u0004 (כלומר אני הייתי מתנחם) \u0003בשביל כבוד שעשיתם. ואם בשביל עקיבא באתם, הרי כמה עקיבא בשוק\u0004 שאין כל ישראל באים לנחמם, \u0003אלא\u0004 ודאי \u0003כך אמרתם \"תורת אלהיו בלבו\"\u0004 (תהלים לז, לא) וכיבדתם את תורתו — \u0003וכל שכן ששכרכם כפול\u0004 שנחמתם אבלים ועשיתם כבוד לתורה, \u0003לכו לבתיכם לשלום.\u0004 משמע שאומרים שלום גם ביום הראשון של האבל!","ומשיבים: \u0003כבוד רבים שאני\u0004 \u0005[שונה]\u0006 שמפני כבודם התירו לו לשאול בשלום.","שנינו בברייתא ש\u0003משלשה ועד שבעה משיב ואינו שואל, מכאן ואילך שואל ומשיב כדרכו.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר: \u0003המוצא את חבירו אבל, בתוך שלשים יום\u0004 למאורע — \u0003מדבר עמו\u0004 עוד \u0003תנחומין ואינו שואל בשלומו,\u0004 ואם מצאו \u0003לאחר שלשים יום — שואל בשלומו ואינו מדבר עמו תנחומין\u0004 עוד, שלא להזכיר לו שוב את צערו.","\u0003מתה אשתו ונשא אשה אחרת — אינו רשאי ליכנס לביתו לדבר עמו תנחומין,\u0004 כדי שלא לפגוע באשה החדשה. אולם אם \u0003מצאו בשוק\u0004 לבדו — \u0003אומר לו\u0004 שלום \u0003בשפה רפה ובכובד ראש.\u0004 הרי שיש איסור בשאילת שלום כל שלושים יום ולא שבעה בלבד!","\u0003אמר רב אידי בר אבין,\u0004 כך יש להבין: בברייתא הראשונה מדובר באבל, ש\u0003הוא שואל\u0004 לאחר שבעה \u0003בשלום אחרים — שאחרים שרויין בשלום,\u0004 ובברייתא השניה שאינו שואל כל שלושים מדובר באחרים, ש\u0003אחרים אין שואלין בשלומו,\u0004 כיון \u0003שהוא\u0004 האבל \u0003אינו שרוי בשלום.\u0004","ומקשים: \u0003והא מדקתני\u0004 \u0005[והרי מ\u0006מה \u0005ששנינו]\u0006 שהאבל אחר שלושה ימים \u0003משיב\u0004 שלום, \u0003מכלל\u0004 הדבר אתה למד \u0003דשיילינן ליה\u0004 \u0005[ששואלים לו\u0006 בשלום\u0005]?\u0006 ומשיבים: מדובר בכאלה \u0003דלא ידעי\u0004 \u0005[שאין יודעים]\u0006 שאבל הוא ולכן שאלו בשלומו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 ששאלו בשלומו בלא לדעת, \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בשלושה ימים הראשונים יתכן שישאלו אותו ויהיה מותר לו להשיב! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בתוך שלושה \u0003מודע להו ולא מהדר להו\u0004 \u0005[מודיע להם\u0006 שהוא אבל \u0005ואינו מחזיר להם\u0006 שלום\u0005],\u0006 \u0003הכא לא צריך לאודועינהו\u0004 \u0005[כאן\u0006 לאחר שלושה \u0005אינו צריך להודיעם]\u0006 אלא משיב שלום.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המוצא את חבירו אבל בתוך שנים עשר חדש — מדבר עמו תנחומין, ואינו שואל בשלומו. לאחר שנים עשר חדש — שואל בשלומו, ואינו מדבר עמו\u0004 עוד \u0003תנחומין, אבל מדבר עמו מן הצד,\u0004 שבדרך אגב יכול לומר \"תתנחם\" בלי לפרט שם המת.","ובענין זה \u0003אמר ר' מאיר: המוצא את חבירו אבל לאחר שנים עשר חדש ומדבר עמו תנחומין למה הוא דומה — לאדם שנשברה רגלו וחיתה\u0004 (והבריאה), \u0003מצאו רופא ואמר לו: כלך\u0004 (בוא) \u0003אצלי שאני שוברה\u0004 שנית \u0003וארפאנה, כדי שתדע שסממנין\u0004 (תרופות) \u0003שלי יפין\u0004 ומועילים לרפואה, כך המנחם את חבירו לאחר שכבר התנחם עם הזמן. ומכאן רואים שעד שנים עשר חודש עדיין אין שואלים בשלומו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין שואלים בשלומו כל שנים עשר חודש, הרי זה \u0003ב\u0004אבל על \u0003אביו ואמו, הא\u0004 \u0005[זה]\u0006 ששנינו ששואלים לאחר שבעה, הרי זה \u0003ב\u0004אבל על \u0003שאר קרובים.\u0004","ושואלים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בשאר קרובים לאחר שלושים \u0003ידבר עמו תנחומין מן הצד\u0004 ומדוע אמרה הברייתא שלאחר שלושים אינו מדבר עמו תנחומים כלל? ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן].\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003אינו מדבר עמו תנחומין —\u0004 יש להבין: אינו מדבר עמו \u0003כדרכו, אבל מדבר עמו מן הצד.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שלשה ימים הראשנים\u0004 אם \u0003בא ממקום קרוב — מונה עמהן\u0004 עם שאר האבלים את ימי האבילות מיום הקבורה ומסיים עימם, אף על פי שבסופו של דבר אינו יושב אלא חמישה או שישה ימים. \u0003בא ממקום רחוק — מונה לעצמו\u0004 שבעה שלימים מיום השמועה. \u0003מכאן ואילך\u0004 אחר שלושה ימים \u0003אפילו בא ממקום קרוב מונה\u0004 שבעה \u0003לעצמו. ר' שמעון אומר: אפילו בא ביום השביעי ממקום קרוב — מונה\u0004 ומסיים \u0003עמהן.\u0004","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שלשה ימים הראשונים,\u0004 אם \u0003בא ממקום קרוב — מונה עמהן. אמר ר' חייא בר אבא אמר ר' יוחנן: והוא שיש גדול הבית בבית\u0004 ולכן כל שאר הקרובים נגררים אחריו, אולם אם זה שבבית הוא הצעיר והבא ממקום רחוק הוא גדול הבית — ודאי שאינו נגרר אחרי הצעיר ומונה שבעה לעצמו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו:"],["\u0003הלך גדול הבית לבית הקברות\u0004 לכבוד המת ושהה שם שלושה ימים ולא חזר לביתו \u0003מהו?\u0004 האם כיון שלכבוד המת הלך הריהו נחשב כאילו הוא בביתו וכל הבא בתוך אותו זמן נגרר אחריו או לא?","ומשיבים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אפילו הלך גדול הבית לבית הקברות —\u0004 האבל שבא \u0003מונה עמהן.\u0004 ותוהים: \u0003מונה\u0004 ומסיים \u0003עמהן? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003מונה\u0004 שבעה \u0003לעצמו!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמונה עמהם הרי זה באופן \u0003דאתא בגו תלתא\u0004 \u0005[שבא\u0006 גדול הבית \u0005בתוך שלושה\u0006 ימים\u0005],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 שמונה לעצמו \u0003דלא אתא בגו תלתא\u0004 \u0005[שלא בא בתוך שלושה\u0006 ימים\u0005].\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב לבני הצלפוני\u0004 כשהיו באבל: \u0003דאתו בגו תלתא\u0004 \u0005[\u0006אלה \u0005שבאים בתוך שלושה\u0006 ימים\u0005] —\u0006 \u0003לימנו בהדייכו\u0004 \u0005[שיימנו אתכם],\u0006 \u0003דלא אתו בגו תלתא\u0004 \u0005[שאינם באים בתוך שלושה] —\u0006 \u0003לימנו לנפשיהו\u0004 \u0005[שיימנו לעצמם].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לבני מחוזא: אתון דלא אזליתו בתר ערסא\u0004 \u0005[אתם שאינכם הולכים אחר המיטה\u0006 של המת לקוברו\u0005]\u0006 (שהיו מוליכים את מתיהם להיקבר במקום רחוק, ולא הלכו רוב האבלים אחר המיטה עד לקבר), \u0003מכי מהדריתו אפייכו מבבא דאבולא אתחילו מנו\u0004 \u0005[מזמן שאתם מחזירים את פניכם משער העיר\u0006 לחזור הביתה \u0005התחילו למנות]\u0006 ימי אבילות.","שנינו במשנה, ש\u0003ר' שמעון אומר: אפילו בא\u0004 אחד האבלים \u0003ביום השביעי ממקום קרוב — מונה עמהן. אמר ר' חייא בר גמדא אמר ר' יוסי בן שאול אמר רבי: והוא שבא ומצא\u0004 עדיין \u0003מנחמין אצלו\u0004 בבית.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב ענן:\u0004 אם \u0003ננערו\u0004 המנחמים \u0003לעמוד\u0004 וללכת \u0003ו\u0004עדיין \u0003לא עמדו, מהו?\u0004 היש לראות זאת כאילו הלכו כבר המנחמים או לא? לשאלה זו לא נמצאה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","מספרים: \u0003גמירי חבריה\u0004 \u0005[למד חבירו]\u0006 של \u0003ר' אבא בר חייא מר' אבא\u0004 ושואלים: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 חבר זה — \u0003ר' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח אחר: \u0003חבריה\u0004 \u0005[חבירו]\u0006 של \u0003ר' זירא\u0004 שלמד \u0003מר' זירא ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005] —\u0006 \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יוחנן: הלכה כר' שמעון בן גמליאל בטריפות, והלכה כר' שמעון באבל.\u0004","ומסבירים: \u0003כר' שמעון באבל — הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 לענין מי שבא ביום השביעי. \u0003כרבן שמעון בן גמליאל בטריפות — דתנן\u0004 \u0005[\u0006זה \u0005ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בני מעים שניקבו\u0004 (שנעשה בהם נקב) \u0003וליחה סותמתן\u0004 כך שאין דבר יוצא דרך הנקב החוצה — הרי זו \u0003כשרה,\u0004 ואין דינו כנקב במעיים שמטריף את הבהמה, אלו \u0003דברי רבן שמעון בן גמליאל.\u0004","לעצם ההלכה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003ליחה? אמר רב כהנא: שירקא דמעיא דנפיק\u0004 \u0005[שומן המעיים שיוצא]\u0006 מהם \u0003אגב דוחקא\u0004 \u0005[דחיקתם\u0006 ולחיצתם\u0005].\u0006 \u0003אמר מאן דהוא\u0004 \u0005[מי שהוא]\u0006 שלא נתפרש שמו: \u0003איזכי ואסיק ואגמרא לשמעתא מפומיה דמריה\u0004 \u0005[אזכה ואעלה\u0006 לארץ ישראל \u0005ואלמד את השמועה מפי בעליה],\u0006","\u0003כי סליק אשכחיה\u0004 \u0005[כאשר עלה מצא אותו]\u0006 את \u0003ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא. אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003אמר מר\u0004 \u0005[אדוני]\u0006 כי \u0003הלכה כרבן שמעון בן גמליאל בטריפות? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003אין הלכה\u0004 כרבן שמעון בן גמליאל \u0003אמרי\u0004 \u0005[אמרתי],\u0006 להיפך ממה שאמרו בשמי, ולדעתי נקב כעין זה מטריף את הבהמה.","שאל אותו שוב: ומה שנמסר בשמך שהלכה \u0003כר' שמעון באבל, מאי\u0004 \u0005[מה\u0006 אכן כך הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלוגתא נינהו\u0004 \u0005[מחלוקות הן]\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 \u0003רב חסדא אמר: הלכה\u0004 כר' שמעון, \u0003וכן אמר ר' יוחנן: הלכה. רב נחמן אמר: אין הלכה.\u0004","ומסכמים: \u0003ואין הלכה כרבן שמעון בן גמליאל בטריפות\u0004 בענין זה, \u0003והלכה כר' שמעון באבל.\u0004 ולפי הכלל ש\u0003אמר שמואל: הלכה כדברי המיקל באבל.\u0004","\u0003על כל המתים כולן\u0004 אם \u0003מדחה מטתו\u0004 (שממהר להוציא ולקבור את המת מיד) — \u0003הרי זה משובח, על אביו ועל אמו — הרי זה מגונה,\u0004 שראוי שיאריך האבל באנינותו, אבל אם \u0003היה ערב שבת או ערב יום טוב,\u0004 אם ממהר לקבור \u0003הרי זה משובח,\u0004 לפי \u0003שאינו עושה אלא לכבוד אביו ואמו,\u0004 שלא ישהו במשך השבת בלא קבורה.","\u0003על כל המתים כולן,\u0004 אם \u0003רצה\u0004 האבל — \u0003ממעט בעסקו\u0004 משום האבל, \u0003רצה — אינו\u0004"],["\u0003ממעט, על אביו ועל אמו — ממעט\u0004 תמיד.","\u0003על כל המתים כולן, רצה — חולץ\u0004 את הבגד מעל כתפו האחת, \u0003רצה — אינו חולץ. על אביו ועל אמו — חולץ\u0004 תמיד.","מספרים: \u0003ומעשה בגדול הדור אחד שמת אביו וביקש לחלוץ, וביקש גדול הדור אחר שעמו לחלוץ\u0004 גם הוא, להשתתף עמו באבלו, \u0003ונמנע\u0004 הראשון \u0003ולא חלץ\u0004 כדי שלא לגרום לחבירו שיחלוץ.","\u0003אמר אביי: גדול הדור\u0004 שאמרנו היה \u0003רבי, גדול הדור שעמו — ר' יעקב בר אחא. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003גדול הדור — ר' יעקב בר אחא, גדול הדור שעמו — רבי.\u0004","ודנים בדבר; \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003גדול הדור שעמו — רבי, היינו\u0004 \u0005[זהו\u0006 הטעם\u0005]\u0006 ש\u0003נמנע ולא חלץ,\u0004 לפי שלא רצה לגרום לנשיא הדור רבי שיחלוץ,","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003ר' יעקב בר אחא\u0004 היה גדול הדור שעמו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003נמנע\u0004 רבי \u0003ולא חלץ?\u0004 הלא \u0003רבן שמעון בן גמליאל\u0004 אביו של רבי \u0003נשיא הוה\u0004 \u0005[היה]\u0006 \u0003וכולי עלמא מיחייבי למיחלץ\u0004 \u0005[והכל חייבים לחלוץ\u0006 עליו\u0005]\u0006 שכך עושים במות הנשיא, ואם כן היה גם ר' יעקב בר אחא צריך לחלוץ מן הדין, ומדוע מנעו רבי? ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לדעה זו.","ועוד בהלכות אבל: \u0003על כל המתים כולן — מסתפר לאחר שלשים יום,\u0004 והאבל \u0003על אביו ועל אמו\u0004 אינו מסתפר \u0003עד שיגערו בו חבריו\u0004 על שהוא מגדל שיער יותר מדי. \u0003על כל המתים כולן — נכנס לבית השמחה\u0004 (מקום שיש בו שמחה וחגיגה) \u0003לאחר שלשים יום, על אביו ועל אמו — לאחר שנים עשר חדש.\u0004","\u0003אמר רבה בר בר חנה:\u0004 זה שאמרנו כי על כל שאר המתים הריהו נכנס לבית השמחה לאחר שלושים ימי האבל — הרי זה דווקא \u0003ולשמחת מריעות,\u0004 כלומר סעודת שמחה שעושים ריעים זה לזה שאוכלים לפי התור זה בביתו של זה, ואין מדובר בשמחה גדולה (כגון נישואין). \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: הלא שנינו \u0003ולשמחה ולמריעות שלשים יום.\u0004 ומשמע שסתם שמחה אינה שמחת מריעות, ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003אמימר מתני הכי\u0004 \u0005[היה שונה\u0006 את השמועה \u0005כך],\u0006 \u0003אמר רבה בר בר חנה: ולשמחת מריעות — מותר ליכנס לאלתר\u0004 \u0005[מיד].\u0006 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003לשמחה שלשים, ולמריעות שלשים!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 בברייתא — כגון \u0003באריסותא\u0004 \u0005[בהתחלה]\u0006 כלומר, כאשר נקבע בין הידידים שהוא הראשון שצריך לעשות משתה לכולם — אז ימתין שלושים יום, \u0003הא\u0004 \u0005[זה]\u0006 דברי רבה בר בר חנה — \u0003בפורענותא\u0004 \u0005[בפרעון]\u0006 כאשר חביריו כבר עשו סעודות, והגיע תורו, שכיוון שחובה עליו לעשות זאת לחביריו אינו יכול לדחות.","ועוד אמרו: \u0003על כל המתים כולן קורע טפח,\u0004 ואילו \u0003על אביו ועל אמו\u0004 קורע \u0003עד שיגלה את לבו. אמר ר' אבהו: מאי קרא\u0004 \u0005[מה הכתוב]\u0006 המלמד שקריעה היא טפח לפחות, שנאמר: \u0003\"ויחזק דוד בבגדו ויקרעם\"\u0004 (שמואל ב' א, יא), \u0003ואין אחיזה פחות מטפח.\u0004","\u0003על כל המתים כולן אפילו\u0004 היה \u0003לבוש עשרה חלוקין — אינו קורע אלא\u0004 בגד \u0003עליון, על אביו ועל אמו קורע את כולן. ו\u0004אולם \u0003אפיקרסותו\u0004 (בגד תחתון שעל גופו) \u0003אינה מעכבת,\u0004 שאותה אינו צריך לקרוע.","\u0003אחד האיש ואחד אשה\u0004 בקריעה. \u0003ר' שמעון בן אלעזר אומר: האשה קורעת את\u0004 הבגד \u0003התחתון ומחזירתו לאחוריה, וחוזרת וקורעת את העליון\u0004 כדי שלא יתגלה בשרה.","\u0003על כל המתים כולן,\u0004 אם \u0003רצה — מבדיל\u0004 וקורע \u0003קמי שפה שלו\u0004 \u0005[לפני שפת\u0006 הבגד\u0005]\u0006 ולא בצואר, כדי שייראה הקרע נבדל מפתח הבגד, ואם לא \u0003רצה — אינו מבדיל\u0004 אלא קורע את בית הצוואר עצמו, אף על פי שהקריעה במקום כזה אינה ניכרת כל כך. \u0003על אביו ועל אמו — מבדיל\u0004 תמיד.","\u0003ר' יהודה אומר: כל קריעה שאינו מבדיל קמי שפה שלו — אינו אלא קרע של תיפלות\u0004 (של שטות) שקריעה צריכה שתיראה שנעשתה לאבל, ולא כפגם בלבד בבגד. \u0003אמר ר' אבהו: מאי טעמא\u0004 \u0005[מה טעם]\u0006 דברי \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחזק בבגדיו ויקרעם לשנים קרעים\"\u0004 (מלכים ב' ב, יב), \u0003ממשמע שנאמר \"ויקרעם\" איני יודע שהן לשנים? אלא\u0004 ודאי הכוונה היא \u0003שנראין קרועים כשנים,\u0004 משמע שצריך הקרע להיות גלוי ונראה.","\u0003על כל המתים כולן שולל\u0004 (תופר את הקרע תפירה גסה) \u0003לאחר שבעה, ומאחה\u0004 בתפירה מדוייקת \u0003לאחר שלשים. על אביו ועל אמו — שולל לאחר שלשים, ואינו מאחה לעולם. והאשה שוללתו\u0004 את הקרע \u0003לאלתר\u0004 \u0005[מיד]\u0006 \u0003מפני כבודה,\u0004 שאין זה כבודה שייראו בגדיה קרועים.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: על כל המתים, רצה — קורע ביד, רצה — קורע בכלי. על אביו ועל אמו —\u0004 קורע \u0003ביד\u0004 בדרך השחתה וקלקול.","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: על כל המתים כולן\u0004 יכול לקרוע קרע \u0003מבפנים\u0004 ולא בבגדו העליון, ואילו \u0003על אביו ועל אמו\u0004 — \u0003קורע מבחוץ. אמר רב חסדא: וכן לנשיא\u0004 קורע כמו שקורע על אביו.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005],\u0006 ממה ששנינו: \u0003לא הושוו\u0004 דיני קריעה על נשיא ואב בית דין ורבו \u0003לאביו ולאמו אלא ל\u0004ענין \u0003איחוי בלבד,\u0004 שאסור לאחות את הבגד הקרוע בתפירה מדוייקת.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003אפילו\u0004 הקורע \u0003לנשיא?\u0004 ודוחים: \u0003לא, לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004הקורע ל\u0003נשיא,\u0004 שקרע על נשיא דינו לכל דבר כקרע על אביו.","מסופר: \u0003נשיאה שכיב\u0004 \u0005[הנשיא מת],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב חנן בר רבא: כפי אסיתא\u0004 \u0005[הפוך מדוכה]\u0006 שיהיה לך מקום מוגבה \u0003וקום עלה\u0004 \u0005[ועמוד עליה],\u0006 \u0003ואחוי\u0004 \u0005[והראה]\u0006 \u0003קריעה לעלמא\u0004 \u0005[לכל]\u0006 שיראו כיצד קורעים, וכן יעשו כולם, שהרי כל העם קורעים על הנשיא.","ועוד בהלכות קריעה: \u0003על חכם חולץ\u0004 את הבגד מכתפו \u0003מימין, על אב בית דין\u0004 חולץ ומגלה הכתף \u0003משמאל, על נשיא\u0004 חולץ \u0003מכאן ומכאן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חכם שמת — בית מדרשו בטל\u0004 ואין לומדים בו מפני אבילות, \u0003אב בית דין שמת — כל בתי מדרשות שבעירו בטילין, ונכנסין לבית הכנסת, ו\u0004שם \u0003משנין את מקומן\u0004 כמנהג אבלים, \u0003היושבין\u0004 כרגיל \u0003בצפון — יושבין בדרום, היושבין בדרום — יושבין בצפון. נשיא שמת — בתי מדרשות כולן בטילין, ובני הכנסת נכנסין לבית הכנסת\u0004"],["\u0003וקורין\u0004 (וקוראים) בתורה בשבת \u0003שבעה\u0004 קרואים, שדבר זה אפשר לעשות רק בציבור, \u0003ויוצאין\u0004 ומתפללים ביחידות. \u0003ר' יהושע בן קרחה אומר: לא שילכו\u0004 אחר כך \u0003ויטיילו בשוק, אלא יושבין ודומין\u0004 (דוממים, שותקים) באבלם.","ועוד אמרו: \u0003ואין אומרים שמועה\u0004 (הלכה) \u0003ואגדה בבית האבל\u0004 מפני שהן מביאות לשמחה. \u0003אמרו עליו על ר' חנניה בן גמליאל שהיה אומר שמועה ואגדה בבית האבל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אבל, שבת\u0004 (שבוע) \u0003ראשונה\u0004 של אבלו \u0003אינו יוצא מפתח ביתו, שניה — יוצא ואינו יושב\u0004 בבית הכנסת \u0003במקומו, שלישית — יושב במקומו ואינו מדבר, רביעית\u0004 — \u0003הרי הוא ככל אדם.\u0004","\u0003ר' יהודה אומר: לא הוצרכו לומר שבת ראשונה לא יצא מפתח ביתו,\u0004 שאין כאן חידוש \u0003שהרי הכל נכנסין לביתו לנחמו. אלא, שניה\u0004 — \u0003אינו יוצא מפתח ביתו, שלישית\u0004 — \u0003יוצא ואינו יושב במקומו, רביעית\u0004 — \u0003יושב במקומו ואינו מדבר, חמישית\u0004 — \u0003הרי הוא ככל אדם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל שלשים יום\u0004 שלאחר כל אבל אסורים \u0003לנישואין.\u0004 ואם \u0003מתה אשתו — אסור לישא אשה אחרת עד שיעברו עליו שלשה רגלים\u0004 מאז מותה. \u0003ר' יהודה אומר: רגל ראשון ושני — אסור, שלישי — מותר.\u0004","\u0003ואם אין לו בנים — מותר לישא\u0004 אשה אחרת \u0003לאלתר\u0004 (מיד) \u0003משום ביטול פריה ורביה,\u0004 שהרי מצוה עליו לשאת אשה. וכן אם \u0003הניחה לו\u0004 אשתו \u0003בנים קטנים — מותר לישא לאלתר מפני פרנסתן\u0004 של הילדים, שיהיה מי שידאג להם.","ומספרים: \u0003מעשה שמתה אשתו של יוסף הכהן, ואמר לאחותה בבית הקברות: לכי ופרנסי את בני אחותך,\u0004 כלומר, רמז לה באותו יום שרוצה לשאת אותה מיד. ומוסיפים: \u0003ואף על פי כן\u0004 שנשאה מיד \u0003לא בא עליה אלא לזמן מרובה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לזמן מרובה\u0004 בענין זה? \u0003אמר רב פפא:\u0004 רק \u0003לאחר שלשים יום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל שלשים יום\u0004 של אבל אסורים \u0003לגיהוץ, אחד כלים\u0004 (בגדים) \u0003חדשים ואחד כלים ישנים\u0004 ה\u0003יוצאין מתוך המכבש\u0004 אסור ללבשם, שכיון שגוהצו ויושרו היטב הריהם כחדשים. ואילו \u0003רבי אומר: לא אסרו אלא כלים חדשים בלבד. ר' אלעזר בר' שמעון אומר: לא אסרו אלא כלים חדשים לבנים בלבד.\u0004","ומספרים: \u0003אביי נפיק\u0004 \u0005[יצא]\u0006 בזמן אבלו \u0003בגרדא דסרבלא\u0004 \u0005[בבגד לבן ישן]\u0006 ונהג \u0003כ\u0004דעת \u0003רבי.\u0004 ואילו \u0003רבא נפיק\u0004 \u0005[יצא]\u0006 \u0003בחימוצתא רומיתא סומקתא חדתי\u0004 \u0005[בחלוק רומי אדום חדש]\u0006 שנהג \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון.\u0004","שנינו במשנה: \u0003מפני שאמרו שבת עולה\u0004 לענין ימי אבילות \u0003ואינה מפסקת.\u0004 ואומרים, שבענין אבילות בשבת נחלקו המנהגים בין \u0003בני יהודה ובני גלילא\u0004 \u0005[הגליל].\u0006 \u0003הני אמרי\u0004 \u0005[אלו אומרים]:\u0006"],["\u0003יש אבילות\u0004 כלשהי \u0003בשבת\u0004 ועל כל פנים בדברים שבצינעה כשאין אחרים רואים, \u0003והני אמרי\u0004 \u0005[ואלו אומרים]:\u0006 \u0003אין אבילות בשבת\u0004 כלל.","ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003יש אבילות בשבת\u0004 סמך על מה \u0003דקתני\u0004 \u0005[ששנינו]\u0006 שהשבת \u0003עולה\u0004 ונחשבת למנין ימי האבל, ומכאן שבשבת יש קצת אבילות. \u0003מאן דאמר\u0004 \u0005[\u0006ו\u0005מי שאומר]\u0006 \u0003אין אבילות בשבת — דקתני\u0004 \u0005[ששנינו]\u0006 שהשבת \u0003אינה מפסקת.\u0004","וכך הם מדייקים: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003יש אבילות\u0004 כלשהי \u0003בשבת, השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003אבילות נהגא\u0004 \u0005[נוהגת]\u0006 ביום זה, \u0003אפסוקי מיבעיא\u0004 \u0005[\u0006שאינה \u0005מפסקת צריך\u0006 לומר\u0005]?\u0006 אלא ודאי אין בה אבילות כל עיקר.","ושואלים: \u0003ואלא הא קתני\u0004 \u0005[הרי שנינו]\u0006 \u0003עולה,\u0004 הרי שהיא ממש כשאר ימי האבל ונוהגת בה אבילות! ומשיבים: \u0003איידי דקבעי למיתנא סיפא\u0004 \u0005[מתוך שרצה לשנות בסוף\u0006 המשנה\u0005]\u0006 על הימים טובים ש\u0003אינן עולים, תנא רישא\u0004 \u0005[שנה בראשה]\u0006 \u0003עולה,\u0004 אף שאין בה כל אבילות.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ש\u0003יש אבילות בשבת, הא קתני\u0004 \u0005[הרי שנינו]\u0006 \u0003אינה מפסקת!\u0004 ומשיבים לשיטתם: דבר זה לא נצרך לגופו, אלא \u0003משום דקבעי למיתנא סיפא\u0004 \u0005[שרצה לשנות בסוף]\u0006 שימים טובים \u0003מפסיקין, תנא רישא\u0004 \u0005[שנה בראש]\u0006 \u0003אינה מפסקת\u0004 אף שאינו נחוץ.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005לומר\u0006 שמחלוקת זו \u0005כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו: \u0003מי שמתו מוטל לפניו\u0004 שעדיין לא נקבר — \u0003אוכל בבית אחר, אין לו בית אחר — אוכל בבית חברו, אין לו בית חברו\u0004 שיאכל בו — \u0003עושה לו מחיצה עשרה טפחים\u0004 בינו לבין המת ואוכל. \u0003אין לו דבר לעשות\u0004 בו \u0003מחיצה — מחזיר\u0004 (מפנה) \u0003פניו\u0004 מן המת \u0003ואוכל.\u0004","\u0003ו\u0004בכל מקרה \u0003אינו מיסב ואוכל\u0004 כבסעודה חגיגית, \u0003ואינו אוכל בשר, ואינו שותה יין, ואין מברך\u0004 להוציא אחרים ידי חובתם, \u0003ואין מזמן, ואין מברכין עליו\u0004 (עבורו, להוציאו ידי חובה), \u0003ואין מזמנין עליו\u0004 שאין מצרפים אותו למנין המזמנים, \u0003ופטור מקריאת שמע, ומן התפלה, ומן התפילין, ומכל מצות האמורות בתורה.\u0004","\u0003ו\u0004אם היה זה \u0003בשבת — מיסב ואוכל, ואוכל בשר, ושותה יין, ומברך, ומזמן, ומברכין ומזמנין עליו, וחייב בקריאת שמע ובתפילה ובתפילין ובכל מצות האמורות בתורה. רבן גמליאל אומר: מתוך שנתחייב\u0004 בשבת \u0003באלו — נתחייב בכולן. \u0004","ולהסברת ביטוי לא ברור זה של רבן גמליאל \u0003אמר ר' יוחנן:\u0004 לגבי \u0003תשמיש המטה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שלדעת רבן גמליאל כיון שבשבת נתחייב בכל המצוות — חייב גם במצות עונה עם אשתו בשבת.","ומציעים, \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם\u0006 \u0005חלוקים]:\u0006 \u0003דמר\u0004 \u0005[שחכם\u0006 זה, התנא הראשון\u0005]\u0006 \u0003סבר: יש אבילות בשבת\u0004 בדברים שבצינעה ולכן אינו משמש מיטתו, \u0003ומר\u0004 \u0005[וחכם\u0006 זה, רבן גמליאל\u0005]\u0006 \u0003סבר: אין אבילות בשבת\u0004 כלל!","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מגיע אתה למסקנה זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שאסור בתשמיש המיטה \u0003אלא משום שמתו מוטל לפניו\u0004 ועדיין לא נקבר, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 באבל ש\u0003אין מתו מוטל לפניו — לא.\u0004","ולהיפך, \u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן גמליאל התם\u0004 \u0005[שם]\u0006 להתיר בתשמיש המיטה רק משום \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא חל\u0004 \u0005[חלה]\u0006 \u0003אבילות עליה\u0004 \u0005[עליו]\u0006 שאין דין אבילות מתחיל אלא מקבורת המת, \u0003אבל הכא, דחל\u0004 \u0005[כאן שחלה]\u0006 \u0003אבילות עליה\u0004 \u0005[עליו]\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ינהג איסור גם בתשמיש המיטה."],["\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן משמואל: יש אבילות בשבת או אין אבילות בשבת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין אבילות בשבת.\u0004","\u0003יתבי רבנן קמיה\u0004 \u0005[ישבו חכמים לפני]\u0006 \u0003רב פפא וקאמרי משמיה\u0004 \u0005[ואמרו משמו]\u0006 של \u0003שמואל: אבל ששימש מטתו בימי אבלו — חייב מיתה\u0004 בידי שמים. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: אסור אתמר\u0004 \u0005[נאמר]\u0006 אבל לא חייב מיתה, \u0003ומשמיה\u0004 \u0005[ומשמו]\u0006 של \u0003ר' יוחנן אתמר\u0004 \u0005[נאמר]\u0006 ולא בשם שמואל,","\u0003ואי שמיעא לכו משמיה\u0004 \u0005[ואם שמעתם\u0006 דבר \u0005משמו]\u0006 של \u0003שמואל\u0004 בענין זה, \u0003הכי שמיע לכו\u0004 \u0005[כך\u0006 היה הדבר \u0005ששמעתם],\u0006 \u0003אמר רב תחליפא בר אבימי אמר שמואל: אבל שלא פרע\u0004 ראשו, \u0003ושלא פירם\u0004 בגדיו — \u0003חייב מיתה, שנאמר\u0004 לבני אהרון באבלם: \u0003\"ראשיכם אל תפרעו ובגדיכם לא תפרמו ולא תמתו\"\u0004 (ויקרא י, ו), שהם נצטוו שלא להתאבל, בגלל חנוכת המשכן, ונדייק כאן \u0003הא\u0004 \u0005[הרי]\u0006 כל אבל \u0003אחר שלא פרע ושלא פירם — חייב מיתה.\u0004","\u0003אמר רפרם בר פפא: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003ב\u0004מסכת המיוחדת לדיני אבלות \u0003אבל רבתי\u0004 (מסכת שמחות): \u0003אבל אסור לשמש מטתו בימי אבלו, ומעשה באחד ששימש מטתו בימי אבלו ו\u0004נענש, שאחר מותו \u0003שמטו חזירים את גוייתו\u0004 (גופו).","\u0003אמר שמואל\u0004 בענין מנהגי האבל ביום השבת, ונתן סימן לדבר: \u0003פח\"ז — חובה, נת\"ר — רשות.\u0004","ופירושו: \u0003פריעת הראש\u0004 שלא יכסה את ראשו כאבל, \u0003חזרת קרע\u0004 שמחזיר קרע שבבגדיו \u0003לאחוריו\u0004 שלא ייראה, \u0003וזקיפת המטה\u0004 שלא תהיה כפויה (הפוכה) בשבת — \u0003חובה\u0004 היא. ואילו \u0003נעילת הסנדל, תשמיש המטה,\u0004 ו\u0003רחיצת ידים ורגלים בחמין ערבית\u0004 (בשעת ערב) — \u0003רשות\u0004 הם, ואם רוצה האבל שלא לעשותם בשבת — רשאי. \u0003ורב אמר: אף פריעת הראש רשות.\u0004","ושואלים: \u0003ושמואל מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נעילת הסנדל\u0004 שהיא \u0003רשות —\u0004 טעמו: \u0003דלאו כולי עלמא עבידי דסיימי מסאנייהו\u0004 \u0005[שלא הכל עשויים שהם נועלים מנעליהם]\u0006 תמיד, ולכן, אם אינו נועל נעליו בשבת אין הדבר נראה לכל כסימן של אבילות. אולם \u0003פריעת הראש נמי\u0004 \u0005[גם כן],\u0006 הלא \u0003לאו כולי עלמא עבידי דמגלו רישייהו\u0004 \u0005[פריעת הראש גם כן, לא הכל עשויים שמגלים ראשם]\u0006 ויש ההולכים בעטיפה על ראשם תמיד, ואין בזה סימן ברור לאבילות!","ומשיבים: \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר שמואל: כל קרע שאינו בשעת חימום\u0004 בשעת עיקר הצער והכאב של האבל, בשעת מיתה — \u0003אינו קרע,\u0004 שהקורע לאחר זמן אינו נחשב. \u0003וכל עטיפה\u0004 של אבל \u0003שאינה כעטיפת ישמעאלים\u0004 העוטפים את ראשם מכל צד — \u0003אינה\u0004 חשובה \u0003עטיפה.\u0004 וכיון שלדעת שמואל האבל מתעטף בעטיפה מיוחדת כעטיפת הישמעאלים, הרי כשנוהג כן בשבת, ניכרת בכך האבילות, שהרי אין שאר האנשים מתעטפים כך כרגיל. ומהי עטיפה זו? \u0003מחוי\u0004 \u0005[\u0006היה \u0005מראה]\u0006 \u0003רב נחמן עד גובי דדיקנא\u0004 \u0005[גומות הזקן],\u0006 כלומר שמכסה בטלית גם את הגומות בלחי, סמוך לזקן.","\u0003אמר ר' יעקב אמר ר' יוחנן: לא שנו\u0004 שצריך האבל להסיר עטיפת ראשו בשבת \u0003אלא שאין לו מנעלים ברגליו\u0004 ובשל כך הוא נראה כאבל, \u0003אבל\u0004 אם \u0003יש לו מנעלים ברגליו — מנעליו מוכיחין עליו\u0004 שאיננו נוהג מנהג אבל.","וחוזרים למה שאמר שמואל \u0003כל קרע שאינו בשעת חימום אינו קרע,\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל: נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב, קרע עליה\u0004 \u0005[עליו]\u0006 \u0003תריסר מני\u0004 \u0005[שנים עשר בגדים].\u0006 \u0003אמר: אזל גברא דהוה מסתפינא מיניה\u0004 \u0005[הלך,\u0006 נפטר \u0005האיש שהייתי מתיירא ממנו]\u0006 מפני חוכמתו. כיוצא בו \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן: נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' חנינא. קרע עליה\u0004 \u0005[עליו]\u0006 \u0003תליסר אצטלי מלתא\u0004 \u0005[שלושה עשר בגדי צמר\u0006 יקר\u0005]\u0006 \u0003אמר: אזל גברא דהוה מסתפינא מיניה\u0004 \u0005[הלך,\u0006 נפטר \u0005האיש שהייתי מתיירא ממנו].\u0006 והרי שמועה זו ששמעו שלא בשעת חימום היתה ובכל זאת קרעו!","ומשיבים: \u0003שאני רבנן\u0004 \u0005[שונים חכמים],\u0006 \u0003כיון דכל שעתא מדכרי שמעתייהו\u0004 \u0005[שבכל שעה נזכרות שמועותיהם,\u0006 הלכותיהם\u0005] —\u0006 \u0003כשעת חימום דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 שצער מותם מתחדש תמיד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר אדא לרבא: אמר תלמידך רב עמרם, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבל, כל שבעה\u0004 ימי האבילות \u0003קורעו\u0004 (הקרע שלו) \u0003לפניו\u0004 כדי שייראה, \u0003ואם בא להחליף\u0004 לבגד אחר — \u0003מחליף, וקורע\u0004 אף אותו. \u0003בשבת, קורעו\u0004 נמצא \u0003לאחוריו, ואם בא להחליף — מחליף, ואינו קורע\u0004 את הבגד השני, משמע שקורעים אף שלא בשעת חימום!","ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 שקורע גם לאחר שעת החימום, הרי היא \u0003בכבוד אביו ואמו,\u0004 שמפני כבודם אין זה נאה שיהא האבל עליהם מהלך בבגד שאינו קרוע.","ושואלים: \u0003אותן קרעין\u0004 נוספים שקורע מפני הכבוד \u0003מתאחין,\u0004 האם מותר לתופרם תפירה יפה ומדוייקת לאחר זמן האבל, \u0003או אין מתאחין\u0004 כלל כקרע שקרע על אביו ואמו בשעת חימום? ועונים: שבדבר זה \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב אושעיא, ובר קפרא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין מתאחין, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מתאחין.\u0004","ומעירים, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 \u0003דאבוה\u0004 \u0005[שאביו]\u0006 של \u0003רב אושעיא\u0004 הוא ש\u0003אמר אין מתאחין.\u0004 שהרי \u0003אמר רב אושעיא: אין מתאחין,\u0004 ולכאורה \u0003ממאן שמיע ליה\u0004 \u0005[ממי שמע\u0006 הלכה זו\u0005]\u0006 — \u0003לאו מאבוה\u0004 \u0005[\u0006האם \u0005לא מאביו]?\u0006 ודוחים: \u0003לא\u0004 מכאן אין להוכיח, שמא \u0003מבר קפרא רביה\u0004 \u0005[רבו]\u0006 \u0003שמיע ליה\u0004 \u0005[שמע אותה].\u0006","\u0003אמר רבא: אבל מטייל באונקלי\u0004 (חלוק) קרוע \u0003בתוך ביתו\u0004 בשבת, כיון שאין הדבר בפרהסיה. ומספרים: \u0003אביי אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב יוסף\u0004 בשבת בשעת אבלו \u0003דפריס ליה סודרא ארישיה ואזיל ואתי בביתיה\u0004 \u0005[שפרוס סודר על ראשו\u0006 בעטיפת אבילות \u0005והיה הולך ובא בביתו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו סבר לה מר\u0004 \u0005[האם אין אדוני סבור]\u0006 ש\u0003אין אבילות בשבת? אמר ליה\u0004 \u0005[לו]\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: דברים שבצינעא נוהג,\u0004 וכיון שהוא בביתו — צריך לנהוג אבילות אף בשבת.","שנינו במשנה כי \u0003ר' אליעזר אומר: משחרב בית המקדש עצרת\u0004 (חג השבועות) \u0003כשבת\u0004 ואינה נחשבת לשבעה ימים. ורבן גמליאל אומר: אפילו ראש השנה ויום הכיפורים דינם כרגלים. \u0003אמר רב גידל בר מנשיא אמר שמואל: הלכה כרבן גמליאל.\u0004","\u0003ואיכא דמתני להא\u0004 \u0005[ויש ששונים\u0006 פסיקה \u0005זו\u0006 שאמר\u0005]\u0006 \u0003רב גידל בר מנשיא אהא\u0004 \u0005[על\u0006 הלכה \u0005זו].\u0006 ששנינו: \u0003כל שלשים יום\u0004 סמוך ללידתו, אם מת ה\u0003תינוק — יוצא\u0004 להיקבר \u0003בחיק,\u0004 שנושאים אותו בידים בלבד ולא בארון, \u0003ונקבר באשה אחת ושני אנשים\u0004 ואין צורך בעשרה. \u0003אבל לא\u0004 יוליכו אותו \u0003באיש אחד ושתי נשים\u0004 משום איסור יחוד עם האשה."],["\u0003אבא שאול אומר: אף באיש אחד ושתי נשים,\u0004 שבשעת אבילות אין לחשוש לכך. \u0003ו\u0004על תינוק קטן כזה \u0003אין עומדין עליו בשורה\u0004 שאין מנחמים את האבלים העוברים בין המלווים כפי שעושים במת אחר. \u0003ואין אומרים עליו ברכת אבלים\u0004 שמברכים ברחבה מיוחדת הסמוכה לבית הקברות \u0003ו\u0004לא \u0003תנחומי אבלים.\u0004","תינוק \u0003בן שלשים\u0004 יום והלאה שמת \u0003יוצא בדלוסקמא\u0004 (בארון מתים). \u0003ר' יהודה אומר: לא דלוסקמא\u0004 קטנה \u0003הניטלת בכתף\u0004 של אדם אחד, \u0003אלא הניטלת באגפיים\u0004 (בידים) על ידי שני אנשים. \u0003ועומדין עליו בשורה, ואומרים עליו ברכת אבלים ותנחומי אבלים.\u0004","\u0003בן שנים עשר חדש — יוצא במטה\u0004 כפי שמוציאים אדם מבוגר. \u0003ר' עקיבא אומר:\u0004 רק אם \u0003הוא,\u0004 התינוק שמת, \u0003בן שנה ואבריו כבן שתים\u0004 שהיה נראה כגדול, או \u0003הוא בן שתים ואבריו כבן שנה — יוצא במטה,\u0004","\u0003ר' שמעון בן אלעזר אומר: היוצא במטה — רבים מצהיבין\u0004 (מצטערים) \u0003עליו, אינו יוצא במטה — אין רבים מצהיבין עליו. ר' אלעזר בן עזריה אומר,\u0004 הכלל הוא: אם היה התינוק \u0003ניכר לרבים,\u0004 שהיה רגיל כבר לצאת מן הבית, ורבים יודעים עליו — \u0003רבים מתעסקים עמו\u0004 בהלוייתו, \u0003אינו ניכר לרבים — אין רבים מתעסקים עמו.\u0004","ושואלים: \u0003ומה הן\u0004 דיני התינוקות \u0003ב\u0004ענין \u0003הספד? ר' מאיר בשם ר' ישמעאל אומר:\u0004 בני \u0003עניים\u0004 מספידים אותם כשבמותם היו כבר \u0003בני שלש,\u0004 כי העני שאין לו שמחות אחרות מצטער על בניו יותר מן העשיר. בני \u0003עשירים —\u0004 כשהיו במותם \u0003בני חמש. ר' יהודה אומר משמו\u0004 של רבי ישמעאל: \u0003עניים — בני חמש, עשירים — בני שש.\u0004 ומעירים: \u0003ובני זקנים כבני עניים,\u0004 שהרי גם הם מצטערים ביותר על ילדים שמתו להם בזקנותם.","\u0003אמר רב גידל בר מנשיא אמר רב: הלכה כר' יהודה שאמר משום\u0004 (בשם) \u0003ר' ישמעאל.\u0004","\u0003דרש ר' ענני בר ששון אפיתחא דבי נשיאה\u0004 \u0005[על פתחו של בית הנשיא]:\u0006 מי שמת לו מת סמוך לחג השבועות, כיון שהתאבל \u0003יום אחד לפני עצרת\u0004 (שבועות) \u0003ו\u0004גם ב\u0003עצרת\u0004 עצמה \u0003הרי כאן ארבעה עשר.\u0004 שהיום שלפני העצרת נחשב כשבעה ימי אבל שלמים (שהרי החג הפסיק את האבילות) והעצרת עצמה נחשבת כרגל בן שבעה ימים, ואף שאין בה בפועל שבעה ימים, כיון שדינה כרגל (ראה לעיל מועד קטן כ, א) — נחשבת היא לענין ימי אבילות כשבעה, וממילא, הרי זה כאילו עברו שבועיים ונשארו עוד שבועיים לאבילות שלושים. \u0003שמע\u0004 זאת \u0003ר' אמי ואיקפד\u0004 \u0005[הקפיד\u0006 עליו\u0005],\u0006 \u0003אמר: אטו דידיה\u0004 \u0005[וכי שלו]\u0006 \u0003היא\u0004 הלכה זו? הלא של \u0003ר' אלעזר אמר ר' אושעיא היא!\u0004","וכיוצא בזה \u0003דרש ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003אקילעא דריש גלותא\u0004 \u0005[באהל של ראש הגולה]:\u0006 \u0003יום אחד לפני עצרת ועצרת — הרי כאן ארבעה עשר. שמע רב ששת איקפד\u0004 \u0005[הקפיד\u0006 עליו\u0005],\u0006 \u0003אמר: אטו דידיה\u0004 \u0005[וכי שלו]\u0006 \u0003היא\u0004 הלכה זו? הלא של \u0003ר' אלעזר אמר ר' אושעיא היא,\u0004 שעל דבריו סמכו חכמים אלה, ולא פירשו בשמו!","ש\u0003אמר ר' אלעזר אמר ר' אושעיא: מנין לעצרת שיש לה תשלומין כל שבעה,\u0004 ששישה ימים אחר עצרת אפשר עוד להקריב את קרבנות החג — \u0003שנאמר: \"בחג המצות ובחג השבעות\"\u0004 (דברים טז, טז), \u0003מה חג המצות יש לה תשלומין כל שבעה,\u0004 שהרי יש שבעה ימים של חג הפסח — \u0003אף חג השבועות יש לה תשלומין כל שבעה\u0004 בימים שלאחר החג. ומכאן למדים שדין שבועות כדין רגל של שבעת ימים לכל דבר.","\u0003אדבריה\u0004 \u0005[\u0006נתן \u0005רשות]\u0006 \u0003רב פפא לרב אויא סבא ודרש\u0004 ברבים כך: אם התאבל \u0003יום אחד לפני ראש השנה וראש השנה\u0004 עצמו — \u0003הרי כאן ארבעה עשר\u0004 יום, שאף ראש השנה נחשב כרגל. \u0003אמר רבינא: הלכך\u0004 (על כן), המתאבל \u0003יום אחד לפני החג\u0004 (הסוכות) \u0003ו\u0004ה\u0003חג\u0004 עצמו שהוא שבעה ימים, \u0003ושמיני שלו\u0004 (שמיני עצרת) שהוא רגל בפני עצמו — \u0003הרי כאן עשרים ואחד יום\u0004 ומשלים רק את הימים הנותרים לשלושים ימי אבל.","מסופר: \u0003רבינא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003סורא\u0004 שעל נהר \u0003פרת, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבא מסורא\u0004 שעל ה\u0003פרת לרבינא:\u0004 וכי \u0003אמר מר\u0004 \u0005[אדוני]\u0006 ש\u0003יום אחד לפני ראש השנה וראש השנה הרי כאן ארבעה עשר? אמר ליה\u0004 \u0005[לו]:\u0006 לא פסקתי הלכה כך, אלא \u0003אנא, מסתברא\u0004 \u0005[אני, מסתבר]\u0006 \u0003כרבן גמליאל הוא דאמינא\u0004 \u0005[שאמרתי],\u0006 והוא סבור שראש השנה דינו כרגל, אבל לא פסקתי הלכה.","\u0003אין קורעין\u0004 בחול המועד, \u0003ולא חולצין\u0004 כתף מן הבגד שעליה \u0003ואין מברין\u0004 (מאכילים את הארוחה הראשונה לאחר הקבורה) \u0003אלא קרוביו של מת\u0004 ולא אחרים שאינם קרוביו, \u0003ואין\u0004 המנחמים \u0003מברין אלא על מטה זקופה\u0004 ואינם יושבים על מיטה כפויה."],["נאמר במשנה שאין קורעין אלא קרוביו של המת, ושואלים: \u0003ואפילו\u0004 אם היה המת \u0003חכם? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חכם שמת — הכל קרוביו.\u0004","ותוהים: \u0003הכל קרוביו סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003אלא\u0004 כך יש להבין: \u0003הכל\u0004 נוהגים \u0003כקרוביו,\u0004 כלומר: \u0003הכל קורעין עליו, והכל חולצין עליו, והכל מברין עליו ברחבה\u0004 שליד בית הקברות! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 המשנה אלא באדם \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003חכם הוא.\u0004","ועוד שואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אדם כשר\u0004 (ירא שמים ובעל מעשים טובים) \u0003הוא — חיובי מיחייב למיקרע\u0004 \u0005[חייבים\u0006 הכל \u0005לקרוע]\u0006 עליו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מפני מה בניו ובנותיו של אדם מתים כשהן קטנים — כדי שיבכה ויתאבל על אדם כשר\u0004 שמת.","ותוהים על הלשון: כדי ש\u0003יבכה ויתאבל?!\u0004 וכי \u0003ערבונא קא שקיל מיניה\u0004 \u0005[ערבון לוקחים ממנו]\u0006 שממיתים את בניו כדי שיתאבל לאחר מכן?! \u0003אלא\u0004 כך צריך לומר: בניו מתים \u0003מפני שלא בכה והתאבל על אדם כשר\u0004 שמת. \u0003שכל הבוכה ומתאבל על אדם כשר — מוחלין לו על כל עונותיו בשביל כבוד שעשה לו,\u0004 ואם כן יש לקרוע עליו! ומשיבים: צריכים לומר שמשנתנו מדברת באדם \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003אדם כשר הוא.\u0004","ועוד שואלים: \u0003אי דקאי התם\u0004 \u0005[אם עומד שם]\u0006 \u0003בשעת יציאת נשמה —\u0004 הלא \u0003חיובי מיחייב\u0004 \u0005[חייב]\u0006 כל אדם לקרוע! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: העומד על המת בשעת יציאת נשמה — חייב לקרוע. למה\u0004 דבר \u0003זה דומה — לספר תורה שנשרף, שחייב\u0004 כל הרואה זאת \u0003לקרוע!\u0004","ומשיבים: במשנה מדובר \u0003דלא קאי התם\u0004 \u0005[שאינו עומד שם]\u0006 \u0003בשעת יציאת נשמה,\u0004 אלא רק שמע שמת אדם שאינו קרובו, ואינו חכם או אדם כשר.","מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב ספרא, לא קרעו רבנן עליה\u0004 \u0005[חכמים עליו],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003לא גמרינן מיניה\u0004 \u0005[למדנו ממנו],\u0006 שהוא לא היה מרביץ תורה ברבים. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: מי תניא\u0004 \u0005[האם שנינו\u0006 בברייתא\u0005]\u0006 \u0003\"הרב שמת\"?\u0004 הלא \u0003\"חכם שמת\" תניא\u0004 \u0005[שנינו],\u0006 ובודאי היה רב ספרא חכם. \u0003ועוד: כל יומא\u0004 \u0005[יום]\u0006 \u0003שמעתתיה בפומין בבי מדרשא\u0004 \u0005[שמועותיו\u0006 מצויות \u0005בפינו בבית המדרש],\u0006 ואם כן אף שלא למדו ממנו במישרין, תלמידיו הם.","\u0003סבור\u0004 \u0005[סברו]:\u0006 \u0003מה דהוה הוה\u0004 \u0005[שהיה היה]\u0006 ואי אפשר לתקן עוד. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי, תנינא\u0004 \u0005[שנינו]:\u0006 \u0003חכם, כל זמן שעוסקין בהספד\u0004 עליו — \u0003חייבין לקרוע\u0004 אפילו שלא בשעת מיתה. \u0003סבור למיקרע לאלתר\u0004 \u0005[חשבו לקרוע מיד],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חכם כבודו בהספידו\u0004 וצריך להמתין עד שעת ההספד לקרוע אז עליו.","אגב כך מסופר מעשה דומה במקצת: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב הונא, סבור לאותובי\u0004 \u0005[חשבו להניח]\u0006 \u0003ספר תורה אפורייה\u0004 \u0005[על מיטתו],\u0006 שהיו נוהגים לעשות זאת לחכם שמת ולומר: קיים זה מה שכתוב בזה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא: מילתא דבחייה לא סבירא ליה, השתא ליקום ליה ליעבד ליה\u0004 \u0005[דבר שבחייו לא היה סבור כן, עכשיו נקום ונעשה לו]?\u0006 ש\u0003אמר רב תחליפא: אנא חזיתיה\u0004 \u0005[אני ראיתי אותו]\u0006 את \u0003רב הונא דבעי למיתב אפורייה\u0004 \u0005[שהיה רוצה לשבת על מיטתו],\u0006 \u0003והוה מנח\u0004 \u0005[והיה מונח]\u0006 \u0003ספר תורה עליה\u0004 \u0005[עליה],\u0006 \u0003וכף כדא אארעא\u0004 \u0005[והפך כד על הארץ]\u0006 \u0003ואותיב\u0004 \u0005[והניח]\u0006 \u0003ספר תורה עילויה\u0004 \u0005[עליו]\u0006 ורק אחר כך ישב על המיטה. \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 ש\u0003אסור לישב על גבי מטה שספר תורה מונח עליה.\u0004 ואין זה נאה לעשות לו כן אחר מותו.","כשרצו להוציאו מביתו לקבורה \u0003לא הוה נפיק פוריא מבבא\u0004 \u0005[לא היתה המיטה יוצאת מן הדלת]\u0006 שהיתה הדלת צרה, \u0003סבור לשלשולי\u0004 \u0005[חשבו לשלשל]\u0006 את המיטה \u0003דרך גגין\u0004 \u0005[הגג]\u0006 מלמעלה, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא: הא גמירנא מיניה\u0004 \u0005[הרי למדתי ממנו]:\u0006 \u0003חכם, כבודו\u0004 שמוציאים את מיטתו \u0003דרך\u0004 ה\u0003פתח,\u0004 ולא באופן אחר.","\u0003סבור לאשנויי מפוריא לפוריא\u0004 \u0005[רצו לשנות ממיטה למיטה\u0006 צרה יותר\u0005]\u0006 שתוכל לצאת בפתח, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא: הכי גמירנא מיניה\u0004 \u0005[כך למדתי ממנו]:\u0006 \u0003חכם כבודו במטה ראשונה.\u0004 ש\u0003אמר רב יהודה אמר רב: מנין לחכם שכבודו במטה ראשונה — שנאמר: \"וירכבו את ארון האלהים אל עגלה חדשה\"\u0004 (שמואל ב' ו, ג), שהביאו את הארון לירושלים באותה עגלה שבה הובא לקרית יערים, ודינו של החכם כארון הברית. וכיון שלא היתה דרך אחרת \u0003פרוס בבא ואפקוה\u0004 \u0005[שברו\u0006 את \u0005השער והוציאוהו\u0006 דרכו\u0005].\u0006","\u0003פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ר' אבא\u0004 בהספד: \u0003ראוי היה רבינו שתשרה עליו שכינה, אלא שבבל גרמה ליה\u0004 \u0005[לו].\u0006 שרק משום שלא היה בארץ ישראל לא שרתה שכינה עליו.","\u0003מתיב\u0004 \u0005[הקשה]\u0006 על כך באותה שעה \u0003רב נחמן בר חסדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב חנן בר חסדא:\u0004 הלא נאמר \u0003\"היה היה דבר ה' אל יחזקאל בן בוזי הכהן בארץ כשדים\"\u0004 (יחזקאל א, ג), משמע שנביא יכול לנבא גם בחוץ לארץ!","\u0003טפח ליה אבוה\u0004 \u0005[אביו]\u0006 \u0003בסנדליה\u0004 \u0005[טפח לו אביו בסנדלו]\u0006 על רגלו, לרמוז לו שישתוק, ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אמינא לך לא תיטרוד עלמא\u0004 \u0005[האם לא אמרתי לך שלא תטריד\u0006 את \u0005הציבור]\u0006 בשאלות בתוך ההספד? והתשובה לקושיה זו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"היה\" — שהיה כבר.\u0004 כלומר, שכבר היה נביא עוד בהיותו בארץ ישראל ורק המשיך את נבואתו בבבל.","מספרים: \u0003כי אסקוה להתם\u0004 \u0005[כאשר העלו אותו\u0006 את רב הונא \u0005לשם]\u0006 לארץ ישראל, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לר' אמי ולר' אסי: רב הונא אתי\u0004 \u0005[בא]\u0006 וחשבו שהוא בא בעצמו. \u0003אמרו: כי הוינן התם לא הוה לן לדלויי רישין מיניה\u0004 \u0005[כאשר היינו שם\u0006 בבבל \u0005לא היה\u0006 לנו \u0005כח להרים ראשינו בפניו] —\u0006 \u0003השתא אתינן הכא, אתא בתרין\u0004 \u0005[עכשיו באנו לכאן,\u0006 הוא \u0005בא אחרינו]?\u0006","\u0003אמרו להו\u0004 \u0005[להם]:\u0006 \u0003ארונו בא. ר' אמי ור' אסי נפוק\u0004 \u0005[יצאו\u0006 לקראתו\u0005],\u0006 \u0003ר' אילא ור' חנינא לא נפוק\u0004 \u0005[יצאו].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003ר' אילא נפק\u0004 \u0005[יצא],\u0006 \u0003ר' חנינא לא נפק\u0004 \u0005[יצא].\u0006","ושואלים: \u0003דנפק מאי טעמיה\u0004 \u0005[\u0006זה \u0005שיצא מה טעם]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארון העובר ממקום למקום — עומדים עליו בשורה, ואומרים עליו ברכת אבלים, ותנחומי אבלים.\u0004 זה ש\u0003לא נפק\u0004 \u0005[יצא]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא יצא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארון העובר ממקום למקום — אין עומדין עליו בשורה, ואין אומרים עליו ברכת אבלים, ותנחומי אבלים.\u0004","ושואלים: אם כן \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 הברייתות \u0005זו על זו]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן — ששלדו קיימת —\u0004 צריכים לנהוג בו מנהג אבילות, \u0003כאן בשאין שלדו קיימת\u0004 — אין צריך לנהוג בו מנהגי אבלות, \u0003ורב הונא שלדו קיימת הוה\u0004 \u0005[היה],\u0006 \u0003דלא נפק לא סיימוה קמיה\u0004 \u0005[\u0006וזה \u0005שלא יצא, לא גמרו\u0006 לברר \u0005לו\u0006 את הדבר\u0005]\u0006 שעדיין שלדו קיימת.","\u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמי ארץ ישראל: \u0003היכא נינחיה\u0004 \u0005[היכן נניח אותו,\u0006 היכן נקברהו\u0005]?\u0006 והחליטו: \u0003רב הונא ריבץ תורה בישראל ור' חייא ריבץ תורה בישראל הוה\u0004 \u0005[היה],\u0006 ולכן ראוי לקוברו לידו.","ושאלו: \u0003מאן מעייל ליה\u0004 \u0005[מי יכניס אותו]\u0006 למערת הקבר של ר' חייא? שלא הכל ראויים להיכנס לשם. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חגא: אנא מעיילנא ליה\u0004 \u0005[אני אכניס אותו\u0006 לשם\u0005],\u0006 \u0003דאוקמתיה לתלמודאי כי הוינא בר תמני סרי שנין ולא חזי לי קרי\u0004 \u0005[שהעמדתי את תלמודי,\u0006 שהיה סדור בידי, \u0005כשהייתי\u0006 כבר \u0005בן שמונה עשרה שנה ולא ראיתי קרי],\u0006 \u0003ו\u0004כן גם \u0003משמע ליה קמיה, וידעי בעובדיה\u0004 \u0005[והייתי משמש לפניו, וידעתי במעשיו]\u0006 הגדולים, דוגמה לדבר, \u0003דיומא חד אתהפיכא ליה\u0004 \u0005[שיום אחד התהפכה לו]\u0006 \u0003רצועה\u0004 של \u0003תפילין\u0004 שהיה הצד שאינו צבוע נראה החוצה \u0003ויתיב עלה ארבעין תעניתא\u0004 \u0005[וישב על כך ארבעים תעניות]\u0006 על שלא נהג כראוי, מפני שהצד השחור של הרצועה צריך להיות מבחוץ.","\u0003עייליה\u0004 \u0005[הכניס אותו\u0006 רב חגא לשם\u0005],\u0006 \u0003הוה גני\u0004 \u0005[היה שוכב]\u0006 בקבר \u0003יהודה\u0004 בן רבי חייא \u0003מימיניה דאבוה\u0004 \u0005[מימין אביו]\u0006 \u0003וחזקיה\u0004 בנו \u0003משמאליה\u0004 \u0005[משמאלו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003יהודה לחזקיה: קום מדוכתיך\u0004 \u0005[ממקומך],\u0006 \u0003דלאו אורח ארעא דקאים\u0004 \u0005[שאין זה דרך ארץ שעומד כאן]\u0006 \u0003רב הונא, בהדי דקאים\u0004 \u0005[כאשר קם]\u0006 — \u0003קם בהדיה\u0004 \u0005[עמו]\u0006 \u0003עמודא דנורא\u0004 \u0005[עמוד של אש],\u0006 \u0003חזייה\u0004 \u0005[\u0006כש\u0005ראה זאת]\u0006 \u0003רב חגא, איבעית\u0004 \u0005[נבהל],\u0006 \u0003זקפיה לארוניה ונפק אתא\u0004 \u0005[זקף את ארונו\u0006 של רב הונא \u0005ויצא ובא].\u0006 ומעירים: \u0003והאי דלא איענש ענש\u0004 \u0005[וזה שלא נענש]\u0006 ולא ניזוק מעמוד האש הזה, \u0003משום דזקפיה לארוניה\u0004 \u0005[שזקף את ארונו]\u0006 של \u0003רב הונא\u0004 כהגנה לפניו.","ועוד מעשים על קבורת החכמים. \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב חסדא, סבור לאותובי\u0004 \u0005[חשבו להניח]\u0006 \u0003ספר תורה אפורייה\u0004 \u0005[על מיטתו],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יצחק: מילתא דלרביה לא סבירא ליה, אנן ניקום נעביד ליה\u0004 \u0005[דבר שעל רבו לא היה מקובל, אנחנו נעמוד ונעשה לו]?\u0006","\u0003סבור דלא למישלל קרעייהו\u0004 \u0005[חשבו שלא לחבר את הקרעים\u0006 שבבגדיהם\u0005].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יצחק בר אמי:\u0004 כשהנפטר הוא \u0003חכם, כיון שהחזירו פניהם מאחורי המטה — שוללין.\u0004","ומסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבה בר הונא ורב המנונא אסקינהו להתם\u0004 \u0005[העלו אותם לשם,\u0006 לארץ ישראל\u0005].\u0006"],["\u0003כי מטו אגישרא\u0004 \u0005[כאשר הגיעו לגשר]\u0006 שבו היו יכולים לעבור רק בזה אחר זה, \u0003קמו גמלי\u0004 \u0005[עמדו הגמלים]\u0006 ולא עברו. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ההוא טייעא\u0004 \u0005[ערבי אחד]\u0006 שהיה שם: \u0003מאי האי\u0004 \u0005[מהו זה]\u0006 שאין הגמלים זזים? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003רבנן דקא עבדי יקרא אהדדי\u0004 \u0005[חכמים,\u0006 המתים, הם \u0005שעושים כבוד זה לזה],\u0006 \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003אמר: מר ניעול ברישא\u0004 \u0005[אדוני יכנס,\u0006 יעבור \u0005בראש],\u0006 \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003אמר: מר ניעול ברישא\u0004 \u0005[אדוני יכנס,\u0006 יעבור \u0005בראש].\u0006 \u0003אמר\u0004 הערבי: \u0003דינא\u0004 \u0005[בדין]\u0006 \u0003הוא\u0004 ש\u0003רבה בר הונא ליעול ברישא\u0004 \u0005[יכנס בראש],\u0006 שכן הוא בנו של אדם גדול. ואכן \u0003חליף גמליה\u0004 \u0005[חלף\u0006 תחילה \u0005גמלו]\u0006 של \u0003רבה בר הונא,\u0004 אולם \u0003נתור ככיה ושניה דההוא טייעא\u0004 \u0005[נפלו חניכיו ושיניו של אותו ערבי]\u0006 משום שגרם ביזיון לרב המנונא.","כאשר הגיעו לטבריה \u0003פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ההוא ינוקא\u0004 \u0005[צעיר אחד]\u0006 בדברי הספד אלה: \u0003גזע ישישים עלה מבבל\u0004 הוא רבה בר רב הונא שהוא בן גדולים, \u0003ועמו ספר מלחמות\u0004 (רב המנונא, הגדול בתורה, הקרויה במליצה \"ספר מלחמות ה' \"), \u0003קאת וקפוד\u0004 שהם כאות וסמל לחורבן (ראה ישעיהו לד, יא) \u0003הוכפלו, לראות בשוד ושבר הבא משנער\u0004 (מבבל). \u0003קצף\u0004 ה' \u0003על עולמו וחמס ממנו נפשות, ו\u0004הוא \u0003שמח בהם\u0004 כאשר הם מגיעים אליו \u0003ככלה חדשה. רוכב ערבות\u0004 (= ה') \u0003שש ושמח בבא אליו נפש נקי וצדיק.\u0004","ועוד מספרים על הספדים מפורסמים. \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבינא, פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ההוא ספדנא\u0004 \u0005[ספדן אחד]\u0006 את הספדו בדברים הללו: \u0003תמרים הניעו ראש\u0004 בעצב \u0003על צדיק כתמר, נשים לילות כימים\u0004 בבכי, \u0003על\u0004 אדם שהיה \u0003משים לילות כימים\u0004 בלימוד התורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לבר קיפוק\u0004 שהיה ספדן מפורסם: \u0003ההוא יומא מאי אמרת\u0004 \u0005[באותו יום\u0006 שמת רבינא \u0005מה תאמר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמינא\u0004 \u0005[אומר]\u0006 ואפתח \u0003אם בארזים נפלה שלהבת — מה יעשו איזובי קיר? לויתן בחכה הועלה — מה יעשו דגי רקק? בנחל שוטף נפלה חכה — מה יעשו מי גבים\u0004 (שלוליות)?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר אבין\u0004 שהיה גם הוא ספדן: \u0003חס ושלום,\u0004 שלשון \u0003חכה ושלהבת בצדיקי אמינא\u0004 \u0005[בצדיקים אומר],\u0006 שאינם לשון כבוד להם. שאל אותו רב אשי: \u0003ומאי אמרת\u0004 \u0005[ומה תאמר אתה]?\u0006 ענה לו: \u0003אמינא\u0004 \u0005[אומר]\u0006 \u0003בכו לאבלים ולא לאבידה, שהיא,\u0004 האבידה, הנשמה, הלכה \u0003למנוחה ואנו\u0004 האבלים \u0003לאנחה.\u0004","\u0003חלש דעתיה עלייהו\u0004 \u0005[נחלשה דעתו,\u0006 נעלב רב אשי \u0005עליהם,\u0006 בגללם\u0005]\u0006 משום שמלשונות הספד אלה נראו לו שכאילו ממעטים בכבודו שלו שמדמים את שאר החכמים לאיזובי קיר לעומת רבינא המוזכר כארז, וגרמה הקפדתו שאירע להם \u0003ואתהפוך כרעייהו\u0004 \u0005[שנהפכו\u0006 והתעקמו \u0005רגליהם].\u0006 \u0003ההוא יומא\u0004 \u0005[באותו יום]\u0006 שמת רבינא \u0003לא אתו\u0004 \u0005[באו]\u0006 שניהם \u0003לאספודיה\u0004 \u0005[להספידו].\u0006 \u0003והיינו\u0004 \u0005[והוא]\u0006 ש\u0003אמר רב אשי\u0004 עליהם לענין הלכה אחרת: \u0003לא בר קיפוק חליץ\u0004 \u0005[\u0006יכול \u0005לחלוץ]\u0006 \u0003ולא בר אבין חליץ\u0004 \u0005[\u0006יכול \u0005לחלוץ],\u0006 משום שרגליהם עקומות באופן שאי אפשר שיחלצו מעליהם את הנעלים כדין.","\u0003רבא כי הוה אתא לדגלת\u0004 \u0005[כאשר היה מגיע ל\u0006נהר \u0005חידקל],\u0006 כשחששו מפני השיטפון \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לבר אבין: קום אימא מילתא\u0004 \u0005[עמוד\u0006 ו\u0005אמור דבר]\u0006 של תפילה, \u0003קאי\u0004 \u0005[עמד]\u0006 \u0003ואמר: באו רוב שלישית במים,\u0004 ו\"שלישית\" הוא כינוי מליצי לעם ישראל (ראה ישעיהו יט, כד) ורבא שקול כנגד רוב ישראל והוא חושש מפני השיטפון, לכן \u0003זכור ורחם\u0004 עלינו, אף כי \u0003תעינו מאחריך כאשה מבעלה, אל תזניחנו\u0004 ותענישנו \u0003כאות מי מרה\u0004 כמים המרים שאשה סוטה נבדקת בהם, ואל תענישנו במים.","ובענין הספדם של צדיקים הבאים: \u0003חנין, יוחנן, זירא, אבא, יעקב, יוסי, שמואל, חייא\u0004 ו\u0003מנחם\u0004 הם ה\u0003סימן\u0004 לסיפורים שיפורטו.","מסופר: \u0003ר' חנין, חתניה דבי נשיאה הוה\u0004 \u0005[חתנו של בית הנשיא היה],\u0006 \u0003לא קא הוו ליה בני\u0004 \u0005[לא היו לו בנים,\u0006 ילדים\u0005],\u0006 \u0003בעא רחמי והוו ליה\u0004 \u0005[ביקש רחמים, והיו לו].\u0006 \u0003ההוא יומא דהוה ליה, נח נפשיה\u0004 \u0005[אותו יום שנולד לו\u0006 בן, \u0005נחה נפשו,\u0006 נפטר\u0005],\u0006 \u0003פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ההוא ספדנא\u0004 \u0005[ספדן אחד]\u0006 במילים אלה: \u0003שמחה לתוגה נהפכה, ששון ויגון נדבקו, בעת שמחתו נאנח, בעת חנינתו\u0004 בבנים \u0003אבד חנינו. אסיקו ליה\u0004 \u0005[\u0006ו\u0005קראו לו]\u0006 לילד \u0003חנן על שמיה\u0004 \u0005[שמו]\u0006 של האב.","\u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' יוחנן, פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ר' יצחק בן אלעזר\u0004 את הספדו במילים: \u0003קשה היום לישראל כיום בא השמש בצהרים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה ביום ההוא\u0004 נאום ה' אלהים \u0003והבאתי השמש בצהרים\u0004 והחשכתי לארץ ביום אור. והפכתי חגיכם לאבל וכל שיריכם לקינה והעליתי על כל מתנים שק ועל כל ראש קרחה ושמתיה כאבל יחיד ואחריתה כיום מר\u0003\"\u0004 (עמוס ח, ט-י) \u0003ואמר ר' יוחנן: זה יומו של יאשיהו\u0004 (היום שבו נהרג) הרי שצדיק הדור קרוי \"שמש\".","מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' יוחנן, יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אמי\u0004 עליו באבל כמו על קרוב משפחה \u0003שבעה ושלשים. אמר ר' אבא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא בר אבא: ר' אמי\u0004 מה \u0003דעבד\u0004 \u0005[שעשה] —\u0006 \u0003לגרמיה\u0004 \u0005[לעצמו]\u0006 \u0003הוא דעבד\u0004 \u0005[שעשה],\u0006 שאין זו הלכה שיש לנהוג כמותה, \u0003דהכי\u0004 \u0005[שכך]\u0006 \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 אם מת \u0003אפילו רבו שלימדו חכמה — אינו יושב עליו אלא יום אחד\u0004 ולא יותר.","ועוד לענין הספד, מסופר: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' זירא, פתח עליה\u0004 \u0005[עליו]\u0006 \u0003ההוא ספדנא\u0004 \u0005[ספדן אחד]:\u0006 \u0003ארץ שנער\u0004 (בבל) \u0003הרה וילדה\u0004 אותו, שכן היה בבלי במקורו, \u0003ארץ צבי\u0004 (ארץ ישראל) \u0003גידלה שעשועיה\u0004 של בבל, שאחר כך עלה לארץ ישראל וגדל בה, \u0003אוי נא לה אמרה רקת\u0004 (היא טבריה) \u0003כי אבדה כלי חמדתה.\u0004","ומסופר עוד על פטירתם של צדיקים: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' אבהו אחיתו עמודי דקסרי מיא\u0004 \u0005[הורידו עמודי\u0006 עירו \u0005קיסרי מים]\u0006 כאילו היו בוכים עליו. כשנפטר \u0003ר' יוסי שפעו מרזבי ציפורי\u0004 עירו \u0003דמא\u0004 \u0005[דם].\u0006 כשנפטר \u0003ר' יעקב אתחמיאו כוכבי ביממא\u0004 \u0005[נראו כוכבים ביום].\u0006 כשנפטר \u0003ר' אסי איעקרו\u0004 \u0005[נעקרו]\u0006 \u0003כל אילניא\u0004 \u0005[האילנות]\u0006 בסערה. כשנפטר \u0003ר' חייא נחיתו כיפי דנורא מרקיעא\u0004 \u0005[ירדו סלעים של אש מן השמים].\u0006 כשנפטר \u0003ר' מנחם בר' יוסי אישתעו צלמנייא והוו למחלצייא\u0004 \u0005[הוחלקו\u0006 פרצופי \u0005הצלמים ונעשו\u0006 חלקים כאילו נמעכו \u0005במחלציים].\u0006","בפטירתו של \u0003ר' תנחום בר חייא איתקצצו כל אנדרטיא\u0004 \u0005[נתקצצו כל האנדרטות\u0006 של המלך\u0005].\u0006 בפטירתו של \u0003ר' אלישיב איחתרו שבעין מחתרתא\u0004 \u0005[נחתרו שבעים מחתרות\u0006 של גנבים\u0005]\u0006 \u0003בנהרדעא,\u0004 משום שכל עוד חי גרמה זכותו שלא היו גנבים, בפטירתו של \u0003רב המנונא נחיתו כיפי דברדא מרקיעא\u0004 \u0005[ירדו אבני ברד מן השמים].\u0006 בפטירתם של \u0003רבה ורב יוסף נשוק כיפי\u0004 \u0005[נשקו,\u0006 נשברו ונגעו, ראשי \u0005הגשרים]\u0006 של ה\u0003פרת אהדדי\u0004 \u0005[זה בזה].\u0006 בפטירתם של \u0003אביי ורבא נשוק כיפי דדגלת אהדדי\u0004 \u0005[נשקו,\u0006 נגעו, ראשי \u0005גשרי החידקל זה בזה].\u0006 \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' משרשיא טעון דיקלי שיצי\u0004 \u0005[טענו הדקלים קוצים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006"]]};
